import 'nuclo'

let count = 0

export function Counter() {
  return div(
    p(() => count),
    p("COUNT"),
    button("-", { onClick: () => { count--; update() } }),
    button("Reset", { onClick: () => { count = 0; update() } }),
    button("+", { onClick: () => { count++; update() } }),
  )
}

import 'nuclo'

interface Todo {
  id: number
  text: string
  done: boolean
}

let todos: Todo[] = []
let filter: "all" | "active" | "done" = "all"
let text = ""
let nextId = 1

function visible() {
  if (filter === "active") return todos.filter((t) => !t.done)
  if (filter === "done") return todos.filter((t) => t.done)
  return todos
}

function addTodo() {
  if (!text.trim()) return

  todos.push({ id: nextId++, text, done: false })
  text = ""
  update()
}

// A filter button: pressed while its filter is the active one
function FilterButton(label: string, next: typeof filter) {
  return button(label, {
    "aria-pressed": () => String(filter === next),
    style: () => ({ fontWeight: filter === next ? "700" : "400" }),
    onClick: () => { filter = next; update() },
  })
}

export function TodoList() {
  return div(
    input(
      // value: () => text keeps the input in sync, so Add can clear it
      { placeholder: "Add a task...", value: () => text },
      {
        onInput: (event) => { text = (event.target as HTMLInputElement).value },
        onKeyDown: (event) => { if (event.key === "Enter") addTodo() },
      },
    ),
    button("Add", { onClick: addTodo }),
    div(
      FilterButton("All", "all"),
      FilterButton("Active", "active"),
      FilterButton("Done", "done"),
    ),
    ul(
      list(
        () => visible(),
        (todo) => li(
          input(
            { type: "checkbox", checked: () => todo.done },
            { onChange: () => { todo.done = !todo.done; update() } },
          ),
          span(todo.text, {
            style: () => ({
              textDecoration: todo.done ? "line-through" : "none",
              opacity: todo.done ? "0.6" : "1",
            }),
          }),
          button("✕", {
            "aria-label": "Delete",
            onClick: () => {
              todos = todos.filter((item) => item.id !== todo.id)
              update()
            },
          }),
        ),
      ),
      when(() => visible().length === 0, div("No tasks yet.")),
    ),
    p(() => {
      const left = todos.filter((t) => !t.done).length
      return `${left} of ${todos.length} remaining`
    }),
  )
}

import 'nuclo'

const users = [
  { name: "Alice Chen", email: "alice@example.com", initials: "AC" },
  { name: "Bob Smith", email: "bob@example.com", initials: "BS" },
  { name: "Charlie Davis", email: "charlie@example.com", initials: "CD" },
  { name: "Diana Park", email: "diana@example.com", initials: "DP" },
]
let query = ""

function results() {
  const q = query.toLowerCase()
  if (!q) return users
  return users.filter((user) =>
    user.name.toLowerCase().includes(q) ||
    user.email.toLowerCase().includes(q)
  )
}

export function SearchFilter() {
  return div(
    input(
      { placeholder: "Search users..." },
      {
        onInput: (event) => {
          query = (event.target as HTMLInputElement).value
          update()
        },
      },
    ),
    div(
      list(
        () => results(),
        (user) => div(
          div(user.initials),
          div(user.name),
          div(user.email),
        ),
      ),
      when(() => results().length === 0, div("No users found.")),
    ),
  )
}

