import 'nuclo'

const values = { username: '', email: '', password: '', confirm: '' }
const touched = new Set<keyof typeof values>()
let availability: 'idle' | 'checking' | 'taken' | 'free' = 'idle'
let submitted: string | null = null
const taken = ['ada', 'grace', 'linus'] // stands in for a server

// Validation is a plain function over the state. It runs on every
// update(), so the messages are always current.
const errors = () => ({
  username:
    values.username.length < 3 ? 'At least 3 characters'
    : availability === 'taken' ? 'Already taken'
    : null,
  email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)
    ? null : 'Enter a valid email',
  password:
    values.password.length < 8 ? 'At least 8 characters'
    : !/\d/.test(values.password) ? 'Include a number'
    : null,
  confirm: values.confirm === values.password ? null : 'Passwords do not match',
})
const valid = () =>
  Object.values(errors()).every((e) => e === null) &&
  availability !== 'checking'

// An async check: debounced, with a pending state the UI can show.
let timer: ReturnType<typeof setTimeout>
function checkUsername() {
  clearTimeout(timer)
  if (values.username.length < 3) { availability = 'idle'; return }
  availability = 'checking'
  timer = setTimeout(() => {
    availability = taken.includes(values.username.toLowerCase()) ? 'taken' : 'free'
    update()
  }, 500)
}

// A field shows its error only once it was touched (blurred):
// red while invalid, green once it passes.
function Field(
  key: keyof typeof values,
  text: string,
  type = 'text',
  placeholder = '',
  hint: () => string = () => '',
) {
  const show = () => touched.has(key) && errors()[key]
  const ok = () => touched.has(key) && !errors()[key]
  return div(
    label(text, ' ', small(hint)),
    input({
      type,
      placeholder,
      value: () => values[key],
      style: () => ({ borderColor: show() ? '#ef4444' : ok() ? '#22c55e' : '' }),
      'aria-invalid': () => String(!!show()),
      onInput: (e) => {
        values[key] = e.currentTarget.value
        if (key === 'username') checkUsername()
        update()
      },
      onBlur: () => { touched.add(key); update() },
    }),
    p({ role: 'alert' }, () => show() || ''),
  )
}

export const SignUp = () =>
  form(
    Field('username', 'Username', 'text', 'ada, grace and linus are taken', () =>
      availability === 'checking' ? 'checking…' : availability === 'free' ? 'available' : ''),
    Field('email', 'Email', 'email', 'you@example.com'),
    Field('password', 'Password', 'password', '8+ characters, one number'),
    Field('confirm', 'Confirm password', 'password'),
    div(
      // Disabled until every rule passes and the async check is done.
      button('Create account', {
        type: 'button',
        disabled: () => !valid(),
        onClick: () => {
          submitted = JSON.stringify({ username: values.username, email: values.email })
          update()
        },
      }),
      small(() => (valid() ? '' : 'Fix the fields above')),
    ),
    when(() => submitted !== null, p('Submitted ', code(() => submitted ?? ''))),
  )

import 'nuclo'

const data = { name: '', email: '', street: '', city: '', zip: '' }
type Key = keyof typeof data
const labels: Record<Key, string> = {
  name: 'Full name', email: 'Email', street: 'Street', city: 'City', zip: 'ZIP',
}
const touched = new Set<Key>()
let step = 0
let done = false

const errors = (): Record<Key, string | null> => ({
  name: data.name.trim() ? null : 'Required',
  email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)
    ? null : 'Enter a valid email',
  street: data.street.trim() ? null : 'Required',
  city: data.city.trim() ? null : 'Required',
  zip: /^\d{5}(-\d{4})?$/.test(data.zip) ? null : 'Five digits, like 12345',
})

// Each step owns some fields. It is valid when they all are.
const steps: { title: string; fields: Key[] }[] = [
  { title: 'Account', fields: ['name', 'email'] },
  { title: 'Address', fields: ['street', 'city', 'zip'] },
  { title: 'Review', fields: [] },
]
const stepValid = (i: number) =>
  steps[i].fields.every((k) => errors()[k] === null)

function next() {
  // Touch the step's fields so every error shows, then advance if clean.
  steps[step].fields.forEach((k) => touched.add(k))
  if (stepValid(step)) step++
  update()
}

function Field(key: Key, type = 'text') {
  const show = () => touched.has(key) && errors()[key]
  const ok = () => touched.has(key) && !errors()[key]
  return div(
    label(labels[key]),
    input({
      type,
      value: () => data[key],
      style: () => ({ borderColor: show() ? '#ef4444' : ok() ? '#22c55e' : '' }),
      'aria-invalid': () => String(!!show()),
      onInput: (e) => { data[key] = e.currentTarget.value; update() },
      onBlur: () => { touched.add(key); update() },
    }),
    p({ role: 'alert' }, () => show() || ''),
  )
}

// A bar per step, filled up to the current one
const Progress = () =>
  div(
    { style: { display: 'flex', gap: '6px' } },
    ...steps.map((_, i) =>
      div({
        style: () => ({
          flex: '1',
          height: '4px',
          borderRadius: '2px',
          backgroundColor: i <= step ? '#ff3f00' : '#cccccc',
        }),
      }),
    ),
  )

// A step is a when() branch, so moving on builds the next step fresh
// and keeps the data in the plain object above.
export const Wizard = () =>
  div(
    Progress(),
    strong(() => steps[step].title, ' ', small(() => `step ${step + 1} of ${steps.length}`)),
    when(() => step === 0 && !done,
      Field('name'),
      Field('email', 'email'),
    )
      .when(() => step === 1 && !done,
        Field('street'),
        Field('city'),
        Field('zip'),
      )
      .when(() => step === 2 && !done,
        dl(...(Object.keys(labels) as Key[]).flatMap((k) => [
          dt(labels[k]),
          dd(() => data[k]),
          button('Edit', {
            type: 'button',
            onClick: () => {
              step = steps.findIndex((s) => s.fields.includes(k))
              update()
            },
          }),
        ])),
      )
      .else(p('Submitted. ', code(() => JSON.stringify(data)))),
    when(() => !done,
      div(
        button('Back', {
          disabled: () => step === 0,
          onClick: () => { step--; update() },
        }),
        when(() => step < 2, button('Next', { onClick: next }))
          .else(button('Submit', { onClick: () => { done = true; update() } })),
      ),
    ),
  )

import 'nuclo'

interface Line { id: number; item: string; qty: string; price: string }

let nextId = 3
let lines: Line[] = [
  { id: 1, item: 'Design', qty: '2', price: '120' },
  { id: 2, item: '', qty: '1', price: '' },
]
const touched = new Set<number>()   // line ids that were blurred
let submitted: string | null = null

// Validation per row, and for the whole form.
const lineErrors = (l: Line) => ({
  item: l.item.trim() ? null : 'Name the item',
  qty: Number.isInteger(+l.qty) && +l.qty > 0 ? null : 'Whole number above 0',
  price: l.price !== '' && +l.price >= 0 ? null : 'A price',
})
const lineValid = (l: Line) =>
  Object.values(lineErrors(l)).every((e) => e === null)
const valid = () => lines.length > 0 && lines.every(lineValid)
const total = () =>
  lines.filter(lineValid).reduce((sum, l) => sum + +l.qty * +l.price, 0)

const rowStyle = {
  display: 'grid',
  gridTemplateColumns: 'minmax(0, 1fr) 64px 84px 36px',
  gap: '6px',
}

// One input per cell. The row object is the state, so an input writes
// straight into it and update() refreshes the errors and the total.
const cell = (l: Line, key: 'item' | 'qty' | 'price', placeholder: string, type = 'text') =>
  input({
    type,
    placeholder,
    value: () => l[key],
    style: () => ({ borderColor: touched.has(l.id) && lineErrors(l)[key] ? '#ef4444' : '' }),
    'aria-label': `${key} of line ${l.id}`,
    onInput: (e) => { l[key] = e.currentTarget.value; update() },
    onBlur: () => { touched.add(l.id); update() },
  })

// list() keeps a row's inputs while the row is in the array: adding or
// removing other rows does not touch them, and their focus survives.
export const Invoice = () =>
  form(
    div({ style: rowStyle }, small('Item'), small('Qty'), small('Price'), span()),
    list(() => lines, (l) =>
      div(
        div(
          { style: rowStyle },
          cell(l, 'item', 'Item'),
          cell(l, 'qty', '1', 'number'),
          cell(l, 'price', '0.00', 'number'),
          button('✕', {
            type: 'button',
            title: 'Remove',
            'aria-label': 'Remove line',
            onClick: () => { lines = lines.filter((x) => x !== l); update() },
          }),
        ),
        p({ role: 'alert' }, () =>
          touched.has(l.id) ? Object.values(lineErrors(l)).find((e) => e) ?? '' : ''),
      ),
    ),
    div(
      { style: { display: 'flex', justifyContent: 'space-between', fontWeight: '600' } },
      span('Total'),
      span(() => total().toFixed(2)),
    ),
    div(
      button('Add line', {
        type: 'button',
        onClick: () => {
          lines.push({ id: nextId++, item: '', qty: '1', price: '' })
          update()
        },
      }),
      button('Send invoice', {
        type: 'button',
        disabled: () => !valid(),
        onClick: () => {
          submitted = `${lines.length} lines, total ${total().toFixed(2)}`
          update()
        },
      }),
    ),
    when(() => submitted !== null, p(() => submitted ?? '')),
  )

import 'nuclo'

const labels = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
let data = [40, 72, 55, 90, 30, 64]

const rand = () => Math.round(10 + Math.random() * 90)
const barY = (value: number) => 140 - value * 1.3

// Every SVG builder ends in "Svg". Attributes that depend on
// data are functions, so update() moves the bars. A CSS
// transition on y and height animates the move.
export const BarChart = () =>
  div(
    svgSvg(
      { viewBox: '0 0 320 160', width: '320', height: '160' },
      lineSvg({ x1: 0, y1: 140.5, x2: 320, y2: 140.5, stroke: '#ccc' }),
      ...labels.map((label, i) =>
        gSvg(
          rectSvg({
            x: i * 52 + 14,
            width: 36,
            rx: 5,
            fill: '#ff3f00',
            style: { transition: 'y 0.4s, height 0.4s' },
            y: () => barY(data[i]),
            height: () => data[i] * 1.3,
          }),
          textSvg(
            { x: i * 52 + 32, y: 156, 'text-anchor': 'middle' },
            label,
          ),
          // A text's y does not transition; a CSS transform does.
          gSvg(
            {
              style: () => ({
                transition: 'transform 0.4s',
                transform: `translateY(${barY(data[i]) - 6}px)`,
              }),
            },
            textSvg(
              { x: i * 52 + 32, y: 0, 'text-anchor': 'middle' },
              () => data[i],
            ),
          ),
        ),
      ),
    ),
    button('Randomize', {
      onClick: () => { data = data.map(rand); update() },
    }),
    button('Sort', {
      onClick: () => { data = [...data].sort((a, b) => a - b); update() },
    }),
  )

import 'nuclo'

let points = [20, 45, 30, 70, 55, 85, 60]

const x = (i: number) => (i / (points.length - 1)) * 300 + 10
const y = (value: number) => 140 - value * 1.2
const rand = () => Math.round(5 + Math.random() * 95)

// A path's d is a plain string, so build it from the data.
const line = () =>
  points.map((v, i) => `${i ? 'L' : 'M'}${x(i)},${y(v)}`).join(' ')
const area = () => `${line()} L${x(6)},150 L${x(0)},150 Z`

// Each point becomes the average of itself and its neighbours.
const smooth = () =>
  points.map((v, i, all) =>
    Math.round((all[i - 1] ?? v) * 0.25 + v * 0.5 + (all[i + 1] ?? v) * 0.25),
  )

export const LineChart = () =>
  div(
    svgSvg(
      { viewBox: '0 0 320 160', width: '320', height: '160' },
      defsSvg(
        linearGradientSvg(
          { id: 'fill', x1: 0, y1: 0, x2: 0, y2: 1 },
          stopSvg({
            offset: '0', 'stop-color': '#ff3f00', 'stop-opacity': 0.35,
          }),
          stopSvg({
            offset: '1', 'stop-color': '#ff3f00', 'stop-opacity': 0,
          }),
        ),
      ),
      // Grid lines at fixed values.
      ...[0, 25, 50, 75, 100].map((v) =>
        lineSvg({
          x1: 10, x2: 310, y1: y(v) + 0.5, y2: y(v) + 0.5,
          stroke: '#ddd', 'stroke-dasharray': v ? '2 4' : '',
        }),
      ),
      pathSvg({
        fill: 'url(#fill)', stroke: 'none', d: area,
        style: { transition: 'd 0.4s' },
      }),
      pathSvg({
        fill: 'none', stroke: '#ff3f00', 'stroke-width': 2.5,
        'stroke-linejoin': 'round', style: { transition: 'd 0.4s' }, d: line,
      }),
      ...points.map((_, i) =>
        circleSvg({
          r: 4,
          fill: '#fff',
          stroke: '#ff3f00',
          'stroke-width': 2,
          style: { transition: 'cx 0.4s, cy 0.4s' },
          cx: x(i),
          cy: () => y(points[i]),
        }),
      ),
    ),
    div(
      { style: { display: 'flex', gap: '8px', justifyContent: 'center' } },
      button('New data', {
        onClick: () => { points = points.map(rand); update() },
      }),
      button('Smooth', { onClick: () => { points = smooth(); update() } }),
    ),
  )

import 'nuclo'

const names = ['Core', 'Router', 'Docs']
const colors = ['#ff3f00', '#2563eb', '#ff8a00']
const start = [52, 18, 30]
let parts = [...start]

const C = 2 * Math.PI * 54 // the ring's circumference
const total = () => parts.reduce((a, b) => a + b, 0)
const share = (i: number) => parts[i] / total()
const before = (i: number) =>
  parts.slice(0, i).reduce((a, b) => a + b, 0) / total()

const ring = { cx: 80, cy: 80, r: 54, fill: 'none', 'stroke-width': 18 }

// One circle per slice: the dash array is its share of the ring,
// the dash offset moves it past the slices before it.
export const DonutChart = () =>
  div(
    svgSvg(
      { viewBox: '0 0 160 160', width: '160', height: '160' },
      circleSvg(ring, { stroke: '#eee' }),
      ...parts.map((_, i) =>
        circleSvg(ring, {
          stroke: colors[i],
          transform: 'rotate(-90 80 80)',
          style: {
            transition: 'stroke-dasharray 0.5s, stroke-dashoffset 0.5s',
          },
          'stroke-dasharray': () => `${share(i) * C} ${C}`,
          'stroke-dashoffset': () => -before(i) * C,
        }),
      ),
      textSvg(
        {
          x: 80, y: 80, 'text-anchor': 'middle', 'dominant-baseline': 'middle',
          'font-size': 22, 'font-weight': 700,
        },
        () => `${Math.round(share(0) * 100)}%`,
      ),
      textSvg(
        { x: 80, y: 102, 'text-anchor': 'middle', 'font-size': 11 },
        names[0],
      ),
    ),
    div(
      { style: { display: 'flex', gap: '8px', justifyContent: 'center' } },
      ...names.map((name, i) =>
        button(`+ ${name}`, { onClick: () => { parts[i] += 10; update() } }),
      ),
      button('Reset', { onClick: () => { parts = [...start]; update() } }),
    ),
  )

import 'nuclo'

let svg: SVGSVGElement | undefined
let paused = false
let speed = 1

const setSpeed = (next: number) => {
  speed = next
  update()
}

// SMIL elements are builders too: animateSvg drives one attribute,
// animateTransformSvg a transform. A modifier function receives the
// element, here to keep the <svg> for pauseAnimations().
export const Orbit = () =>
  div(
    svgSvg(
      { viewBox: '0 0 200 200', width: '200', height: '200' },
      (el: SVGSVGElement) => { svg = el },
      circleSvg({
        cx: 100, cy: 100, r: 70, fill: 'none', stroke: '#eee',
        'stroke-width': 1.5, 'stroke-dasharray': '3 5',
      }),
      // The sun pulses.
      circleSvg(
        { cx: 100, cy: 100, r: 22, fill: '#ff3f00' },
        animateSvg({
          attributeName: 'r', values: '22;26;22', dur: '2s',
          repeatCount: 'indefinite',
        }),
      ),
      // The planet orbits; its moon spins around it.
      gSvg(
        animateTransformSvg({
          attributeName: 'transform', type: 'rotate',
          from: '0 100 100', to: '360 100 100', repeatCount: 'indefinite',
          dur: () => `${6 / speed}s`, // dynamic: update() changes the speed
        }),
        circleSvg({ cx: 170, cy: 100, r: 10, fill: '#2563eb' }),
        gSvg(
          animateTransformSvg({
            attributeName: 'transform', type: 'rotate',
            from: '0 170 100', to: '360 170 100', dur: '1.5s',
            repeatCount: 'indefinite',
          }),
          circleSvg({ cx: 188, cy: 100, r: 4, fill: '#ff8a00' }),
        ),
      ),
    ),
    div(
      { style: { display: 'flex', gap: '8px', justifyContent: 'center' } },
      button(() => (paused ? 'Play' : 'Pause'), {
        onClick: () => {
          paused = !paused
          paused ? svg?.pauseAnimations() : svg?.unpauseAnimations()
          update()
        },
      }),
      button('Slower', { onClick: () => setSpeed(Math.max(0.25, speed / 2)) }),
      button(() => `${speed}×`, { onClick: () => setSpeed(1) }),
      button('Faster', { onClick: () => setSpeed(Math.min(8, speed * 2)) }),
    ),
  )

import 'nuclo'

let value = 62
const ARC = Math.PI * 70 // length of the half circle
const set = (next: number) => {
  value = Math.max(0, Math.min(100, next))
  update()
}

// The arc is a dash as long as the half circle; the offset hides
// the part past the value. The needle is a group whose CSS
// transform rotates it around the pivot.
export const Gauge = () =>
  div(
    svgSvg(
      { viewBox: '0 0 200 150', width: '200', height: '150' },
      pathSvg({
        d: 'M30,110 A70,70 0 0 1 170,110', fill: 'none',
        stroke: '#eee', 'stroke-width': 14, 'stroke-linecap': 'round',
      }),
      pathSvg({
        d: 'M30,110 A70,70 0 0 1 170,110', fill: 'none',
        stroke: '#ff3f00', 'stroke-width': 14, 'stroke-linecap': 'round',
        'stroke-dasharray': `${ARC} ${ARC}`,
        style: { transition: 'stroke-dashoffset 0.5s' },
        'stroke-dashoffset': () => ARC * (1 - value / 100),
      }),
      gSvg(
        {
          style: () => ({
            transition: 'transform 0.5s',
            transformOrigin: '100px 110px',
            transform: `rotate(${-90 + value * 1.8}deg)`,
          }),
        },
        lineSvg({
          x1: 100, y1: 110, x2: 100, y2: 54,
          stroke: '#222', 'stroke-width': 3, 'stroke-linecap': 'round',
        }),
        circleSvg({
          cx: 100, cy: 110, r: 6, fill: '#fff',
          stroke: '#ff3f00', 'stroke-width': 3,
        }),
      ),
      textSvg(
        { x: 100, y: 144, 'text-anchor': 'middle', 'font-size': 22 },
        () => `${value}%`,
      ),
    ),
    button('−10', { onClick: () => set(value - 10) }),
    button('Random', { onClick: () => set(Math.round(Math.random() * 100)) }),
    button('+10', { onClick: () => set(value + 10) }),
  )

import 'nuclo'

const axes = ['Speed', 'Size', 'DX', 'SSR', 'Docs']
const start = [90, 95, 80, 70, 60]
let values = [...start]

// Axis i points at -90° + i * 72°; a value is a distance along it.
const angle = (i: number) => ((-90 + i * 72) * Math.PI) / 180
const px = (i: number, v: number) => 100 + Math.cos(angle(i)) * 68 * (v / 100)
const py = (i: number, v: number) => 100 + Math.sin(angle(i)) * 68 * (v / 100)

// A closed path through one point per axis. The grid rings are
// the same path at fixed values; the data shape reads the values.
const ring = (v: number) =>
  axes.map((_, i) => `${i ? 'L' : 'M'}${px(i, v)},${py(i, v)}`).join(' ') + ' Z'
const shape = () =>
  axes
    .map((_, i) => `${i ? 'L' : 'M'}${px(i, values[i])},${py(i, values[i])}`)
    .join(' ') + ' Z'

export const RadarChart = () =>
  div(
    svgSvg(
      { viewBox: '0 0 200 200', width: '200', height: '200' },
      ...[25, 50, 75, 100].map((v) =>
        pathSvg({ d: ring(v), fill: 'none', stroke: '#ddd' }),
      ),
      ...axes.map((_, i) =>
        lineSvg({
          x1: 100, y1: 100, x2: px(i, 100), y2: py(i, 100), stroke: '#ddd',
        }),
      ),
      pathSvg({
        fill: '#ff3f00', 'fill-opacity': 0.25, stroke: '#ff3f00',
        'stroke-width': 2, 'stroke-linejoin': 'round',
        style: { transition: 'd 0.4s' },
        d: shape,
      }),
      ...axes.map((_, i) =>
        circleSvg({
          r: 3.5, fill: '#fff', stroke: '#ff3f00', 'stroke-width': 2,
          style: { transition: 'cx 0.4s, cy 0.4s' },
          cx: () => px(i, values[i]),
          cy: () => py(i, values[i]),
        }),
      ),
      ...axes.map((name, i) =>
        textSvg(
          { x: px(i, 126), y: py(i, 126) + 4, 'text-anchor': 'middle' },
          { 'font-size': 11 },
          name,
        ),
      ),
    ),
    div(
      { style: { display: 'flex', gap: '8px', justifyContent: 'center' } },
      button('Randomize', {
        onClick: () => {
          values = values.map(() => Math.round(20 + Math.random() * 80))
          update()
        },
      }),
      button('Reset', { onClick: () => { values = [...start]; update() } }),
    ),
  )

import 'nuclo'

const COLS = 14
const ROWS = 7
const OPACITY = [0.08, 0.3, 0.55, 0.8, 1]
const random = () => Math.floor(Math.random() * 5)
let levels = Array.from({ length: COLS * ROWS }, random)

// One rect per cell, column by column. Its fill-opacity is a
// function of the cell's level, and a titleSvg child is the
// browser's own tooltip. onClick works on SVG elements as on any.
export const Heatmap = () =>
  div(
    svgSvg(
      { viewBox: '0 0 235 116', width: '235', height: '116' },
      ...levels.map((_, i) =>
        rectSvg(
          {
            x: Math.floor(i / ROWS) * 17,
            y: (i % ROWS) * 17,
            width: 14, height: 14, rx: 3,
            fill: '#ff3f00',
            style: { cursor: 'pointer', transition: 'fill-opacity 0.2s' },
            'fill-opacity': () => OPACITY[levels[i]],
            onClick: () => { levels[i] = (levels[i] + 1) % 5; update() },
          },
          titleSvg(() => `${levels[i]} commits`),
        ),
      ),
    ),
    div(() => `${levels.reduce((a, b) => a + b, 0)} commits · click a cell`),
    div(
      { style: { display: 'flex', gap: '8px', justifyContent: 'center' } },
      button('Shuffle', {
        onClick: () => { levels = levels.map(random); update() },
      }),
      button('Clear', {
        onClick: () => { levels = levels.map(() => 0); update() },
      }),
    ),
