            y: () => H - 2 - (pick(i).v / vmax) * 38,
            height: () => (pick(i).v / vmax) * 38,
          }),
        ),
      ),
      pathSvg({
        fill: 'none', stroke: '#ff8a00', 'stroke-width': 1.6, 'stroke-linejoin': 'round',
        opacity: () => (showSma ? 1 : 0), d: sma,
      }),
      // The last price: a dashed line and a tag on the axis.
      lineSvg({
        'stroke-dasharray': '3 3', x1: 0, x2: PW,
        stroke: lastColor, y1: () => y(last().c), y2: () => y(last().c),
      }),
      rectSvg({ rx: 3, x: PW + 1, width: 37, height: 14, fill: lastColor, y: () => y(last().c) - 7 }),
      textSvg(muted, { x: PW + 4, style: { fill: '#fff' }, y: () => y(last().c) + 4 }, () => last().c.toFixed(1)),
      // The hover cursor
      gSvg(
        { stroke: '#8a8a8a', 'pointer-events': 'none', opacity: () => (hover === null ? 0 : 1) },
        lineSvg({ y1: 0, y2: H, x1: () => cx(hover ?? 0), x2: () => cx(hover ?? 0) }),
        lineSvg({ x1: 0, x2: PW, y1: () => y(pick(hover ?? 0).c), y2: () => y(pick(hover ?? 0).c) }),
      ),
      // A transparent rect on top follows the pointer.
      rectSvg({
        x: 0, y: 0, width: PW, height: H, fill: 'transparent', style: { cursor: 'crosshair', touchAction: 'none' },
        onPointerMove: (e) => {
          const box = e.currentTarget.getBoundingClientRect()
          const i = Math.floor(((e.clientX - box.left) / box.width) * view.length)
          hover = Math.max(0, Math.min(view.length - 1, i))
          update('candles')
        },
        onPointerLeave: () => { hover = null; update('candles') },
      }),
    ),
    div(
      { style: { fontFamily: 'ui-monospace, monospace', fontSize: '12px', color: '#8a8a8a', textAlign: 'center', minHeight: '36px' } },
      () => {
        const k = pick(hover ?? view.length - 1)
        return 'O ' + k.o.toFixed(1) + ' · H ' + k.h.toFixed(1) + ' · L ' + k.l.toFixed(1) +
          ' · C ' + k.c.toFixed(1) + ' · ' + (((k.c - k.o) / k.o) * 100).toFixed(2) + '%'
      },
    ),
    div(
      { style: { display: 'flex', gap: '8px', justifyContent: 'center' } },
      ...[1, 3, 5].map((m) =>
        button(m + 'm', {
          'aria-pressed': () => String(agg === m),
          style: () => ({ outline: agg === m ? '2px solid currentColor' : 'none', outlineOffset: '2px' }),
          onClick: set(() => { agg = m; hover = null }),
        }),
      ),
      button('SMA', {
        'aria-pressed': () => String(showSma),
        style: () => ({ outline: showSma ? '2px solid currentColor' : 'none', outlineOffset: '2px' }),
        onClick: set(() => { showSma = !showSma }),
      }),
      button(() => (live ? 'Live' : 'Paused'), { onClick: set(() => { live = !live }) }),
    ),
  )

import 'nuclo'

const W = 320
const ROW = 24
const TOP = 6
const LABEL = 68
const H = TOP * ROW + 6
const KEYS = 13
const FIRST = 2012
const names = ['Atlas', 'Borealis', 'Cobalt', 'Delta', 'Ember', 'Fjord', 'Garnet', 'Helix', 'Indigo', 'Juno']

// Seeded random numbers, so the first frame is always the same.
let seed = 23
const random = () => (seed = (seed * 16807) % 2147483647) / 2147483647

// One value per name per year. Each name grows at its own pace.
const series = names.map(() => {
  let v = 20 + random() * 60
  const g = -0.04 + random() * 0.34
  return Array.from({ length: KEYS }, () => {
    const out = v
    v *= 1 + g + (random() - 0.5) * 0.3
    return out
  })
})

let t = 0 // 0 to 12, with decimals: how far between two years
let playing = true
let value: number[] = []
let rank: number[] = []
let peak = 1

// Interpolate the years, then rank the interpolated values.
function measure() {
  const k = Math.min(KEYS - 2, Math.floor(t))
  value = series.map((s) => s[k] + (s[k + 1] - s[k]) * (t - k))
  const order = value.map((_, i) => i).sort((p, q) => value[q] - value[p])
  order.forEach((item, r) => (rank[item] = r))
  peak = value[order[0]]
}
measure()

const year = () => FIRST + Math.floor(t + 0.001)
const barWidth = (i: number) => Math.max(2, (value[i] / peak) * (W - LABEL - 44))

// The list never reorders: every bar keeps its place in the DOM
// and moves with translateY(rank), so a CSS transition slides it
// to its new row. Names below the top six fade out below the chart.
// The bar's width is a plain function of the value, so it follows
// every frame. The frame loop updates only the 'race' scope.
export const Race = () =>
  div(
    { style: { display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '18px', width: '100%', maxWidth: '380px' } },
    scope('race'),
    svgSvg(
      {
        viewBox: '0 0 320 150', role: 'img', 'aria-label': 'Bar chart race',
        style: { width: '100%', height: 'auto', overflow: 'visible' },
        onMount: () => {
          let id = requestAnimationFrame(function frame() {
            if (playing) {
              t = Math.min(KEYS - 1, t + 0.012)
              if (t >= KEYS - 1) playing = false
              measure()
              update('race')
            }
            id = requestAnimationFrame(frame)
          })
          return () => cancelAnimationFrame(id)
        },
      },
      // The big year sits behind the bars.
      textSvg(
        { x: W - 4, y: H - 8, 'text-anchor': 'end', 'font-size': 54, 'font-weight': 800, 'fill-opacity': 0.12, 'pointer-events': 'none' },
        () => year(),
      ),
      ...names.map((name, i) =>
        gSvg(
          {
            opacity: () => (rank[i] < TOP ? 1 : 0),
            style: () => ({
              transition: 'transform 0.45s ease, opacity 0.3s ease',
              transform: 'translateY(' + Math.min(rank[i], TOP) * ROW + 'px)',
            }),
          },
          textSvg({ x: LABEL - 6, y: 15, 'text-anchor': 'end', 'font-size': 11, 'font-weight': 600 }, name),
          rectSvg({
            x: LABEL, y: 3, height: ROW - 6, rx: 4,
            fill: 'hsl(' + ((i * 47 + 12) % 360) + ' 72% 52%)',
            width: () => barWidth(i),
          }),
          textSvg(
            { y: 15, 'font-family': 'ui-monospace, monospace', 'font-size': 11, fill: '#8a8a8a', x: () => LABEL + barWidth(i) + 5 },
            () => Math.round(value[i]),
          ),
        ),
      ),
    ),
    div(
      { style: { display: 'flex', flexWrap: 'wrap', alignItems: 'center', justifyContent: 'center', gap: '8px' } },
      button(() => (playing ? 'Pause' : t >= KEYS - 1 ? 'Replay' : 'Play'), {
        onClick: () => {
          if (t >= KEYS - 1) { t = 0; measure() }
          playing = !playing
          update('race')
        },
      }),
      input({
        type: 'range', min: '0', max: String((KEYS - 1) * 100), step: '1', 'aria-label': 'Year',
        style: { width: '100%', maxWidth: '320px' },
        value: () => String(Math.round(t * 100)),
        onInput: (e) => {
          t = Number(e.currentTarget.value) / 100
          playing = false
          measure()
          update('race')
        },
      }),
    ),
    div(
      { style: { fontFamily: 'ui-monospace, monospace', fontSize: '12px', color: '#8a8a8a', textAlign: 'center' } },
      () => year() + ' · ' + names[rank.indexOf(0)] + ' leads · sample data',
    ),
  )

import 'nuclo'

type Mode = 'stacked' | 'stream' | 'percent'

const W = 320
const H = 170
const PT = 6 // plot top
const PH = 142 // plot height
const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
const names = ['Core', 'Router', 'Docs', 'Tools']
const colors = ['#ff3f00', '#2563eb', '#ff8a00', '#6b7280']

// A seeded random walk per series, so every reload draws the same chart.
let seed = 3
const random = () => (seed = (seed * 16807) % 2147483647) / 2147483647
const clamp = (v: number, min: number, max: number) => Math.max(min, Math.min(max, v))
const data = names.map((_, k) => {
  let v = 16 + k * 6 + random() * 8
  return months.map(() => Math.round((v = clamp(v + (random() - 0.45) * 10, 6, 52))))
})

const on = names.map(() => true) // which series are shown
let mode: Mode = 'stacked'
let hover: number | null = null // the month under the pointer

const x = (i: number) => 28 + (i / (months.length - 1)) * (W - 34)

// Every series is a band between a low edge and a high edge.
// A hidden series only gets zero thickness, so every path keeps
// the same shape and the CSS transition on d can morph it.
//   stacked: the edges pile up from zero
//   stream:  the pile is centered on zero
//   percent: each month is divided by its total
function layout() {
  const rows = months.map((_, i) => data.map((s, k) => (on[k] ? s[i] : 0)))
  const totals = rows.map((r) => r.reduce((a, b) => a + b, 0))
  const peak = Math.max(1, ...totals)
  const lo = names.map((): number[] => [])
  const hi = names.map((): number[] => [])
  rows.forEach((row, i) => {
    const unit = mode === 'percent' ? totals[i] || 1 : 1
    let acc = mode === 'stream' ? -totals[i] / 2 : 0
    row.forEach((v, k) => {
      lo[k][i] = acc / unit
      acc += v
      hi[k][i] = acc / unit
    })
  })
  const [d0, d1] =
    mode === 'percent' ? [0, 1] : mode === 'stream' ? [-peak / 2, peak / 2] : [0, peak]
  return { lo, hi, d0, d1 }
}

const py = (v: number, d0: number, d1: number) =>
  PT + (1 - (v - d0) / (d1 - d0)) * PH

// Curves with horizontal tangents never overshoot the data.
function smooth(pts: number[][], from: 'M' | 'L') {
  let d = from + pts[0][0].toFixed(1) + ',' + pts[0][1].toFixed(1)
  for (let i = 1; i < pts.length; i++) {
    const mid = ((pts[i - 1][0] + pts[i][0]) / 2).toFixed(1)
    d += ' C' + mid + ',' + pts[i - 1][1].toFixed(1) + ' ' + mid + ',' + pts[i][1].toFixed(1) +
      ' ' + pts[i][0].toFixed(1) + ',' + pts[i][1].toFixed(1)
  }
  return d
}

// The high edge forward, the low edge back, then close.
function band(k: number) {
  const { lo, hi, d0, d1 } = layout()
  const top = hi[k].map((v, i) => [x(i), py(v, d0, d1)])
  const bottom = lo[k].map((v, i) => [x(i), py(v, d0, d1)]).reverse()
  return smooth(top, 'M') + ' ' + smooth(bottom, 'L') + ' Z'
}

// The y of a grid line, and the label that goes with it.
function level(f: number) {
  const { d0, d1 } = layout()
  return py(d0 + (d1 - d0) * f, d0, d1)
}
function label(f: number) {
  const { d0, d1 } = layout()
  if (mode === 'stream') return ''
  return mode === 'percent' ? Math.round(f * 100) + '%' : String(Math.round(d0 + (d1 - d0) * f))
}

const caption = () =>
  hover === null
    ? 'Hover a month. Click a name to hide it.'
    : months[hover] + ' · ' +
      names.map((n, k) => (on[k] ? n + ' ' + data[k][hover!] : '')).filter(Boolean).join(' · ')

const row = { display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: '6px' }

export const StackedArea = () =>
  div(
    { style: { display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '18px', width: '100%', maxWidth: '380px' } },
    svgSvg(
      {
        viewBox: '0 0 320 170', role: 'img', 'aria-label': 'Stacked area chart',
        style: { width: '100%', overflow: 'visible' },
        onPointerLeave: () => { hover = null; update() },
      },
      // grid lines and their labels follow the layout
      ...[0, 0.25, 0.5, 0.75, 1].map((f) =>
        gSvg(
          lineSvg({ x1: 24, x2: W, stroke: '#ddd', 'stroke-dasharray': '2 4', y1: () => level(f) + 0.5, y2: () => level(f) + 0.5 }),
          textSvg({ x: 20, 'text-anchor': 'end', 'font-size': 11, 'fill-opacity': 0.6, y: () => level(f) + 4 }, () => label(f)),
        ),
      ),
      ...names.map((_, k) =>
        pathSvg({
          fill: colors[k], 'fill-opacity': 0.88, stroke: '#fff', 'stroke-width': 1,
          style: { transition: 'd 0.5s cubic-bezier(0.22, 1, 0.36, 1)' },
          d: () => band(k),
        }),
      ),
      // a dashed line that follows the pointer
      lineSvg({
        x1: 0, x2: 0, y1: PT, y2: PT + PH, stroke: '#888', 'stroke-dasharray': '3 3',
        opacity: () => (hover === null ? 0 : 1),
        style: () => ({ pointerEvents: 'none', transition: 'transform 0.12s ease-out', transform: 'translateX(' + x(hover ?? 0) + 'px)' }),
      }),
      ...months.map((m, i) =>
        textSvg({ x: x(i), y: H - 4, 'text-anchor': 'middle', 'font-size': 11, 'fill-opacity': 0.6, opacity: i % 2 ? 0 : 1 }, m),
      ),
      // a transparent rect over the plot reads the pointer and picks the month
      rectSvg({
        x: 0, y: 0, width: W, height: PT + PH, fill: 'transparent',
        style: { cursor: 'crosshair', touchAction: 'none' },
        onPointerMove: (e) => {
          const box = (e.currentTarget as Element).getBoundingClientRect()
          hover = Math.round(clamp((e.clientX - box.left) / box.width, 0, 1) * (months.length - 1))
