        }),
      ),
      textSvg(
        { x: 100, y: 112, 'text-anchor': 'middle', 'font-size': 30, 'font-weight': 700 },
        () => String(value),
      ),
      textSvg(
        { x: 100, y: 130, 'text-anchor': 'middle', 'font-size': 10, fill: '#8b949e' },
        'VOLUME',
      ),
    ),
    div(
      { style: { display: 'flex', gap: '8px' } },
      button('Mute', { onClick: () => set(0) }),
      button('Half', { onClick: () => set(50) }),
