      defsSvg(pathSvg({ id: 'ring', d: ring })),
      circleSvg({ cx: 100, cy: 100, r: () => radius - 24, fill: '#ff3f00' }),
      textSvg(
        {
          x: 100, y: 100, fill: 'white', 'font-weight': 800,
          'text-anchor': 'middle', 'dominant-baseline': 'central',
          'font-size': () => Math.round(radius * 0.8),
