}
export function flatten(root: Block): Block[] { return [root, ...root.children.flatMap(flatten)]; }
export function parentOf(root: Block, id: string): Block | undefined {
  return flatten(root).find((block) => block.children.some((child) => child.id === id));
}
export function duplicate(block: Block): Block {
  const copy = structuredClone(block);
  for (const item of flatten(copy)) item.id = `block-${++nextId}`;
  copy.name += " copy";
  return copy;
}
// Index is the insertion slot before removal, so forward moves in the same layout stay accurate.
export function moveTo(root: Block, block: Block, target: Block, index = target.children.length) {
  if (block === root || target.kind !== "section" || flatten(block).includes(target) || !flatten(root).includes(target)) return false;
  const parent = parentOf(root, block.id);
  if (!parent) return false;
  const previous = parent.children.indexOf(block);
  if (previous < 0) return false;
  index = Math.max(0, Math.min(index, target.children.length));
  if (parent === target && previous < index) index--;
  if (parent === target && previous === index) return false;
  parent.children.splice(previous, 1);
  target.children.splice(index, 0, block);
  return true;
}
export function imageUrl(value: string) {
  try { const url = new URL(value); return ["https:", "http:"].includes(url.protocol) ? url.href : ""; } catch { return ""; }
}
const escape = (value: string) => value.replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]!);
export function exportHtml(root: Block) {
  function render(block: Block): string {
    const tag = { section: "section", heading: "h2", text: "p", button: "button", image: "img", divider: "hr" }[block.kind];
    const css = Object.entries(block.styles).map(([key, value]) => `${key.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`)}:${value}`).join(";");
    const attrs = `style="${escape(css)}"`;
    if (tag === "img") return `<img ${attrs} src="${escape(imageUrl(block.content))}" alt="${escape(block.name)}">`;
    if (tag === "hr") return `<hr ${attrs}>`;
    return `<${tag} ${attrs}>${block.kind === "section" ? block.children.map(render).join("\n") : escape(block.content)}</${tag}>`;
  }
  return `<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Your page</title><style>*{box-sizing:border-box}body{margin:0;font-family:system-ui,sans-serif}h2,p{margin:0}h2,p,button{white-space:pre-wrap}button,hr{border:0}img{max-width:100%}section{min-width:0}h2,p,button{overflow-wrap:anywhere}@media(max-width:600px){section[style*="display:grid"]{grid-template-columns:1fr!important}body>section,section[style*="padding"]{padding:20px!important}h2[style*="font-size:40px"]{font-size:30px!important}}</style></head><body>\n${render(root)}\n</body></html>`;
}

// app.ts: the player. The state is a handful of plain variables; the UI reads
// them through functions. next() is the only place the engine runs, and the
// one update() in it is what refreshes the bars, the counters and the status.
import "nuclo";
import { ALGORITHMS, type Item, type Step } from "./algorithms.ts";
import { s } from "./styles.ts";

const SIZE = 24;

let start: number[] = Array.from({ length: SIZE }, (_, i) => ((i * 7) % SIZE) + 1);
let items: Item[] = [];
let algorithm: keyof typeof ALGORITHMS = "Bubble";
let run: Generator<Step, void> | null = null;
let step: Step | null = null; // the last thing the algorithm did
let compares = 0;
let swaps = 0;
let playing = false;
let speed = 30; // steps per second
let timer: ReturnType<typeof setTimeout> | undefined;

function reset() {
  stop();
  items = start.map((value) => ({ value, sorted: false }));
  run = null;
  step = null;
  compares = swaps = 0;
  update();
}

function shuffle() {
  for (let i = start.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [start[i], start[j]] = [start[j], start[i]];
  }
  reset();
}

// One step: the generator mutates `items`, we note what it did, then update().
function next() {
  run ??= ALGORITHMS[algorithm](items);
  const result = run.next();
  if (result.done) {
    stop();
    step = null;
  } else {
    step = result.value;
    if (step.kind === "swap") swaps++;
    else compares++;
  }
  update();
}

function play() {
  playing = true;
  tick();
}

function tick() {
  next();
  if (playing) timer = setTimeout(tick, 1000 / speed);
}

function stop() {
  playing = false;
  clearTimeout(timer);
}

reset();

const isActive = (item: Item) => step !== null && (step.a === item || step.b === item);

const status = () => {
  if (!step) return items.every((item) => item.sorted) ? "Sorted." : "Press Play or Step.";
  return step.kind === "swap"
    ? `Swapped ${step.a.value} and ${step.b.value}`
    : `Compared ${step.a.value} with ${step.b.value}`;
};

export function SortingStepper() {
  return div(
    s.app,
    on("destroy", stop),
    div(
      s.toolbar,
      select(
        s.select,
        { value: () => algorithm, "aria-label": "Algorithm" },
        { onChange: (e) => { algorithm = e.currentTarget.value as keyof typeof ALGORITHMS; reset(); } },
        ...Object.keys(ALGORITHMS).map((name) => option({ value: name }, name)),
      ),
      button(s.btn, s.primary, () => (playing ? "Pause" : "Play"), { onClick: () => { if (playing) { stop(); update(); } else play(); } }),
      button(s.btn, "Step", { disabled: () => playing, onClick: next }),
      button(s.btn, "Reset", { onClick: reset }),
      button(s.btn, "Shuffle", { onClick: shuffle }),
      label(
        s.speed,
        "Speed",
        input({ type: "range", min: "1", max: "120", value: () => String(speed) }, { onInput: (e) => { speed = Number(e.currentTarget.value); update(); } }),
        span(() => `${speed}/s`),
      ),
    ),
    // Items are tracked by identity: a swap moves two existing bars, it never
    // rebuilds them. The height is static; only the class is read again.
    div(
      s.bars,
      list(
        () => items,
        (item) =>
          div(
            s.bar,
            { style: { height: `${(item.value / SIZE) * 100}%` } },
            { class: () => cx(s.bar, isActive(item) ? (step!.kind === "swap" ? s.swap : s.compare) : item.sorted ? s.sorted : null).className },
