// algorithms.ts: the engine. Plain generators over a plain array; nothing here
// knows about the DOM or about nuclo. Each one mutates `items` in place and
// yields after every comparison or swap, so whoever drives it (a UI, a test)
// can stop between any two steps and look at the array as it is right now.

export interface Item {
  value: number;
  sorted: boolean; // set by the algorithm once the item is in its final place
}

export type Step =
  | { kind: "compare"; a: Item; b: Item }
  | { kind: "swap"; a: Item; b: Item };

export type Algorithm = (items: Item[]) => Generator<Step, void>;

function* greater(items: Item[], i: number, j: number): Generator<Step, boolean> {
  yield { kind: "compare", a: items[i], b: items[j] };
  return items[i].value > items[j].value;
}

function* swap(items: Item[], i: number, j: number): Generator<Step, void> {
  [items[i], items[j]] = [items[j], items[i]];
  yield { kind: "swap", a: items[i], b: items[j] };
}

export function* bubbleSort(items: Item[]): Generator<Step, void> {
  for (let end = items.length - 1; end > 0; end--) {
    for (let i = 0; i < end; i++) {
      if (yield* greater(items, i, i + 1)) yield* swap(items, i, i + 1);
    }
    items[end].sorted = true;
  }
  items[0].sorted = true;
}

export function* insertionSort(items: Item[]): Generator<Step, void> {
  for (let i = 1; i < items.length; i++) {
    for (let j = i; j > 0 && (yield* greater(items, j - 1, j)); j--) {
      yield* swap(items, j - 1, j);
    }
  }
  for (const item of items) item.sorted = true;
}

export function* selectionSort(items: Item[]): Generator<Step, void> {
  for (let i = 0; i < items.length; i++) {
    let min = i;
    for (let j = i + 1; j < items.length; j++) {
      if (yield* greater(items, min, j)) min = j;
    }
    if (min !== i) yield* swap(items, i, min);
    items[i].sorted = true;
  }
}

export function* quickSort(items: Item[], lo = 0, hi = items.length - 1): Generator<Step, void> {
  if (lo > hi) return;
  let p = lo; // everything before p is smaller than the pivot, items[hi]
  for (let i = lo; i < hi; i++) {
    if (yield* greater(items, hi, i)) {
      if (i !== p) yield* swap(items, i, p);
      p++;
    }
  }
  if (p !== hi) yield* swap(items, p, hi);
  items[p].sorted = true;
  yield* quickSort(items, lo, p - 1);
  yield* quickSort(items, p + 1, hi);
}

export const ALGORITHMS = {
  Bubble: bubbleSort,
  Insertion: insertionSort,
  Selection: selectionSort,
  Quick: quickSort,
} satisfies Record<string, Algorithm>;

// app.ts: the board. Columns are a list() of columns, cards a list() of each
// column's cards. Rows are matched by identity, so reordering inside a column
// (a drag, "Sort", "Top"), assigning a user or editing a card moves or patches
// the existing elements and mounts nothing. A card dropped into another column
// leaves one list and enters another (a filter does the same), so it is built
// again there: watch it flash, and the mount count go up.
import "nuclo";
import { add, columnOf, columns, cyclePriority, edit, initials, move, PRIORITIES, remove, restore, sortByPriority, users, type Card, type Column, type Draft, type User } from "./board.ts";
import { s } from "./styles.ts";

let dragging: Card | null = null;
let over: { column: Column; index: number } | null = null; // where it would land
let mounts = 0;

// Which cards are shown. A filtered-out card stays in its column, only hidden.
const filter = { search: "", user: null as User | "none" | null };

// The open task dialog: a new card for `column`, or `card` being edited.
let dialog: { card: Card | null; column: Column; draft: Draft } | null = null;
let undo: { card: Card; column: Column; index: number } | null = null;
let undoTimer = 0;

const PRIORITY = { 1: "low", 2: "normal", 3: "urgent" };

const matches = (c: Card) => {
  const q = filter.search.trim().toLowerCase();
  if (q && !`${c.title} ${c.description} ${c.assignee?.name ?? ""}`.toLowerCase().includes(q)) return false;
  if (filter.user === "none") return c.assignee === null;
  return !filter.user || c.assignee === filter.user;
};
const visible = (column: Column) => column.cards.filter(matches);
const filtering = () => filter.search.trim() !== "" || filter.user !== null;

function setOver(column: Column, index: number) {
  if (over?.column === column && over.index === index) return;
  over = { column, index };
  update();
}

function drop() {
  if (dragging && over) move(dragging, over.column, over.index);
  dragging = over = null;
  update();
}

function openNew(column: Column) {
  dialog = { card: null, column, draft: { title: "", description: "", priority: 2, assignee: filter.user && filter.user !== "none" ? filter.user : null } };
  update();
}

function openEdit(card: Card) {
  const { title, description, priority, assignee } = card;
  dialog = { card, column: columnOf(card), draft: { title, description, priority, assignee } };
  update();
}

const closeDialog = () => { dialog = null; update(); };

function save() {
  if (!dialog || !dialog.draft.title.trim()) return;
  const { card, column, draft } = dialog;
  const next = { ...draft, title: draft.title.trim(), description: draft.description.trim() };
  if (!card) add(column, next);
  else {
    edit(card, next);
    if (columnOf(card) !== column) move(card, column, 0);
  }
  closeDialog();
}

function deleteCard(card: Card) {
  const column = columnOf(card);
  undo = { card, column, index: column.cards.indexOf(card) };
  remove(card);
  clearTimeout(undoTimer);
  undoTimer = window.setTimeout(() => { undo = null; update(); }, 6000);
  dialog = null;
  update();
}

function undoDelete() {
  if (!undo) return;
  restore(undo.card, undo.column, undo.index);
  clearTimeout(undoTimer);
  undo = null;
  update();
}

function Avatar(user: () => User | null) {
  return span(
    { class: () => cx(s.avatar, user() ? null : s.nobody).className },
    { style: () => ({ backgroundColor: user()?.color ?? "" }), title: () => user()?.name ?? "Unassigned" },
    () => { const u = user(); return u ? initials(u) : "?"; },
  );
}

function Field(name: string, ...content: NodeModLike<"label">[]) {
  return label(s.field, span(name), ...content);
}

function CardView(card: Card, column: Column) {
  return div(
    s.card,
    { draggable: true, tabIndex: 0 },
    { class: () => cx(s.card, card === dragging ? s.lifted : null, over?.column === column && over.index === column.cards.indexOf(card) ? s.before : null).className },
    // The mount count is the proof: it only moves when a card is built.
    on("mount", () => { mounts++; queueMicrotask(update); }),
    {
      onClick: (e) => { if (!(e.target as HTMLElement).closest("button, select")) openEdit(card); },
      onKeyDown: (e) => { if (e.key === "Enter" && e.target === e.currentTarget) openEdit(card); },
      onDragStart: (e) => { e.dataTransfer?.setData("text/plain", card.title); dragging = card; update(); },
      onDragEnd: () => { dragging = over = null; update(); },
      onDragOver: (e) => {
        e.preventDefault();
        e.stopPropagation();
        const below = e.offsetY > e.currentTarget.offsetHeight / 2;
        setOver(column, column.cards.indexOf(card) + (below ? 1 : 0));
      },
    },
    div(s.cardHead,
      button(s.priority, { type: "button", title: "Change priority", class: () => cx(s.priority, s[`p${card.priority}`]).className }, () => PRIORITY[card.priority], { onClick: () => { cyclePriority(card); update(); } }),
      span(s.id, `#${card.id}`),
      div(s.actions,
        button(s.icon, { type: "button", title: "Move to top", "aria-label": "Move to top" }, "↑", { onClick: () => { move(card, column, 0); update(); } }),
        button(s.icon, { type: "button", title: "Delete", "aria-label": "Delete" }, "×", { onClick: () => deleteCard(card) }),
      ),
    ),
    div(s.title, () => card.title),
    when(() => card.description !== "", p(s.desc, () => card.description)),
    div(s.cardFoot,
      Avatar(() => card.assignee),
      select(s.assign, {
        "aria-label": "Assignee",
        value: () => card.assignee?.id ?? "",
        onChange: (e) => { card.assignee = users.find((u) => u.id === e.currentTarget.value) ?? null; update(); },
      },
        option({ value: "" }, "Unassigned"),
        ...users.map((u) => option({ value: u.id }, u.name))),
    ),
  );
}

function ColumnView(column: Column) {
  return section(
    s.column,
    { class: () => cx(s.column, over?.column === column && over.index === column.cards.length ? s.after : null).className },
    {
      onDragOver: (e) => { e.preventDefault(); setOver(column, column.cards.length); },
      onDragLeave: (e) => { if (!e.currentTarget.contains(e.relatedTarget as Node | null)) { over = null; update(); } },
      onDrop: (e) => { e.preventDefault(); drop(); },
    },
    header(s.columnHead,
      h3(column.title, span(s.count, () => (filtering() ? `${visible(column).length}/${column.cards.length}` : String(column.cards.length)))),
      button(s.small, { type: "button", title: "Sort by priority", onClick: () => { sortByPriority(column); update(); } }, "Sort"),
      button(s.small, { type: "button", title: `Add a task to ${column.title}`, "aria-label": `Add a task to ${column.title}`, onClick: () => openNew(column) }, "+"),
    ),
    div(s.cards,
      list(() => visible(column), (card) => CardView(card, column)),
      when(() => visible(column).length === 0, p(s.empty, () => (column.cards.length ? "No matching tasks" : "Drop a task here"))),
    ),
    button(s.addTask, { type: "button", onClick: () => openNew(column) }, "+ Add task"),
  );
}

function Toolbar() {
  const done = () => columns[columns.length - 1].cards.length;
  const total = () => columns.reduce((n, c) => n + c.cards.length, 0);
  const percent = () => (total() ? Math.round((done() / total()) * 100) : 0);
  const load = (u: User) => columns.slice(0, -1).reduce((n, c) => n + c.cards.filter((card) => card.assignee === u).length, 0);
  return header(
    s.bar,
    div(s.brand, div(s.logo, "▦"), div(h2("Product board"), p(s.sub, () => `${total()} tasks · ${done()} done`))),
    div(s.progress, { role: "progressbar", "aria-label": "Done", "aria-valuemin": "0", "aria-valuemax": "100", "aria-valuenow": () => String(percent()) },
      div(s.fill, { style: () => ({ width: `${percent()}%` }) })),
    div(s.tools,
      input(s.search, { type: "search", placeholder: "Search tasks", "aria-label": "Search tasks", value: () => filter.search, onInput: (e) => { filter.search = e.currentTarget.value; update(); } }),
      div(s.team, { role: "group", "aria-label": "Filter by assignee" },
        ...users.map((u) =>
          button(
            { type: "button", class: () => cx(s.member, filter.user === u ? s.picked : null).className, title: () => `${u.name}: ${load(u)} open`, "aria-pressed": () => String(filter.user === u), onClick: () => { filter.user = filter.user === u ? null : u; update(); } },
            Avatar(() => u),
          )),
        button({ type: "button", class: () => cx(s.chip, filter.user === "none" ? s.picked : null).className, "aria-pressed": () => String(filter.user === "none"), onClick: () => { filter.user = filter.user === "none" ? null : "none"; update(); } }, "Unassigned"),
      ),
      button(s.primary, { type: "button", onClick: () => openNew(columns[0]) }, "+ New task"),
    ),
  );
}

function Dialog() {
  const draft = () => dialog?.draft;
  return div(
    s.overlay,
    { onMouseDown: (e) => { if (e.target === e.currentTarget) closeDialog(); }, onKeyDown: (e) => { if (e.key === "Escape") closeDialog(); } },
    form(
      s.dialog,
      { role: "dialog", "aria-modal": "true", "aria-label": () => (dialog?.card ? "Edit task" : "New task"), onSubmit: (e) => { e.preventDefault(); save(); } },
      div(s.dialogHead, h3(() => (dialog?.card ? `Edit task #${dialog.card.id}` : "New task")), button(s.icon, { type: "button", "aria-label": "Close", onClick: closeDialog }, "×")),
      Field("Title",
        input(s.input, { required: true, placeholder: "What needs to be done?", value: () => draft()?.title ?? "", onInput: (e) => { dialog!.draft.title = e.currentTarget.value; update(); } }, on("mount", (el) => el.focus()))),
      Field("Description",
        textarea(s.input, s.area, { rows: 3, placeholder: "Add some details (optional)", value: () => draft()?.description ?? "", onInput: (e) => { dialog!.draft.description = e.currentTarget.value; } })),
      div(s.row,
        Field("Assignee",
          select(s.input, { value: () => draft()?.assignee?.id ?? "", onChange: (e) => { dialog!.draft.assignee = users.find((u) => u.id === e.currentTarget.value) ?? null; update(); } },
            option({ value: "" }, "Unassigned"), ...users.map((u) => option({ value: u.id }, u.name)))),
        Field("Column",
          select(s.input, { value: () => dialog?.column.id ?? "", onChange: (e) => { dialog!.column = columns.find((c) => c.id === e.currentTarget.value)!; update(); } },
            ...columns.map((c) => option({ value: c.id }, c.title)))),
      ),
      div(s.field, span("Priority"),
        div(s.modes, { role: "radiogroup", "aria-label": "Priority" },
          ...PRIORITIES.map((p) =>
            button({ type: "button", role: "radio", class: () => cx(s.mode, draft()?.priority === p.value ? s.on : null).className, "aria-checked": () => String(draft()?.priority === p.value), onClick: () => { dialog!.draft.priority = p.value; update(); } }, p.label)))),
      div(s.dialogFoot,
        when(() => dialog?.card != null, button(s.danger, { type: "button", onClick: () => deleteCard(dialog!.card!) }, "Delete")),
        span(s.grow),
        button(s.btn, { type: "button", onClick: closeDialog }, "Cancel"),
        button(s.primary, { type: "submit", disabled: () => !draft()?.title.trim() }, () => (dialog?.card ? "Save" : "Add task")),
      ),
    ),
  );
}

export function KanbanBoard() {
  return div(
    s.app,
    Toolbar(),
    div(s.board, list(() => columns, ColumnView)),
    p(s.hint, "Drag cards within a column or across columns. ", strong(() => `${mounts} cards mounted`), ": reordering, assigning and editing never build a card. Moving it to another column, or filtering it back in, does."),
    when(() => undo !== null, div(s.toast, { role: "status" }, span(() => `Deleted “${undo?.card.title ?? ""}”`), button(s.link, { type: "button", onClick: undoDelete }, "Undo"))),
    when(() => dialog !== null, Dialog()),
  );
}

// board.ts: the model. Columns hold cards in plain arrays, and every change is
// a plain array operation on the same card objects. Nothing is copied or
// re-keyed: a card that moves is the same object before and after.

export interface User {
  id: string;
  name: string;
  color: string;
}

export interface Card {
  id: number;
  title: string;
  description: string;
  priority: 1 | 2 | 3; // 3 is urgent
  assignee: User | null; // the same object as in `users`, never a copy
}

export interface Column {
  id: string;
  title: string;
  cards: Card[];
}

export const users: User[] = [
  { id: "ana", name: "Ana Souza", color: "#e0586f" },
  { id: "ben", name: "Ben Carter", color: "#3b82c4" },
  { id: "chen", name: "Chen Wei", color: "#2f9e72" },
  { id: "dia", name: "Dia Patel", color: "#d98a1f" },
];
const [ana, ben, chen, dia] = users;

let nextId = 1;
const card = (title: string, priority: Card["priority"], assignee: User | null, description = ""): Card => ({ id: nextId++, title, description, priority, assignee });

export const columns: Column[] = [
  { id: "todo", title: "To do", cards: [
    card("Write the release notes", 2, ana, "Summarize the changes since the last tag."),
    card("Fix the flaky test", 3, ben, "The list diff test fails about one run in twenty."),
    card("Design the empty state", 1, null),
    card("Rotate the API keys", 3, dia),
  ] },
  { id: "doing", title: "In progress", cards: [card("Migrate the settings page", 2, chen, "Move it to the new form components."), card("Profile the list diff", 1, ben)] },
  { id: "done", title: "Done", cards: [card("Set up CI", 2, dia), card("Pick a logo", 1, ana)] },
];

export const PRIORITIES = [
  { value: 1, label: "Low" },
  { value: 2, label: "Normal" },
  { value: 3, label: "Urgent" },
] as const;

export const initials = (u: User) => u.name.split(" ").map((w) => w[0]).join("");

export const columnOf = (c: Card) => columns.find((col) => col.cards.includes(c))!;

/** Moves a card to `index` in `to`, from wherever it is now. */
export function move(c: Card, to: Column, index = to.cards.length) {
  const from = columnOf(c);
  const at = from.cards.indexOf(c);
  from.cards.splice(at, 1);
  if (from === to && at < index) index--;
  to.cards.splice(index, 0, c);
}

export interface Draft {
  title: string;
  description: string;
  priority: Card["priority"];
  assignee: User | null;
}

/** Puts a new card at the top of `col`. */
export function add(col: Column, draft: Draft): Card {
  const c = card(draft.title, draft.priority, draft.assignee, draft.description);
  col.cards.unshift(c);
  return c;
}

/** Edits a card in place, so its element is kept. */
export function edit(c: Card, draft: Draft) {
  Object.assign(c, draft);
}

/** Puts a deleted card back where it was. */
export function restore(c: Card, col: Column, index: number) {
  col.cards.splice(Math.min(index, col.cards.length), 0, c);
}

export function remove(c: Card) {
  const cards = columnOf(c).cards;
  cards.splice(cards.indexOf(c), 1);
}

export function cyclePriority(c: Card) {
  c.priority = c.priority === 3 ? 1 : ((c.priority + 1) as Card["priority"]);
}

export function sortByPriority(col: Column) {
  col.cards.sort((a, b) => b.priority - a.priority);
}

// app.ts: the inspector. There is no state of its own: every value on screen
// is read from the three.js object it belongs to, and every control writes
// to that object. The render loop calls update() once per frame, after
// three.js has moved things, and that is the only update() in this file.
import "nuclo";
import type * as THREE from "three";
import { createWorld, type World } from "./scene.ts";
import { s } from "./styles.ts";

let world: World | null = null;
let selected: THREE.Mesh | null = null;
let status = "Loading three.js…";

const meshes = () => world?.meshes() ?? [];
const material = (m: THREE.Mesh) => m.material as THREE.MeshStandardMaterial;
const hex = (m: THREE.Mesh) => `#${material(m).color.getHexString()}`;

function Stage() {
  return div(
    s.stage,
    canvas(
      s.canvas,
      on("mount", (el) => {
        let stop = () => {};
        createWorld(el).then((w) => {
          if (!el.isConnected) return w.dispose(); // closed before three.js arrived
          world = w;
          const box = el.parentElement!;
          const sizes = new ResizeObserver(() => w.resize(box.clientWidth, box.clientHeight));
          sizes.observe(box);
          const stopLoop = w.start(update); // every frame: sync the panel with the scene
          stop = () => { stopLoop(); sizes.disconnect(); w.dispose(); world = selected = null; };
        }).catch((err: Error) => { status = `three.js did not load: ${err.message}`; update(); });
        return () => stop();
      }),
      { onPointerDown: (e) => { selected = world?.pick(e.offsetX, e.offsetY) ?? null; } },
    ),
    when(() => world === null, p(s.loading, () => status)),
  );
}

function Row(mesh: THREE.Mesh) {
  return li(
    s.row,
    { class: () => cx(s.row, mesh === selected ? s.selected : null).className, onClick: () => { selected = mesh; } },
    span(s.swatch, { style: () => ({ backgroundColor: hex(mesh) }) }),
    span(s.name, mesh.name),
    span(s.coords, () => (mesh.visible ? `y ${mesh.position.y.toFixed(2)}  rot ${(mesh.rotation.y % 6.28).toFixed(2)}` : "hidden")),
  );
}

// Only on screen while something is selected, so `selected!` is safe here.
function Inspector() {
  const sel = () => selected!;
  return div(
    s.props,
    h4(s.propsTitle, () => sel().name),
    label(s.field, span("Color"), input({ type: "color", value: () => hex(sel()) }, { onInput: (e) => { material(sel()).color.set(e.currentTarget.value); } })),
    label(s.field, span("Scale"), input({ type: "range", min: "0.3", max: "2.5", step: "0.05", value: () => String(sel().scale.x) }, { onInput: (e) => { sel().scale.setScalar(Number(e.currentTarget.value)); } })),
    label(s.field, span("Spin"), input({ type: "range", min: "-3", max: "3", step: "0.1", value: () => String(sel().userData.spin) }, { onInput: (e) => { sel().userData.spin = Number(e.currentTarget.value); } })),
    label(s.check, input({ type: "checkbox", checked: () => sel().visible }, { onChange: () => { sel().visible = !sel().visible; } }), "Visible"),
    label(s.check, input({ type: "checkbox", checked: () => material(sel()).wireframe }, { onChange: () => { material(sel()).wireframe = !material(sel()).wireframe; } }), "Wireframe"),
    button(s.btn, "Remove", { onClick: () => { world?.remove(sel()); selected = null; } }),
  );
}

export function ThreeInspector() {
  return div(
    s.app,
    Stage(),
    aside(
      s.panel,
      div(s.panelHead, strong("Scene"), span(s.stats, () => `${meshes().length} objects · ${world?.fps ?? 0} fps · ${world?.renderer.info.render.triangles ?? 0} triangles`)),
      ul(s.list, list(meshes, Row)),
      when(() => selected !== null, Inspector()).else(p(s.hint, "Click an object, in the scene or in the list.")),
      button(s.btn, s.primary, "Add object", { onClick: () => { world?.add(); } }),
    ),
  );
}

// scene.ts: a plain three.js scene. three.js owns every object in it: the
// meshes, their positions, colors, visibility. Nothing here is written for a
// UI, and nothing is copied out of it: the inspector reads these objects
// where they live, and writes to them directly.
import type * as THREE from "three";

// Loaded on demand, so this page costs nothing until the scene mounts.
// In an app you would write: import * as THREE from "three".
const THREE_URL = "https://cdn.jsdelivr.net/npm/three@0.187.0/build/three.module.js";

export interface World {
  renderer: THREE.WebGLRenderer;
  fps: number;
  meshes(): THREE.Mesh[];
  add(): THREE.Mesh;
  remove(mesh: THREE.Mesh): void;
  pick(x: number, y: number): THREE.Mesh | null;
  resize(width: number, height: number): void;
  start(onFrame: () => void): () => void;
  dispose(): void;
}

export async function createWorld(canvas: HTMLCanvasElement): Promise<World> {
  const THREE: typeof import("three") = await import(/* @vite-ignore */ THREE_URL);

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 100);
  camera.position.set(0, 3.2, 8.5);
  camera.lookAt(0, 0, 0);
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  scene.add(new THREE.HemisphereLight(0xffffff, 0x334466, 1.6));
  const sun = new THREE.DirectionalLight(0xffffff, 2.2);
  sun.position.set(4, 6, 5);
  scene.add(sun);
  scene.add(new THREE.GridHelper(10, 10, 0x888888, 0x666666));

  const shapes = {
    Box: () => new THREE.BoxGeometry(1.2, 1.2, 1.2),
    Sphere: () => new THREE.SphereGeometry(0.75, 32, 16),
    Torus: () => new THREE.TorusGeometry(0.6, 0.25, 16, 48),
    Cone: () => new THREE.ConeGeometry(0.7, 1.4, 32),
    Knot: () => new THREE.TorusKnotGeometry(0.5, 0.18, 96, 12),
  };
  const kinds = Object.keys(shapes) as (keyof typeof shapes)[];
  let count = 0;

  const meshes = () => scene.children.filter((o): o is THREE.Mesh => o instanceof THREE.Mesh);

  // Spread the meshes on a ring, so the scene stays readable as it changes.
  function layout() {
    const all = meshes();
    all.forEach((m, i) => {
      const angle = (i / all.length) * Math.PI * 2 - Math.PI / 2;
      m.position.x = Math.cos(angle) * 3;
      m.position.z = Math.sin(angle) * 3;
    });
  }

  function add() {
    const kind = kinds[count % kinds.length];
    const color = new THREE.Color().setHSL((count * 0.17 + 0.05) % 1, 0.7, 0.55);
    const mesh = new THREE.Mesh(shapes[kind](), new THREE.MeshStandardMaterial({ color, roughness: 0.45 }));
    mesh.name = `${kind} ${++count}`;
    mesh.userData.spin = 0.8; // plain data on the object; the inspector edits it
    scene.add(mesh);
    layout();
    return mesh;
  }

  function remove(mesh: THREE.Mesh) {
    scene.remove(mesh);
    mesh.geometry.dispose();
    (mesh.material as THREE.Material).dispose();
    layout();
  }

  const raycaster = new THREE.Raycaster();
  const pointer = new THREE.Vector2();
  function pick(x: number, y: number) {
    pointer.set((x / canvas.clientWidth) * 2 - 1, -(y / canvas.clientHeight) * 2 + 1);
    raycaster.setFromCamera(pointer, camera);
    const hit = raycaster.intersectObjects(meshes())[0];
    return hit ? (hit.object as THREE.Mesh) : null;
  }

  function resize(width: number, height: number) {
    renderer.setSize(width, height, false);
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
  }

  const world: World = {
    renderer,
    fps: 0,
    meshes,
    add,
    remove,
    pick,
    resize,
    start(onFrame) {
      let last = performance.now();
      let frame = requestAnimationFrame(function loop(now) {
        const dt = Math.min((now - last) / 1000, 0.1);
        last = now;
        world.fps = Math.round(world.fps * 0.9 + (1 / dt) * 0.1);
        meshes().forEach((m, i) => {
          m.rotation.y += m.userData.spin * dt;
          m.position.y = Math.sin(now / 900 + i) * 0.3;
        });
        renderer.render(scene, camera);
        onFrame();
        frame = requestAnimationFrame(loop);
      });
      return () => cancelAnimationFrame(frame);
    },
    dispose() {
      lut.dispose();
      renderer.dispose();
    },
  };

  for (let i = 0; i < 5; i++) add();
  // three.js shares one lookup texture (DFG_LUT) between every renderer, and
  // that texture keeps each renderer that drew with it reachable, canvas and
  // page included, until it is disposed. Render once to get hold of it.
  renderer.render(scene, camera);
  const lut = (renderer.properties.get(meshes()[0].material) as { uniforms: { dfgLUT: { value: THREE.Texture } } }).uniforms.dfgLUT.value;
  return world;
}

// app.ts: the feed. Every page lands in the same plain array with push(), but
// only the rows near the viewport are in the DOM: the list() renders
// posts.slice(start, end), and two spacers stand in for everything above and
// below. Rows have one fixed height, so start and end are arithmetic on the
// scroll position. A row that scrolls away is dropped; its post object keeps
// its likes, and the same object gets a fresh row when it comes back.
// The sentinel at the real end asks for the next page before it comes into view.
import "nuclo";
import { fetchPage, type Post } from "./api.ts";
import { s } from "./styles.ts";

const ROW = 120; // px: every row is this tall, margin included
const OVERSCAN = 4; // rows rendered beyond each edge of the viewport

let posts: Post[] = [];
let next = 0; // the cursor of the next page
let loading = false;
let error: string | null = null;
let scrollTop = 0;
let viewport = 0; // the feed's visible height
let lookAgain: (() => void) | null = null; // set by the mounted sentinel: checks again whether it is in view

const start = () => Math.max(0, Math.floor(scrollTop / ROW) - OVERSCAN);
const end = () => Math.min(posts.length, Math.ceil((scrollTop + viewport) / ROW) + OVERSCAN);

async function loadMore() {
  if (loading || error !== null) return;
  loading = true;
  update();
  try {
    const page = await fetchPage(next);
    posts.push(...page.items);
    next = page.next;
  } catch (e) {
    error = (e as Error).message;
  }
  loading = false;
  update();
  lookAgain?.(); // a short page can leave the sentinel in view: then load the next one too
}

function retry() {
  error = null;
  loadMore();
}

function startOver() {
  posts = [];
  next = 0;
  error = null;
  scrollTop = 0;
  update();
  lookAgain?.();
}

const ago = (m: number) => (m < 60 ? `${m}m ago` : m < 1440 ? `${Math.round(m / 60)}h ago` : `${Math.round(m / 1440)}d ago`);

function PostView(post: Post) {
  return article(
    s.post,
    div(s.avatar, { style: { backgroundColor: `hsl(${(post.id * 47) % 360} 55% 48%)` } }, post.author[0]),
    div(
      s.body,
      div(s.meta, strong(post.author), span(ago(post.minutesAgo)), span(s.id, `#${post.id + 1}`)),
      p(post.text),
      button(
        s.like,
        { class: () => cx(s.like, post.liked ? s.liked : null).className, "aria-pressed": () => String(post.liked) },
        "♥ ",
        () => String(post.likes),
        { onClick: () => { post.liked = !post.liked; post.likes += post.liked ? 1 : -1; update(); } },
      ),
    ),
  );
}

const Skeleton = () => div(s.skeleton, div(s.bone, s.boneAvatar), div(s.boneLines, div(s.bone), div(s.bone, s.boneShort)));

function Sentinel() {
  return div(
    s.sentinel,
    on("mount", (el) => {
      const observer = new IntersectionObserver(
        ([entry]) => { if (entry.isIntersecting) loadMore(); },
        { root: el.parentElement, rootMargin: "800px" }, // start the next page well before the end is reached
      );
      observer.observe(el);
      lookAgain = () => { observer.unobserve(el); observer.observe(el); };
      return () => { observer.disconnect(); lookAgain = null; }; // left set, it would keep this element alive
    }),
    when(() => loading, Skeleton(), Skeleton(), Skeleton())
      .when(() => error !== null, div(s.error, span(() => error ?? ""), button(s.btn, "Retry", { onClick: retry }))),
  );
}

export function InfiniteFeed() {
  return div(
    s.app,
    header(
      s.head,
      strong(() => `${posts.length} posts`),
      span(s.state, () => `${end() - start()} rows in the DOM · ${loading ? "loading…" : error !== null ? "failed" : "scroll, it never ends"}`),
      button(s.btn, "Start over", { disabled: () => loading, onClick: startOver }),
    ),
    div(
      s.feed,
      on("mount", (el) => {
        // The state outlives the element: a feed built again (the page was left
        // and reopened) resumes where it was, instead of windowing for a scroll
        // position its new element does not have.
        el.scrollTop = scrollTop;
        scrollTop = el.scrollTop;
        const sizes = new ResizeObserver(() => { viewport = el.clientHeight; update(); });
        sizes.observe(el);
        return () => sizes.disconnect();
      }),
      { onScroll: (e) => { scrollTop = e.currentTarget.scrollTop; update(); } },
      div({ style: () => ({ height: `${start() * ROW}px` }) }),
      list(() => posts.slice(start(), end()), PostView),
      div({ style: () => ({ height: `${(posts.length - end()) * ROW}px` }) }),
      Sentinel(),
    ),
  );
}

// api.ts: a fake backend with no end. fetchPage() behaves like a real request:
// it takes a moment and answers with one page and the cursor of the next.
// Rows are generated on the fly from their id, so
// the same cursor always returns the same page. Nothing here knows about the UI.

export interface Post {
  id: number;
  author: string;
  text: string;
  likes: number;
  liked: boolean;
  minutesAgo: number;
}

export interface Page {
  items: Post[];
  next: number; // the cursor of the next page
}

const PAGE_SIZE = 20;

const AUTHORS = ["Ada", "Grace", "Linus", "Margaret", "Dennis", "Barbara", "Ken", "Radia", "Edsger", "Frances", "Tony", "Yukihiro"];
const OPENERS = ["Shipped", "Fixed", "Rewrote", "Profiled", "Deleted half of", "Paired on", "Reviewed", "Benchmarked", "Documented", "Simplified"];
const SUBJECTS = ["the list diff", "the kanban demo", "the router", "the fake fetch", "the docs build", "the three.js inspector", "the form validation", "the SSR hydration", "the style engine", "the undo stack"];
const OUTCOMES = ["and it is faster now.", "with half the code.", "before lunch.", "and nothing re-rendered.", "and found the slow part.", "in one update() call.", "without a store.", "by mutating the array in place.", "and the mount count stayed put.", "while this feed kept loading."];
const EXTRAS = ["Breakpoint at update() showed every change.", "Rows already on screen were never rebuilt.", "The sentinel loaded the next page early.", "Plain objects, plain arrays, one update()."];

// A small integer hash: every field of a post is a deterministic function of its id.
function hash(n: number) {
  n = Math.imul(n ^ (n >>> 16), 0x45d9f3b);
  n = Math.imul(n ^ (n >>> 16), 0x45d9f3b);
  return (n ^ (n >>> 16)) >>> 0;
}
const pick = <T,>(list: T[], id: number, salt: number) => list[hash(id * 31 + salt) % list.length];

function post(id: number): Post {
  let text = `${pick(OPENERS, id, 1)} ${pick(SUBJECTS, id, 2)} ${pick(OUTCOMES, id, 3)}`;
  if (hash(id) % 3 === 0) text += ` ${pick(EXTRAS, id, 4)}`;
  return { id, author: pick(AUTHORS, id, 5), text, likes: hash(id + 7) % 900, liked: false, minutesAgo: id * 3 + 1 };
}

export function fetchPage(cursor: number): Promise<Page> {
  return new Promise((resolve) => {
    setTimeout(() => {
      const items = Array.from({ length: PAGE_SIZE }, (_, i) => post(cursor + i));
      resolve({ items, next: cursor + PAGE_SIZE });
    }, 60 + Math.random() * 140);
  });
}

