      button(s.ctl, { title: () => (win.maximized ? "Restore" : "Maximize"), "aria-label": "Maximize", "aria-pressed": () => String(win.maximized), onClick: () => { toggleMaximize(win); winUpdate(win); } }, icon("maximize", 14)),
