function Clock() {
  return time(
    s.clock,
    scope("os-clock"),
    on("mount", () => {
      const tick = () => { const now = new Date(); clock = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }); date = now.toLocaleDateString([], { month: "short", day: "numeric" }); update("os-clock"); };
      tick();
      const id = setInterval(tick, 30000);
      return () => clearInterval(id);
    }),
    span(() => clock), span(s.clockDate, () => date),
  );
}

export function Desktop() {
  return div(
    s.app,
    contextMenuLifecycle(),
    {
      tabIndex: -1,
      "data-wallpaper": () => appearance.wallpaper,
      onContextMenu: (e) => {
        if (e.defaultPrevented) return;
        if ((e.target as Element).closest(".os-backdrop")) { e.preventDefault(); return; }
        const id = (e.target as Element).closest("[data-os-window]")?.getAttribute("data-os-window");
        const win = windows.find((win) => String(win.id) === id);
        menuOpen = false;
        showContextMenu(e, win?.title ?? "Desktop", win ? windowActions(win) : desktopActions());
      },
      onKeyDown: (e) => {
        if (e.key === "Escape" && menuOpen) { e.stopPropagation(); menuOpen = false; update("os-taskbar"); }
        if (e.key !== "ContextMenu" && !(e.shiftKey && e.key === "F10")) return;
        if ((e.target as Element).closest(".os-backdrop")) { e.preventDefault(); return; }
        const id = (e.target as Element).closest("[data-os-window]")?.getAttribute("data-os-window");
        const win = windows.find((win) => String(win.id) === id);
        contextMenuKey(e, win?.title ?? "Desktop", win ? windowActions(win) : desktopActions());
      },
    },
    on("mount", () => {
      if (!diskLoaded) { loadDisk(); diskLoaded = true; }
      try { const saved = localStorage.getItem("nuclo-desktop-wallpaper"); if (saved && ["grove", "dusk", "slate"].includes(saved)) appearance.wallpaper = saved; } catch {}
      update();
    }),
    div(
      s.desk,
      on("mount", (el) => {
        const sizes = new ResizeObserver(() => {
          if (!el.clientWidth) return; // hidden while a source tab is showing: keep the windows as they are
          setDesk(el.clientWidth, el.clientHeight);
          if (!booted) {
            const welcome = getEntry("welcome");
            if (welcome) {
              openFile(welcome);
              const win = windows.at(-1)!;
              move(win, el.clientWidth - win.w - 24, 36);
            }
            booted = true;
          }
          update();
        });
        sizes.observe(el);
        return () => sizes.disconnect();
      }),
      { tabIndex: 0, "aria-haspopup": "menu", "aria-label": "Desktop workspace", onContextMenu: (e) => {
        if ((e.target as Element).closest("[data-os-window], .os-icon")) return;
        menuOpen = false; showContextMenu(e, "Desktop", desktopActions());
      }, onKeyDown: (e) => { if (e.target === e.currentTarget) contextMenuKey(e, "Desktop", desktopActions()); }, onPointerDown: () => { if (menuOpen) { menuOpen = false; update("os-taskbar"); } } },
      div(s.wallpaper, { "aria-hidden": "true" }, div(s.orbit), div(s.orbit, s.orbitTwo)),
      div(s.desktopHeading, strong("A little room to work."), span("Your files. Your ideas. Your pace.")),
      div(s.icons, ...Object.values(PROGRAMS).slice(0, 7).map(Icon)),
      list(() => windows, WindowView),
    ),
    footer(
      s.taskbar,
      scope("os-taskbar"),
      button(s.start, { "aria-expanded": () => String(menuOpen), onClick: () => { dismissContextMenu(); menuOpen = !menuOpen; update("os-taskbar"); } }, icon("grid", 18), span("Apps")),
      when(() => menuOpen, nav(s.menu, { "aria-label": "Applications" },
        div(s.launcherHeading, strong("Your workspace"), span("Find something to open")),
        input(s.input, { type: "search", "aria-label": "Search apps", placeholder: "Search apps…", value: () => search, onMount: (el) => el.focus(), onInput: (e) => { search = e.currentTarget.value; update("os-taskbar"); }, onKeyDown: (e) => { if (e.key === "Enter") { const program = Object.values(PROGRAMS).find((p) => p.name.toLowerCase().includes(search.toLowerCase())); if (program) { open(program); menuOpen = false; update(); } } } }),
        list(() => Object.values(PROGRAMS).filter((p) => p.name.toLowerCase().includes(search.toLowerCase())), (p) => button(s.item, { onClick: () => { menuOpen = false; open(p); update(); } }, icon(p.icon), p.name)),
        when(() => !Object.values(PROGRAMS).some((p) => p.name.toLowerCase().includes(search.toLowerCase())), p(s.empty, "No matching apps")),
      )),
      div(s.tasks, list(() => windows, TaskButton)),
      button(s.showDesktop, { title: "Show desktop", "aria-label": "Show desktop", onClick: () => { for (const win of windows) minimize(win); update(...windows.map((win) => winScopeId(win)), "os-taskbar"); } }, icon("minimize", 18)),
      // The tray: programs put their own icons here with into("os-tray", ...).
      div(s.tray, region({ id: "os-tray", type: "stack" }), Clock()),
    ),
    // The modal layer, over the desktop and the taskbar. The context menu
    // list runs inside its own wrapper, so its scope stays out of the windows.
    div(scope("os-context-menu"), ContextMenu()),
    region({ id: "os-modal", type: "stack" }),
  );
}

// windows.ts: the window manager. A window is a plain object in one array,
// and every operation is a few assignments on it. Focus raises a window by
// handing it the next z-index, not by moving it to the end of the array: the
// list() that draws the windows never moves an element, so a textarea keeps
// its text, its caret and its focus. Nothing here knows about the UI.
import type { Program } from "./programs.ts";

export interface Win<S = unknown> {
  id: number;
  program: Program<S>;
  title: string;
  x: number; y: number; w: number; h: number; // px, inside the desktop
  z: number; // the highest is on top
  minimized: boolean;
  maximized: boolean;
  confirming: boolean; // asking whether to throw away unsaved work
  state: S; // the program's state lives on its window, so it outlives the view
}

const MIN = { w: 300, h: 220 };

export const windows: Win[] = [];
const desk = { w: 960, h: 520 }; // the desktop's size: a guess on the server, measured in the browser
let topZ = 0; // the highest z-index handed out so far
let nextId = 1;

const clamp = (v: number, max: number) => Math.max(0, Math.min(v, max));

/** The topmost window that is not minimized. */
export const active = () => windows.reduce<Win | null>((a, w) => (!w.minimized && (!a || w.z > a.z) ? w : a), null);

export function open<S>(program: Program<S>): Win<S> {
  const step = (windows.length % 6) * 28; // cascade: each new window a little lower and to the right
  const [w, h] = program.size;
  const win: Win<S> = {
    id: nextId++, program, title: program.name, x: 0, y: 0, w: Math.max(1, Math.min(w, desk.w - 16)), h: Math.max(1, Math.min(h, desk.h - 16)),
    z: ++topZ, minimized: false, maximized: false, confirming: false, state: program.init(),
  };
  move(win, 104 + step, 16 + step); // right of the desktop icons
  windows.push(win);
  return win;
}

export function close(win: Win) {
  const index = windows.indexOf(win);
  if (index !== -1) windows.splice(index, 1);
}

/** Closes it, unless its program has unsaved work: then it asks first. */
export function requestClose(win: Win) {
  if (win.program.unsaved?.(win)) win.confirming = true;
  else close(win);
}

/** Raises it, restoring it if it was minimized. The array order never changes. */
export function focus(win: Win) {
  win.minimized = false;
  if (win.z !== topZ) win.z = ++topZ;
}

/**
 * The update scope id of a window's element. The desktop tags each window
 * with scope(winScopeId(win)), so update(winScopeId(win)) re-evaluates that
 * window and nothing else — other windows, the taskbar and the desktop stay
 * untouched. Programs use it for their own keystrokes, ticks and drags, and
 * the window manager adds "os-taskbar" when the task buttons need it too.
 */
export const winScopeId = (win: Win) => `os-win-${win.id}`;

/** The scope ids of every window running `program`, for data its windows share. */
export const scopesOf = (program: Program) => windows.filter((w) => w.program === program).map(winScopeId);

export function minimize(win: Win) {
  win.minimized = true;
}

export function toggleMaximize(win: Win) {
  win.maximized = !win.maximized;
}

export function move(win: Win, x: number, y: number) {
  win.x = clamp(x, desk.w - win.w);
  win.y = clamp(y, desk.h - win.h);
}

export function resize(win: Win, w: number, h: number) {
  win.w = Math.min(desk.w - win.x, Math.max(MIN.w, w));
  win.h = Math.min(desk.h - win.y, Math.max(MIN.h, h));
}

/** The desktop changed size: every window shrinks and moves back inside it. */
export function setDesk(w: number, h: number) {
  desk.w = w;
  desk.h = h;
  for (const win of windows) {
    win.w = Math.min(win.w, w);
    win.h = Math.min(win.h, h);
    move(win, win.x, win.y);
  }
}

// programs.ts: what runs in the windows. A program is a plain object: a name,
// an icon, a default size, init() for the state of a new window, and a view
// of that state. The state is kept on the window, so leaving the example and
// coming back builds the views again around the same note, sum, shell
// history and board. The Timer reaches outside its window: while it runs, it
// puts its countdown in the taskbar tray with into().
import "nuclo";
import { focus, open, windows, winScopeId, type Win } from "./windows.ts";
import { contextMenuKey, showContextMenu } from "./context-menu.ts";
import { icon } from "./icons.ts";
import { available, children, createEntry, entries, getEntry, moveEntry, pathOf, renameEntry, resolvePath, restoreEntry, storageStatus, trashEntry, writeEntry, type Entry } from "./filesystem.ts";
