// A simulated disk shared by Files, Notes and Terminal. Only browser-local data.
export interface Entry { id: string; parent: string; name: string; kind: "folder" | "file"; content: string; modified: number; trashed: boolean }
const KEY = "nuclo-desktop-disk-v1";
const seed = (): Entry[] => [
  { id: "documents", parent: "root", name: "Documents", kind: "folder", content: "", modified: 0, trashed: false },
  { id: "projects", parent: "root", name: "Projects", kind: "folder", content: "", modified: 0, trashed: false },
  { id: "welcome", parent: "documents", name: "Welcome.txt", kind: "file", content: "Welcome to your workspace.\n\nMake yourself at home. Open Files to create folders and notes, or try the Terminal. Everything shares the same simulated disk.\n\nYour files stay in this browser between visits. Nothing is uploaded.\n\nA few things to try\n\n• Create a note in Documents, write something, and save.\n• Rename or move a file, then find it in Terminal.\n• Move a file to Trash and restore it.\n• Drag windows, double-click a title to maximize, or use the taskbar to switch apps.\n", modified: 0, trashed: false },
  { id: "ideas", parent: "documents", name: "Ideas.txt", kind: "file", content: "A little room for big ideas.\n\n- A reading list\n- A weekend project\n- Something worth remembering\n", modified: 0, trashed: false },
  { id: "readme", parent: "projects", name: "Readme.txt", kind: "file", content: "My projects\n\nStart with a folder. Make something good.\n", modified: 0, trashed: false },
];
export const entries = seed();
export let storageStatus = "Saved in this browser";
export const getEntry = (id: string) => entries.find((entry) => entry.id === id);
export function available(id: string): boolean {
  if (id === "root") return true;
  const entry = getEntry(id);
  return !!entry && !entry.trashed && available(entry.parent);
}
export const children = (parent: string) => entries.filter((entry) => entry.parent === parent && !entry.trashed).sort((a, b) => Number(b.kind === "folder") - Number(a.kind === "folder") || a.name.localeCompare(b.name));
export const pathOf = (id: string): string => id === "root" ? "/" : getEntry(id) ? `${pathOf(getEntry(id)!.parent).replace(/\/$/, "")}/${getEntry(id)!.name}` : "/";
export function resolvePath(path: string, cwd = "root") {
  let id = path.startsWith("/") ? "root" : cwd;
  for (const part of path.split("/").filter(Boolean)) {
    if (part === ".") continue;
    if (part === "..") { id = getEntry(id)?.parent ?? "root"; continue; }
    if (id !== "root" && getEntry(id)?.kind !== "folder") return undefined;
    const entry = children(id).find((entry) => entry.name === part);
    if (!entry || !available(entry.id)) return undefined;
    id = entry.id;
  }
  return available(id) ? id : undefined;
}
export function persist() {
  try { localStorage.setItem(KEY, JSON.stringify(entries)); storageStatus = "Saved in this browser"; }
  catch { storageStatus = "Browser storage unavailable · files stay for this session"; }
}
export function loadDisk() {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return;
    const saved: unknown = JSON.parse(raw);
    if (!Array.isArray(saved) || !saved.every((e) => e && typeof e.id === "string" && e.id !== "root" && typeof e.parent === "string" && typeof e.name === "string" && e.name.trim() && !/[\/\\]/.test(e.name) && ["file", "folder"].includes(e.kind) && typeof e.content === "string" && typeof e.modified === "number" && typeof e.trashed === "boolean")) throw new Error("Invalid disk");
    const ids = new Set(saved.map((e) => e.id));
    if (ids.size !== saved.length) throw new Error("Duplicate IDs");
    for (const entry of saved) {
      const seen = new Set([entry.id]);
      let parent = entry.parent;
      while (parent !== "root") {
        const folder = saved.find((e) => e.id === parent);
        if (!folder || folder.kind !== "folder" || seen.has(parent)) throw new Error("Invalid folder tree");
        seen.add(parent); parent = folder.parent;
      }
      if (saved.some((e) => e !== entry && !e.trashed && !entry.trashed && e.parent === entry.parent && e.name === entry.name)) throw new Error("Duplicate names");
    }
    entries.splice(0, entries.length, ...saved);
  } catch { storageStatus = "Could not load saved disk · using starter files"; }
}
function validateName(parent: string, name: string, except?: string) {
  if (!name.trim() || name !== name.trim() || name === "." || name === ".." || /[\/\\\x00-\x1f]/.test(name) || name.length > 80) throw new Error("Use 1–80 characters without slashes or surrounding spaces.");
  if (!available(parent) || (parent !== "root" && getEntry(parent)?.kind !== "folder")) throw new Error("That folder is no longer available.");
  if (children(parent).some((entry) => entry.name === name && entry.id !== except)) throw new Error("An item with that name already exists.");
}
export function createEntry(parent: string, name: string, kind: Entry["kind"]) {
  validateName(parent, name);
  const entry: Entry = { id: crypto.randomUUID(), parent, name, kind, content: "", modified: Date.now(), trashed: false };
  entries.push(entry); persist(); return entry;
}
export function renameEntry(id: string, name: string) {
  const entry = getEntry(id);
  if (!entry || !available(id)) throw new Error("That item is no longer available.");
  validateName(entry.parent, name, id); entry.name = name; persist();
}
export function moveEntry(id: string, parent: string) {
  const entry = getEntry(id);
  if (!entry || !available(id)) throw new Error("That item is no longer available.");
  let ancestor = parent;
  while (ancestor !== "root") {
    if (ancestor === id) throw new Error("A folder cannot be moved inside itself.");
    ancestor = getEntry(ancestor)?.parent ?? "root";
  }
  validateName(parent, entry.name, id); entry.parent = parent; persist();
}
export function trashEntry(id: string) {
  const entry = getEntry(id);
  if (!entry || !available(id)) throw new Error("That item is no longer available.");
  entry.trashed = true; persist();
}
export function restoreEntry(id: string) {
  const entry = getEntry(id);
  if (!entry?.trashed) throw new Error("That item is not in Trash.");
  const parent = available(entry.parent) ? entry.parent : "root";
  validateName(parent, entry.name, id); entry.parent = parent; entry.trashed = false; persist();
}
export function writeEntry(id: string, content: string, expected?: string) {
  const entry = getEntry(id);
  if (!entry || entry.kind !== "file" || !available(id)) throw new Error("This file was moved to Trash. Restore it in Files before saving.");
  if (expected !== undefined && entry.content !== expected) throw new Error("This file changed in another window. Save a copy to keep your edits.");
  entry.content = content; entry.modified = Date.now(); persist();
}

// board.ts: the Kanban model for the desktop. Columns hold cards in plain
// arrays, and every change is a few plain array operations on the same card
// objects. The board is one shared, saved board: each change is written to
// localStorage, and loadBoard() puts the saved board back on the next visit —
// like the files on the simulated disk.
export interface Card { id: number; title: string; priority: 1 | 2 | 3 } // 3 is urgent
export interface Column { id: string; title: string; cards: Card[] }

const KEY = "nuclo-desktop-board-v1";

let nextId = 1;
const card = (title: string, priority: Card["priority"]): Card => ({ id: nextId++, title, priority });

const seed = (): Column[] => [
  { id: "todo", title: "To do", cards: [card("Write the release notes", 3), card("Fix the flaky test", 2), card("Design the empty state", 1)] },
  { id: "doing", title: "In progress", cards: [card("Ship the desktop", 2), card("Profile the list diff", 1)] },
  { id: "done", title: "Done", cards: [card("Set up CI", 2), card("Pick a logo", 1)] },
];

/** The board every Kanban window reads. loadBoard() may replace it with the saved one. */
export const columns: Column[] = seed();

let booted = false;

/** Replaces the seed with the saved board, once, when the app starts in a browser. */
export function loadBoard() {
  if (booted) return;
  booted = true;
  try {
    const saved = localStorage.getItem(KEY);
    if (!saved) return;
    const parsed = JSON.parse(saved) as Column[];
    const valid = (c: Column) => c && typeof c.id === "string" && typeof c.title === "string" && Array.isArray(c.cards) && c.cards.every((k) => k && typeof k.id === "number" && typeof k.title === "string");
    if (!Array.isArray(parsed) || !parsed.every(valid)) return;
    nextId = parsed.flatMap((c) => c.cards).reduce((max, k) => Math.max(max, k.id), 0) + 1;
    columns.splice(0, columns.length, ...parsed);
  } catch {}
}

export function saveBoard() {
  try { localStorage.setItem(KEY, JSON.stringify(columns)); } catch {}
}

/** Starts the board over. */
export function resetBoard() {
  columns.splice(0, columns.length, ...seed());
  saveBoard();
}

export const columnOf = (c: Card) => columns.find((col) => col.cards.includes(c))!;

/** Moves a card to `index` in `to`, from wherever it is now. */
export function moveCard(c: Card, to: Column, index = to.cards.length) {
  const from = columnOf(c);
  const at = from.cards.indexOf(c);
  from.cards.splice(at, 1);
  if (from === to && at < index) index--;
  to.cards.splice(index, 0, c);
  saveBoard();
}

export function addCard(col: Column, title: string) {
  col.cards.unshift(card(title, 2));
  saveBoard();
}

export function removeCard(c: Card) {
  const cards = columnOf(c).cards;
  cards.splice(cards.indexOf(c), 1);
  saveBoard();
}

export function cyclePriority(c: Card) {
  c.priority = c.priority === 3 ? 1 : ((c.priority + 1) as Card["priority"]);
  saveBoard();
}

export function sortByPriority(col: Column) {
  col.cards.sort((a, b) => b.priority - a.priority);
  saveBoard();
}

// kanban.ts: the Kanban window. The model lives in board.ts, shared by every
// window and saved after each change; this file is the view. Columns are a
// list() of columns, cards a list() of each column's cards. Rows are matched
// by identity, so dragging a card, sorting a column or renaming a card
// splices or patches the same objects and the elements just move. Every
// Kanban window shows the same board, so a change refreshes all of them; the
// forms being typed in belong to their own window.
import "nuclo";
import type { Program } from "./programs.ts";
import { addCard, columns, cyclePriority, loadBoard, moveCard, removeCard, resetBoard, saveBoard, sortByPriority, type Card, type Column } from "./board.ts";
import { scopesOf, type Win } from "./windows.ts";
import { s } from "./styles.ts";

interface Forms {
  adding: Column | null; // the column whose new-card form is open
  draft: string; // the title being typed in that form
  editing: Card | null; // the card whose title is being typed
  editDraft: string;
}
type KanbanWin = Win<Forms>;

const PRIORITY = { 1: "low", 2: "normal", 3: "urgent" };

// One drag at a time, across every Kanban window: a card can be dropped into another one.
let dragging: Card | null = null;
let over: { win: KanbanWin; column: Column; index: number } | null = null; // where it would land

/** The board is shared, so every Kanban window updates, and nothing else. */
const refresh = () => update(...scopesOf(kanban));

const isOver = (win: KanbanWin, column: Column, index: number) => over?.win === win && over.column === column && over.index === index;

function setOver(win: KanbanWin, column: Column, index: number) {
  if (isOver(win, column, index)) return;
  over = { win, column, index };
  refresh();
}

function drop() {
  if (dragging && over) moveCard(dragging, over.column, over.index);
  dragging = over = null;
  refresh();
}

function startEdit(forms: Forms, card: Card) {
  forms.editing = card;
  forms.editDraft = card.title;
  refresh();
}

function commitEdit(forms: Forms, card: Card) {
  if (forms.editing !== card) return;
  const title = forms.editDraft.trim();
  if (title) card.title = title;
  forms.editing = null;
  saveBoard();
  refresh();
}

function CardView(win: KanbanWin, card: Card, column: Column) {
  const forms = win.state;
  return div(
    s.kanbanCard,
    { draggable: true, tabIndex: 0 },
    { class: () => cx(s.kanbanCard, card === dragging ? s.kanbanLifted : null, isOver(win, column, column.cards.indexOf(card)) ? s.kanbanBefore : null).className },
    {
      onKeyDown: (e) => { if (e.key === "Enter" && e.target === e.currentTarget) startEdit(forms, card); },
      onDragStart: (e) => { e.dataTransfer?.setData("text/plain", card.title); dragging = card; refresh(); },
      onDragEnd: () => { dragging = over = null; refresh(); },
      onDragOver: (e) => {
        e.preventDefault();
        e.stopPropagation();
        const below = e.offsetY > e.currentTarget.offsetHeight / 2;
        setOver(win, column, column.cards.indexOf(card) + (below ? 1 : 0));
      },
    },
    div(s.kanbanCardHead,
      button(s.kanbanPriority, { title: "Change priority", class: () => cx(s.kanbanPriority, s[`kanbanP${card.priority}`]).className, onClick: () => { cyclePriority(card); refresh(); } }, () => PRIORITY[card.priority]),
      span(s.kanbanId, `#${card.id}`),
      button(s.kanbanIcon, { title: "Move to top", "aria-label": "Move to top", onClick: () => { moveCard(card, column, 0); refresh(); } }, "↑"),
      button(s.kanbanIcon, { title: "Delete", "aria-label": "Delete", onClick: () => { removeCard(card); refresh(); } }, "×"),
    ),
    when(() => forms.editing === card,
      input(s.kanbanEdit, { "aria-label": "Card title", value: () => forms.editDraft, onMount: (el) => { el.focus(); el.select(); }, onInput: (e) => { forms.editDraft = e.currentTarget.value; }, onKeyDown: (e) => { if (e.key === "Enter") commitEdit(forms, card); else if (e.key === "Escape") { forms.editing = null; refresh(); } }, onBlur: () => { if (forms.editing === card) commitEdit(forms, card); } }),
    ).else(div(s.kanbanTitle, { title: "Double-click to edit", onDblClick: () => startEdit(forms, card) }, () => card.title)),
  );
}

function ColumnView(win: KanbanWin, column: Column) {
  const forms = win.state;
  return section(
    s.kanbanColumn,
    { class: () => cx(s.kanbanColumn, isOver(win, column, column.cards.length) ? s.kanbanAfter : null).className },
    {
      onDragOver: (e) => { e.preventDefault(); setOver(win, column, column.cards.length); },
      onDragLeave: (e) => { if (!e.currentTarget.contains(e.relatedTarget as Node | null)) { over = null; refresh(); } },
      onDrop: (e) => { e.preventDefault(); drop(); },
    },
    header(s.kanbanColumnHead,
      h3(column.title, span(s.kanbanCount, () => String(column.cards.length))),
      button(s.kanbanSmall, { title: "Sort by priority", onClick: () => { sortByPriority(column); refresh(); } }, "Sort"),
      button(s.kanbanSmall, { title: () => (forms.adding === column ? "Close the form" : "Add a task"), "aria-pressed": () => String(forms.adding === column), onClick: () => { forms.adding = forms.adding === column ? null : column; forms.draft = ""; refresh(); } }, "+ Add"),
    ),
    when(() => forms.adding === column, form(s.kanbanAdd, { onSubmit: (e) => { e.preventDefault(); if (forms.draft.trim()) { addCard(column, forms.draft.trim()); forms.draft = ""; forms.adding = null; } refresh(); } },
      input(s.input, { "aria-label": "New task title", placeholder: "What needs to be done?", value: () => forms.draft, onMount: (el) => el.focus(), onInput: (e) => { forms.draft = e.currentTarget.value; }, onKeyDown: (e) => { if (e.key === "Escape") { forms.adding = null; refresh(); } } }),
      button(s.btn, s.primary, { type: "submit" }, "Add"),
    )),
    div(s.kanbanCards,
      list(() => column.cards, (card) => CardView(win, card, column)),
      when(() => !column.cards.length, p(s.kanbanEmpty, "Drop a task here.")),
    ),
  );
}

export const kanban: Program<Forms> = {
  name: "Kanban", icon: "kanban", size: [660, 400],
  init: () => { loadBoard(); return { adding: null, draft: "", editing: null, editDraft: "" }; },
  view: (win) => div(s.kanban,
    div(s.toolbar,
      strong(s.kanbanHeading, "Board"),
      span(s.kanbanHint, "Drag cards between columns · saved in this browser"),
      button(s.btn, "Reset", { title: "Start the board over", onClick: () => { resetBoard(); refresh(); } }),
    ),
    div(s.kanbanBoard, list(() => columns, (column) => ColumnView(win, column))),
  ),
};

// calendar.ts: a month calendar for the desktop. The grid is plain Date math
// over the window's state, and each day can carry a short note, kept in one
// small object saved to localStorage — like the wallpaper and the board.
import "nuclo";
import type { Program } from "./programs.ts";
import { winScopeId } from "./windows.ts";
import { icon } from "./icons.ts";
import { s } from "./styles.ts";

const KEY = "nuclo-desktop-calendar-v1";
const WEEKDAYS = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"];
const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
// Hand-rolled (no Intl): the 42 day labels re-evaluate on every calendar update.
const FULL_DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

const keyOf = (year: number, month: number, day: number) => `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
const labelOf = (key: string) => {
  const [y, m, d] = key.split("-").map(Number);
  const date = new Date(y, m - 1, d);
  return `${FULL_DAYS[date.getDay()]}, ${MONTHS[m - 1]} ${d}`;
};

let notes: Record<string, string> = {};
function loadNotes() {
  try { const saved = localStorage.getItem(KEY); if (saved) notes = JSON.parse(saved); } catch {}
}
const saveNotes = () => { try { localStorage.setItem(KEY, JSON.stringify(notes)); } catch {} };

interface CalState { year: number; month: number; selected: string } // month: 0-11, selected: "YYYY-MM-DD"

export const calendar: Program<CalState> = {
  name: "Calendar", icon: "calendar", size: [360, 430],
  init: () => {
    loadNotes();
    const now = new Date();
    return { year: now.getFullYear(), month: now.getMonth(), selected: keyOf(now.getFullYear(), now.getMonth(), now.getDate()) };
  },
  view: (win) => {
    const state = win.state;
    const refresh = () => update(winScopeId(win)); // the calendar updates only its window
    const now = new Date();
    const today = keyOf(now.getFullYear(), now.getMonth(), now.getDate());
    const lead = (new Date(state.year, state.month, 1).getDay() + 6) % 7; // Monday-first
    const days = new Date(state.year, state.month + 1, 0).getDate();
    const cells: ({ day: number; key: string } | null)[] = [
      ...Array.from({ length: lead }, () => null),
      ...Array.from({ length: days }, (_, i) => ({ day: i + 1, key: keyOf(state.year, state.month, i + 1) })),
    ];
    const moveMonth = (dir: number) => {
      const next = new Date(state.year, state.month + dir, 1);
      Object.assign(state, { year: next.getFullYear(), month: next.getMonth() });
      refresh();
    };
    const goToday = () => {
      Object.assign(state, { year: now.getFullYear(), month: now.getMonth(), selected: today });
      refresh();
    };
    return div(s.calendar,
      div(s.toolbar,
        button(s.btn, { "aria-label": "Previous month", onClick: () => moveMonth(-1) }, icon("back", 15)),
        strong(s.calMonth, () => `${MONTHS[state.month]} ${state.year}`),
        button(s.btn, { "aria-label": "Next month", onClick: () => moveMonth(1) }, icon("forward", 15)),
        button(s.btn, "Today", { onClick: goToday }),
      ),
      div(s.calGrid,
        ...WEEKDAYS.map((day) => span(s.calWeekday, day)),
        ...cells.map((cell) => cell ? button(s.calDay, {
          "aria-label": () => labelOf(cell.key),
          "aria-pressed": () => String(state.selected === cell.key),
          "aria-current": () => (cell.key === today ? "date" : "false"),
          class: () => cx(s.calDay, cell.key === today ? s.calToday : null).className,
          onClick: () => { state.selected = cell.key; refresh(); },
        }, String(cell.day), when(() => !!notes[cell.key], span(s.calDot))) : span(s.calGap)),
      ),
      div(s.calNote,
        div(s.calNoteHead,
          strong(() => labelOf(state.selected)),
          button(s.btn, "Clear", { disabled: () => !notes[state.selected], onClick: () => { delete notes[state.selected]; saveNotes(); refresh(); } }),
        ),
        textarea(s.calInput, { "aria-label": "Note for the selected day", placeholder: "A note for this day…", value: () => notes[state.selected] ?? "", onInput: (e) => { const value = e.currentTarget.value; if (value) notes[state.selected] = value; else delete notes[state.selected]; saveNotes(); refresh(); } }),
      ),
    );
  },
};

// money.ts: the Finance model. Transactions are plain objects in one array,
// and every chart is a few reduce() calls over them. Pure: no DOM, no
// storage, so it can be unit-tested and reused by the spreadsheet and the
// charts alike. Amounts are plain numbers; a negative amount is spending.
export interface Tx { id: number; date: string; description: string; category: string; amount: number } // "YYYY-MM-DD"

export const CATEGORIES = ["Salary", "Freelance", "Housing", "Food", "Transport", "Utilities", "Health", "Fun", "Shopping", "Other"];

/** One fixed color per category, so the same slice is always the same color. */
export const CATEGORY_COLORS: Record<string, string> = {
  Salary: "#237556", Freelance: "#4a9d84", Housing: "#c25b4e", Food: "#d9a13b", Transport: "#4a7d9c",
  Utilities: "#6a4a94", Health: "#b0762f", Fun: "#d97b8f", Shopping: "#3b8a5e", Other: "#8a93a0",
};

const MONTH_NAMES = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

// Hand-rolled number and date formatting: these run inside chart bindings on
// every update, and Intl (toLocaleString / toLocaleDateString) builds a new
// formatter per call — far too slow there.
export const money = (n: number) => {
  const [whole, frac] = Math.abs(n).toFixed(2).split(".");
  return `${whole.replace(/\B(?=(\d{3})+(?!\d))/g, ",")}.${frac}`;
};
export const signed = (n: number) => (n > 0 ? `+${money(n)}` : n < 0 ? `−${money(-n)}` : money(0));

/** "2026-10-12" → "Oct 12", with the year when it is not the current one. */
export function fmtDate(iso: string) {
  const [y, m, d] = iso.split("-").map(Number);
  return y === new Date().getFullYear() ? `${MONTH_NAMES[m - 1]} ${d}` : `${MONTH_NAMES[m - 1]} ${d}, ${y}`;
}

const monthKey = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;

// The demo ledger: six months of a small household, generated relative to
// today so the charts always cover the recent past. Nothing is written here.
let nextId = 1;
const tx = (date: string, description: string, category: string, amount: number): Tx => ({ id: nextId++, date, description, category, amount });

export function seed(): Tx[] {
  const now = new Date();
  const at = (monthsAgo: number, dayOfMonth: number) => {
    const d = new Date(now.getFullYear(), now.getMonth() - monthsAgo, Math.min(dayOfMonth, 28));
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  };
  const txs: Tx[] = [];
  const add = (monthsAgo: number, dayOfMonth: number, description: string, category: string, amount: number) => {
    if (monthsAgo === 0 && dayOfMonth > now.getDate()) return; // no future rows in the current month
    txs.push(tx(at(monthsAgo, dayOfMonth), description, category, amount));
  };
  for (let m = 5; m >= 0; m--) {
    add(m, 1, "Salary", "Salary", 4200);
    add(m, 3, "Rent", "Housing", -1500);
    add(m, 6, "Electricity", "Utilities", -(104 + m * 3));
    add(m, 6, "Internet", "Utilities", -45);
    add(m, 9, "Groceries", "Food", -(290 + m * 9));
    add(m, 12, "Transit pass", "Transport", -60);
    add(m, 15, "Dinner out", "Food", -85);
    add(m, 18, "Cinema", "Fun", -50);
    add(m, 20, "Groceries", "Food", -170);
    add(m, 22, "Clothes", "Shopping", m % 3 === 0 ? -120 : -60);
    add(m, 24, "Gym", "Health", -40);
    if (m % 2 === 0) add(m, 26, "Freelance work", "Freelance", 350);
  }
  return txs;
}

/** Newest first; the same objects, so a list() over it moves rows, not mounts. */
export const byDate = (txs: Tx[]) => [...txs].sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : b.id - a.id));

export interface Month { key: string; label: string; income: number; expense: number; net: number; balance: number }

/** Income, spending and running balance for the last `count` months. */
export function monthly(txs: Tx[], count = 6): Month[] {
  const now = new Date();
  const months: Month[] = [];
  for (let m = count - 1; m >= 0; m--) {
    const d = new Date(now.getFullYear(), now.getMonth() - m, 1);
    months.push({ key: monthKey(d), label: MONTH_NAMES[d.getMonth()], income: 0, expense: 0, net: 0, balance: 0 });
  }
  const byKey = new Map(months.map((month) => [month.key, month]));
  let balance = 0;  for (const t of byDate(txs).reverse()) {
    const month = byKey.get(t.date.slice(0, 7));
    if (!month) { balance += t.amount; continue; } // older than the window: already earned
    if (t.amount >= 0) month.income += t.amount;
    else month.expense += -t.amount;
    month.net += t.amount;
  }
  for (const month of months) { balance += month.net; month.balance = balance; }
  return months;
}

export interface Slice { category: string; value: number; share: number }

/** Spending grouped by category, biggest first. */
export function byCategory(txs: Tx[]): Slice[] {
  const sums = new Map<string, number>();
  for (const t of txs) if (t.amount < 0) sums.set(t.category, (sums.get(t.category) ?? 0) + -t.amount);
  const total = [...sums.values()].reduce((a, b) => a + b, 0);
  return [...sums.entries()].map(([category, value]) => ({ category, value, share: total ? value / total : 0 })).sort((a, b) => b.value - a.value);
}

/** The whole ledger in three numbers. */
export function totals(txs: Tx[]) {
  let income = 0;
  let expense = 0;
  for (const t of txs) t.amount >= 0 ? (income += t.amount) : (expense += -t.amount);
  return { income, expense, balance: income - expense, count: txs.length };
}

/** The current month in three numbers. */
export function monthTotals(txs: Tx[]) {
  const key = monthKey(new Date());
  let income = 0;
  let expense = 0;
  for (const t of txs) if (t.date.slice(0, 7) === key) t.amount >= 0 ? (income += t.amount) : (expense += -t.amount);
  return { income, expense, net: income - expense };
}

// db.ts: a tiny IndexedDB wrapper for Finance. The ledger lives in one object
// store, keyed by id; every edit is a put() or delete(). Nothing here touches
// the DOM, and every call is a promise, so the views can await a load and
// move on after a save. All access is guarded so the docs server can import
// this module and render the page without a database.
import type { Tx } from "./money.ts";

const DB = "nuclo-desktop-finance";
const STORE = "transactions";

export const supported = () => typeof indexedDB !== "undefined";

function open(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE, { keyPath: "id" });
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error ?? new Error("Could not open the database"));
  });
}

function request(mode: IDBTransactionMode, run: (store: IDBObjectStore) => IDBRequest): Promise<any> {
  return open().then((db) => new Promise((resolve, reject) => {
    const tx = db.transaction(STORE, mode);
    const req = run(tx.objectStore(STORE));
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error ?? tx.error);
    tx.oncomplete = () => db.close();
  }));
}

export const loadTxs = (): Promise<Tx[]> => request("readonly", (store) => store.getAll());

export const saveTx = (t: Tx): Promise<void> => request("readwrite", (store) => store.put(t));

export const deleteTx = (id: number): Promise<void> => request("readwrite", (store) => store.delete(id));

/** Wipes the store and writes a fresh set, for the demo Reset. */
export function replaceAll(txs: Tx[]): Promise<void> {
  return open().then((db) => new Promise((resolve, reject) => {
    const tx = db.transaction(STORE, "readwrite");
    const store = tx.objectStore(STORE);
    store.clear();
    for (const t of txs) store.put(t);
    tx.oncomplete = () => { db.close(); resolve(); };
    tx.onerror = () => reject(tx.error);
  }));
}

// charts.ts: hand-rolled SVG charts for Finance — a line/area chart with a
// hover readout, grouped bars, and a donut. Each chart is one svgSvg() with
// viewBox coordinates and width 100%, so it scales with the window.
//
// The desktop's update() re-evaluates function bindings, it does not rebuild
// components — so every chart takes its data as a factory: the elements are
// built once, and each data-driven attribute, label and text re-derives from
// the factory on every update. That is how editing the ledger moves a chart
// without rebuilding it.
import "nuclo";

const TEXT = { "font-size": 9.5, "font-family": "ui-monospace, monospace" } as const;

// ---------------------------------------------------------------------------
// Line chart (with optional area fill, dots and labels). The hover marker is
// one shared state: moving over a chart updates its index and update() redraws.
// ---------------------------------------------------------------------------
export interface LinePoint { label: string; value: number }
export interface LineOpts { width?: number; height?: number; color?: string; area?: boolean; dots?: boolean; labels?: boolean; format?: (n: number) => string; scope?: string }

let hover: { id: string; index: number } | null = null;

export function LineChart(id: string, points: () => LinePoint[], opts: LineOpts = {}) {
  const W = opts.width ?? 360;
  const H = opts.height ?? 160;
  const pad = { l: 10, r: 10, t: 12, b: 18 };
  const color = opts.color ?? "var(--os-accent)";
  const fmt = opts.format ?? ((n: number) => String(Math.round(n)));
  const refresh = () => (opts.scope ? update(opts.scope) : update());
  const pts = () => points();
  const values = () => pts().map((p) => p.value);
  const min = () => Math.min(0, ...values());
  const max = () => Math.max(0, ...values());
  const span = () => max() - min() || 1;
  const x = (i: number) => pad.l + (pts().length === 1 ? (W - pad.l - pad.r) / 2 : (i * (W - pad.l - pad.r)) / (pts().length - 1));
  const y = (v: number) => pad.t + (H - pad.t - pad.b) * (1 - (v - min()) / span());
  const step = () => (W - pad.l - pad.r) / Math.max(1, pts().length - 1);
  const line = () => pts().map((p, i) => `${i ? "L" : "M"}${x(i).toFixed(1)},${y(p.value).toFixed(1)}`).join(" ");
  const area = () => `${line()} L${x(pts().length - 1).toFixed(1)},${H - pad.b} L${x(0).toFixed(1)},${H - pad.b} Z`;
  const show = () => (hover && hover.id === id ? hover.index : -1);
  const tip = () => { const i = show(); return i >= 0 ? `${pts()[i].label} · ${fmt(pts()[i].value)}` : ""; };
  const tipX = () => x(Math.max(0, show()));
  const tipY = () => y(pts()[Math.max(0, show())].value);
  return svgSvg(
    { viewBox: `0 0 ${W} ${H}`, width: "100%", height: H, role: "img", "aria-label": "Line chart", style: { display: "block" } },
    { onPointerMove: (e) => {
      const el = e.currentTarget;
      const rect = el.getBoundingClientRect();
      if (!rect.width || pts().length < 2) return;
      const xv = ((e.clientX - rect.left) / rect.width) * W;
      const index = Math.max(0, Math.min(pts().length - 1, Math.round((xv - pad.l) / step())));
      if (hover?.id === id && hover.index === index) return;
      hover = { id, index };
      refresh();
    }, onPointerLeave: () => { if (hover?.id === id) { hover = null; refresh(); } } },
    lineSvg({ x1: pad.l, x2: W - pad.r, y1: H - pad.b, y2: H - pad.b, style: { stroke: "var(--os-line)" } }),
    textSvg({ x: W - pad.r, y: pad.t - 3, "text-anchor": "end", fill: "var(--os-muted)", ...TEXT }, () => fmt(max())),
    textSvg({ x: W - pad.r, y: H - pad.b - 5, "text-anchor": "end", fill: "var(--os-muted)", ...TEXT }, () => fmt(min())),
    ...(opts.area ? [pathSvg({ d: () => area(), fill: color, opacity: 0.14, stroke: "none" })] : []),
    pathSvg({ d: () => line(), fill: "none", stroke: color, "stroke-width": 2, "stroke-linecap": "round", "stroke-linejoin": "round" }),
    ...(opts.dots === false ? [] : pts().map((_, i) => circleSvg({ cx: () => x(i), cy: () => y(pts()[i].value), r: 2.6, fill: "var(--os-panel)", stroke: color, "stroke-width": 1.6 }))),
    ...(opts.labels === false ? [] : pts().flatMap((_, i) => (i === 0 || i === pts().length - 1 || pts().length <= 6) ? [textSvg({ x: () => x(i), y: H - 5, "text-anchor": "middle", fill: "var(--os-muted)", ...TEXT }, () => pts()[i].label)] : [])),
    gSvg({},
      lineSvg({ x1: () => tipX(), x2: () => tipX(), y1: pad.t, y2: H - pad.b, stroke: color, "stroke-width": 1, "stroke-dasharray": "3 3", opacity: () => (show() < 0 ? 0 : 0.35) }),
      circleSvg({ cx: () => tipX(), cy: () => tipY(), r: 4, fill: color, stroke: "var(--os-panel)", "stroke-width": 2, opacity: () => (show() < 0 ? 0 : 1) }),
      rectSvg({ x: () => Math.min(W - tip().length * 5.6 - 18, Math.max(4, tipX() - tip().length * 2.8 - 9)), y: () => Math.max(2, tipY() - 26), width: () => tip().length * 5.6 + 18, height: 16, rx: 5, fill: "var(--os-panel)", stroke: "var(--os-line)", "stroke-width": 1, opacity: () => (show() < 0 ? 0 : 1) }),
      textSvg({ x: () => Math.min(W - tip().length * 2.8 - 9, Math.max(13, tipX())), y: () => (tipY() > 26 ? tipY() - 14 : tipY() + 20), "text-anchor": "middle", fill: "var(--os-text)", "font-size": 9, "font-family": "ui-monospace, monospace", opacity: () => (show() < 0 ? 0 : 1) }, () => tip()),
    ),
  );
}

// ---------------------------------------------------------------------------
// Grouped bars: one bar per series, side by side for every group.
// ---------------------------------------------------------------------------
export interface BarSeries { value: number; color: string }
export interface BarGroup { label: string; values: BarSeries[] }
export interface BarOpts { height?: number; format?: (n: number) => string }

export function BarChart(groups: () => BarGroup[], opts: BarOpts = {}) {
  const W = 360;
  const H = opts.height ?? 170;
  const pad = { l: 10, r: 10, t: 14, b: 18 };
  const fmt = opts.format ?? ((n: number) => String(Math.round(n)));
  const grp = () => groups();
  const max = () => Math.max(1, ...grp().flatMap((g) => g.values.map((v) => v.value)));
  const groupW = () => (W - pad.l - pad.r) / Math.max(1, grp().length);
  const bars = () => grp()[0]?.values.length ?? 1;
  const barW = () => Math.min(18, Math.max(3, (groupW() - 10) / bars()));
  const xOf = (gi: number, si: number) => pad.l + gi * groupW() + (groupW() - grp()[gi].values.length * barW()) / 2 + si * barW();
  const yOf = (v: number) => pad.t + (H - pad.t - pad.b) * (1 - v / max());
  return svgSvg(
    { viewBox: `0 0 ${W} ${H}`, width: "100%", height: H, role: "img", "aria-label": "Bar chart", style: { display: "block" } },
    lineSvg({ x1: pad.l, x2: W - pad.r, y1: H - pad.b, y2: H - pad.b, style: { stroke: "var(--os-line)" } }),
    textSvg({ x: W - pad.r, y: pad.t - 3, "text-anchor": "end", fill: "var(--os-muted)", ...TEXT }, () => fmt(max())),
    ...grp().flatMap((_, gi) => grp()[gi].values.map((v, si) => rectSvg({ x: () => xOf(gi, si), y: () => yOf(grp()[gi].values[si].value), width: () => barW(), height: () => Math.max(0.5, H - pad.b - yOf(grp()[gi].values[si].value)), rx: () => Math.min(3, barW() / 2), fill: v.color, style: { transition: "height .35s ease, y .35s ease" } }))),
    ...grp().map((_, gi) => textSvg({ x: () => pad.l + gi * groupW() + groupW() / 2, y: H - 5, "text-anchor": "middle", fill: "var(--os-muted)", ...TEXT }, () => grp()[gi].label)),
  );
}

// ---------------------------------------------------------------------------
// Donut: circle strokes with dasharray segments, one per slice, plus the
// total in the hole. The slices are a factory, but the ring keeps a fixed
// number of segment circles, so updates only re-size the arcs.
// ---------------------------------------------------------------------------
export interface DonutSlice { label: string; value: number; color: string }
export interface DonutOpts { size?: number; thickness?: number }

export function DonutChart(slices: () => DonutSlice[], center: { value: () => string; sub: string }, opts: DonutOpts = {}) {
  const size = opts.size ?? 150;
  const thickness = opts.thickness ?? 20;
  const r = (size - thickness) / 2 - 2;
  const c = size / 2;
  const segs = () => {
    const list = slices();
    const total = list.reduce((a, s) => a + s.value, 0) || 1;
    const C = 2 * Math.PI * r;
    let acc = 0;
    return list.map((s) => {
      const frac = s.value / total;
      const seg = { dash: Math.max(0, frac * C - 1.5), offset: acc }; // the 1.5 leaves a hairline gap
      acc += frac * C;
      return seg;
    });
  };
  const C = 2 * Math.PI * r;
  return svgSvg(
    { viewBox: `0 0 ${size} ${size}`, width: size, height: size, role: "img", "aria-label": "Donut chart", style: { display: "block" } },
    ...(slices().length ? slices().map((_, i) => circleSvg({ cx: c, cy: c, r, fill: "none", stroke: () => slices()[i].color, "stroke-width": thickness, "stroke-dasharray": () => `${segs()[i].dash} ${C - segs()[i].dash}`, "stroke-dashoffset": () => -segs()[i].offset, transform: `rotate(-90 ${c} ${c})`, style: { transition: "stroke-dasharray .4s ease, stroke-dashoffset .4s ease" } }))
      : [circleSvg({ cx: c, cy: c, r, fill: "none", stroke: "var(--os-line)", "stroke-width": thickness })]),
    textSvg({ x: c, y: c - 4, "text-anchor": "middle", fill: "var(--os-text)", "font-size": 15, "font-weight": 600 }, () => center.value()),
    textSvg({ x: c, y: c + 11, "text-anchor": "middle", fill: "var(--os-muted)", ...TEXT }, () => center.sub),
  );
}

// finance.ts: personal finance for the desktop — an editable ledger
// spreadsheet and a dashboard of charts over the same array. Every Tx is a
// plain object; the spreadsheet edits cells in place and the charts read the
// same array through function bindings, so editing a cell moves every chart.
// The ledger is one array shared by every Finance window: it is loaded from
// IndexedDB once and saved after every change.
//
// Like the rest of the desktop, views are built once and update() re-runs
// the dynamic bindings — so the charts take their data as factories, and the
// two tabs stay mounted with their visibility toggled by a binding. Updates
// are scoped: a change to the ledger refreshes every Finance window and
// nothing else, opening an editor or switching tabs refreshes only its own
// window, and the chart hover refreshes only the charts sub-scope, never the
// 63-row spreadsheet.
import "nuclo";
import type { Program } from "./programs.ts";
import { scopesOf, winScopeId } from "./windows.ts";
import { byCategory, byDate, CATEGORIES, CATEGORY_COLORS, fmtDate, money, monthly, monthTotals, seed, signed, totals, type Tx } from "./money.ts";
import { deleteTx, loadTxs, replaceAll, saveTx, supported } from "./db.ts";
import { BarChart, DonutChart, LineChart, type DonutSlice } from "./charts.ts";
import { s } from "./styles.ts";

/** What each window keeps for itself: the tab it shows and the cell it edits. */
interface FinState {
  tab: "charts" | "sheet";
  editing: { id: number; field: Field } | null;
  draft: string;
}
type Field = "date" | "description" | "category" | "amount";
type KeyEvent = KeyboardEvent & { currentTarget: HTMLElement };

/** The ledger every Finance window reads. */
const ledger = { txs: [] as Tx[], loaded: false, error: "" };
let loading = false;
let nextId = 1;
const today = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`; };

/** The ledger changed: every Finance window updates, and nothing else. */
const refresh = () => update(...scopesOf(finance));

// IndexedDB only exists in the browser, so the ledger loads when the first
// window mounts, not at init: the server renders the window with its loading state.
async function loadLedger() {
  if (loading) return;
  loading = true;
  if (!supported()) ledger.error = "IndexedDB is not available here.";
  else try {
    let rows = await loadTxs();
    if (!rows.length) { rows = seed(); await replaceAll(rows); }
    ledger.txs = rows;
    nextId = rows.reduce((m, t) => Math.max(m, t.id), 0) + 1;
  } catch (error) { ledger.error = (error as Error).message; }
  ledger.loaded = true;
  refresh();
}

function commit(state: FinState) {
  const e = state.editing;
  if (!e) return;
  const t = ledger.txs.find((tx) => tx.id === e.id);
  if (t) {
    const v = state.draft.trim();
    if (e.field === "date") t.date = v || t.date;
    else if (e.field === "description") t.description = v;
    else if (e.field === "category") t.category = v || t.category;
    else if (e.field === "amount") { const n = Number(v); if (Number.isFinite(n)) t.amount = n; }
    saveTx(t);
  }
  state.editing = null;
  refresh();
}

/** One cell of the spreadsheet: a button that shows the value, or the editor. */
function Cell(state: FinState, t: Tx, field: Field, scopeId: string) {
  const start = () => { state.editing = { id: t.id, field }; state.draft = String(t[field]); update(scopeId); };
  const display = () => {
    if (field === "amount") return signed(t.amount);
    if (field === "date") return fmtDate(t.date);
    if (field === "category") return t.category;
    return t.description || "—";
  };
  const keys = (e: KeyEvent) => {
    if (e.key === "Enter") commit(state);
    else if (e.key === "Escape") { state.editing = null; update(scopeId); }
  };
  return when(() => state.editing?.id === t.id && state.editing.field === field,
    field === "category" ? select(s.finInput,
      { "aria-label": "Category", value: () => state.draft, onMount: (el) => el.focus(), onChange: (e) => { state.draft = e.currentTarget.value; }, onBlur: () => commit(state), onKeyDown: keys },
      ...CATEGORIES.map((c) => option({ value: c }, c)))
    : input(s.finInput,
      { "aria-label": field, type: field === "date" ? "date" : field === "amount" ? "number" : "text", step: field === "amount" ? "0.01" : undefined, value: () => state.draft, onMount: (el) => { el.focus(); el.select(); }, onInput: (e) => { state.draft = e.currentTarget.value; }, onBlur: () => commit(state), onKeyDown: keys }),
  ).else(button(s.finCell, { title: "Click to edit", class: () => cx(s.finCell, field === "description" && !t.description ? s.finPlaceholder : null).className, onClick: start }, () => display()));
}

function RowView(state: FinState, t: Tx, scopeId: string) {
  return tr(s.finRow,
    td(s.finTd, Cell(state, t, "date", scopeId)),
    td(s.finTd, Cell(state, t, "description", scopeId)),
    td(s.finTd, Cell(state, t, "category", scopeId)),
    td(s.finTd, s.finAmount, { class: () => cx(s.finTd, s.finAmount, t.amount < 0 ? s.finExpense : s.finIncome).className }, Cell(state, t, "amount", scopeId)),
    td(s.finTd, s.finDelete, button(s.finIcon, { title: "Delete", "aria-label": "Delete", onClick: () => { ledger.txs.splice(ledger.txs.indexOf(t), 1); state.editing = null; deleteTx(t.id); refresh(); } }, "×")),
  );
}

function SheetView(state: FinState, scopeId: string) {
  const rows = () => byDate(ledger.txs);
  return div(s.finSheet,
    div(s.finScroller,
      table(s.finTable,
        thead(tr(
          th(s.finTh, "Date"), th(s.finTh, "Description"), th(s.finTh, "Category"),
          th(s.finTh, s.finAmount, "Amount"), th(s.finTh, s.finDelete),
        )),
        tbody(
          list(() => rows(), (t) => RowView(state, t, scopeId)),
