// Delete removes the selected node and Escape lets go of it, unless you are typing.
function shortcuts(el: HTMLElement) {
  const onKey = (e: KeyboardEvent) => {
    if (!el.offsetParent || !selected || (e.target as Element).closest?.("input, select, textarea")) return;
    if (e.key === "Delete" || e.key === "Backspace") remove(selected);
    else if (e.key === "Escape") { selected = null; update("ng-canvas"); }
    else return;
    e.preventDefault();
  };
  document.addEventListener("keydown", onKey, true);
  return () => document.removeEventListener("keydown", onKey, true);
}

export function NodeGraph() {
  return div(s.app, on("mount", shortcuts), Side(), div(s.main, Bar(), Canvas()));
}

// engine.ts: runs a function. Each node is a generator that asks for its
// inputs one at a time with yield, and one loop drives them all from its own
// stack array instead of the JavaScript call stack. A graph can be as deep as
// you like, and a function can call itself until memory or the step budget runs
// out: a call costs heap, never a stack frame. An If asks for its condition
// first and then for one branch only, so the other branch never runs, which is
// what lets a recursive function stop.
import { COMPARE, MATH, params, results, unwired, wireInto, type Fn, type GraphNode, type Value, type Wire } from "./graph.ts";

/** One function call: its arguments, and the outputs of every node it has worked out so far. */
interface Frame { fn: Fn; args: Value[] | null; done: Map<GraphNode, Value[]>; depth: number; run: Result; trace: Set<Wire> | null }
type Ask = { node: GraphNode; frame: Frame }; // "work out this node in this call"
type Body = Generator<Ask, Value[], Value[]>;

export interface Result {
  values: Map<GraphNode, Value[]>; // the outputs of the shown function's nodes
  errors: Map<GraphNode, string>;
  live: Set<GraphNode>; // the nodes an Output needed. The rest are worked out only to show their values.
  wires: Set<Wire>; // the wires an Output needed: not the ones into the branch an If skipped
  steps: number; // generator resumes, across every call
  calls: number;
  depth: number; // the deepest call
  ms: number;
}

export const BUDGET = 2_000_000; // steps: a recursion with no way out stops here

// The value on the wire into input i, or the default when nothing is wired there.
function* pull(node: GraphNode, i: number, frame: Frame): Generator<Ask, Value, Value[]> {
  const w = wireInto(frame.fn, node, i);
  if (w) frame.trace?.add(w);
  return w ? (yield { node: w.from, frame })[w.out] : unwired(node, i);
}

function* body(node: GraphNode, frame: Frame): Body {
  switch (node.kind) {
    case "number": case "text": case "switch": return [node.value];
    // Called, it reads its argument. Shown on its own, its test value.
    case "input": return [frame.args ? (frame.args[params(frame.fn).indexOf(node)] ?? 0) : node.value];
    case "output": return [yield* pull(node, 0, frame)];
    case "not": return [!(yield* pull(node, 0, frame))];
    case "if": return [(yield* pull(node, 0, frame)) ? yield* pull(node, 1, frame) : yield* pull(node, 2, frame)];
    case "compare": return [COMPARE[node.op](yield* pull(node, 0, frame), yield* pull(node, 1, frame))];
    case "math": {
      const a = yield* pull(node, 0, frame);
      const b = yield* pull(node, 1, frame);
      return [node.op === "+" && (typeof a === "string" || typeof b === "string") ? `${a}${b}` : MATH[node.op](Number(a), Number(b))];
    }
    case "logic": {
      const a = Boolean(yield* pull(node, 0, frame));
      if (node.op === "and" && !a) return [false]; // short-circuit: b is never asked for
      if (node.op === "or" && a) return [true];
      const b = Boolean(yield* pull(node, 1, frame));
      return [node.op === "xor" ? a !== b : b];
    }
    case "call": {
      const fn = node.fn!;
      const args: Value[] = [];
      for (let i = 0; i < params(fn).length; i++) args.push(yield* pull(node, i, frame));
      const inner: Frame = { fn, args, done: new Map(), depth: frame.depth + 1, run: frame.run, trace: null };
      frame.run.calls++;
      frame.run.depth = Math.max(frame.run.depth, inner.depth);
      const out: Value[] = [];
      for (const r of results(fn)) out.push((yield { node: r, frame: inner })[0]);
      return out;
    }
  }
}

// Works out one node. The stack holds the generators that are waiting for a value:
// the top one runs until it asks for a node, which is either known already in
// that call or pushed on top. When a generator returns, its value goes to the one below.
function drive(node: GraphNode, root: Frame) {
  const run = root.run;
  const stack: Ask[] = [{ node, frame: root }];
  const gens: Body[] = [body(node, root)];
  let value: Value[] = [];
  try {
    while (gens.length) {
      if (++run.steps > BUDGET) throw new Error(`Stopped after ${BUDGET.toLocaleString("en")} steps. Does every call reach a way out?`);
      const step = gens[gens.length - 1].next(value);
      if (step.done) {
        const { node, frame } = stack.pop()!;
        gens.pop();
        frame.done.set(node, (value = step.value));
      } else {
        const known = step.value.frame.done.get(step.value.node);
        if (known) value = known;
        else {
          stack.push(step.value);
          gens.push(body(step.value.node, step.value.frame));
        }
      }
    }
  } catch (e) {
    // Every node of the shown function that was waiting on this one fails with it.
    for (const ask of stack) if (ask.frame === root) run.errors.set(ask.node, (e as Error).message);
  }
}

/** Runs `fn` with its Input nodes' test values: its Outputs first, then every other node, for display. */
export function run(fn: Fn): Result {
  const start = performance.now();
  const result: Result = { values: new Map(), errors: new Map(), live: new Set(), wires: new Set(), steps: 0, calls: 0, depth: 0, ms: 0 };
  const root: Frame = { fn, args: null, done: result.values, depth: 0, run: result, trace: result.wires };
  const ask = (n: GraphNode) => { if (!result.values.has(n) && !result.errors.has(n)) drive(n, root); };
  results(fn).forEach(ask);
  result.live = new Set([...result.values.keys(), ...result.errors.keys()]);
  root.trace = null;
  fn.nodes.forEach(ask);
  result.ms = performance.now() - start;
  return result;
}

// graph.ts: the model. A function is a plain object that holds its nodes and
// wires. A node is a plain object with a position and its own fields, and a
// wire points straight at the two node objects it joins. "main" is a function
// like any other: its Input and Output nodes are the ports of every Call to it,
// and a Call can name any function, itself included. Nothing here knows about the UI.

export type Value = number | boolean | string;
export type Kind = "number" | "text" | "switch" | "math" | "compare" | "logic" | "not" | "if" | "input" | "output" | "call";

export interface GraphNode {
  id: number;
  kind: Kind;
  x: number; y: number; // px, on the canvas
  value: Value; // number, text, switch: the value. input: the test value used when its function runs on its own
  op: string; // math, compare, logic
  name: string; // input, output: the parameter or result name
  fn: Fn | null; // call: the function it calls
}
export interface Wire { from: GraphNode; out: number; to: GraphNode; in: number }
export interface View { x: number; y: number; zoom: number }
export interface Fn { name: string; nodes: GraphNode[]; wires: Wire[]; view: View | null } // view: null until it is first shown

export const MATH: Record<string, (a: number, b: number) => number> = {
  "+": (a, b) => a + b, "−": (a, b) => a - b, "×": (a, b) => a * b, "÷": (a, b) => a / b, "%": (a, b) => a % b, min: Math.min, max: Math.max,
};
export const COMPARE: Record<string, (a: Value, b: Value) => boolean> = {
  "<": (a, b) => a < b, "≤": (a, b) => a <= b, "=": (a, b) => a === b, "≠": (a, b) => a !== b, "≥": (a, b) => a >= b, ">": (a, b) => a > b,
};
export const LOGIC = ["and", "or", "xor"];

/** The parameters and results of a function: its Input and Output nodes, in order. */
export const params = (fn: Fn) => fn.nodes.filter((n) => n.kind === "input");
export const results = (fn: Fn) => fn.nodes.filter((n) => n.kind === "output");

/** The names of a node's input ports (left) and output ports (right). */
export function inputs(n: GraphNode): string[] {
  switch (n.kind) {
    case "math": case "compare": case "logic": return ["a", "b"];
    case "not": return ["in"];
    case "if": return ["if", "then", "else"];
    case "output": return [n.name];
    case "call": return params(n.fn!).map((p) => p.name);
    default: return [];
  }
}
export function outputs(n: GraphNode): string[] {
  switch (n.kind) {
    case "output": return [];
    case "input": return [n.name];
    case "call": return results(n.fn!).map((r) => r.name);
    default: return ["out"];
  }
}

/** An input with no wire into it reads false where a condition is expected, and 0 everywhere else. */
export const unwired = (n: GraphNode, i: number): Value => (n.kind === "logic" || n.kind === "not" || (n.kind === "if" && i === 0) ? false : 0);

export const wireInto = (fn: Fn, to: GraphNode, i: number) => fn.wires.find((w) => w.to === to && w.in === i);

let nextId = 1;
const DEFAULTS: Partial<Record<Kind, Partial<GraphNode>>> = {
  text: { value: "" }, switch: { value: false }, math: { op: "+" }, compare: { op: "<" }, logic: { op: "and" }, output: { name: "result" },
};

export function addNode(fn: Fn, kind: Kind, x: number, y: number, fields: Partial<GraphNode> = {}): GraphNode {
  const node: GraphNode = { id: nextId++, kind, x, y, value: 0, op: "", name: "", fn: null, ...DEFAULTS[kind], ...fields };
  if (kind === "input" && !fields.name) node.name = String.fromCharCode(97 + (params(fn).length % 26)); // a, b, c…
  fn.nodes.push(node);
  return node;
}

/** True when a path of wires already leads from `a` to `b`. */
function reaches(fn: Fn, a: GraphNode, b: GraphNode) {
  const seen = new Set<GraphNode>();
  const todo = [a];
  for (let n = todo.pop(); n; n = todo.pop()) {
    if (n === b) return true;
    if (seen.has(n)) continue;
    seen.add(n);
    for (const w of fn.wires) if (w.from === n) todo.push(w.to);
  }
  return false;
}

/**
 * Wires an output to an input, replacing any wire already in that input.
 * Refuses a loop: a node that feeds itself has no first value. A Call
 * is how a function uses its own result.
 */
export function connect(fn: Fn, from: GraphNode, out: number, to: GraphNode, i: number): boolean {
  if (reaches(fn, to, from)) return false;
  const old = wireInto(fn, to, i);
  if (old) disconnect(fn, old);
  fn.wires.push({ from, out, to, in: i });
  return true;
}

export function disconnect(fn: Fn, wire: Wire) {
  fn.wires.splice(fn.wires.indexOf(wire), 1);
}

/**
 * Removes a node and its wires. An Input or Output node is also a port of
 * every Call to its function, in every function: the wire on that port goes,
 * and the wires on the ports after it move up one.
 */
export function removeNode(fn: Fn, node: GraphNode) {
  const port = node.kind === "input" ? params(fn).indexOf(node) : node.kind === "output" ? results(fn).indexOf(node) : -1;
  fn.wires = fn.wires.filter((w) => w.from !== node && w.to !== node);
  fn.nodes.splice(fn.nodes.indexOf(node), 1);
  if (port === -1) return;
  for (const other of functions) {
    other.wires = other.wires.filter((w) => {
      const [call, key] = node.kind === "input" ? [w.to, "in" as const] : [w.from, "out" as const];
      if (call.fn !== fn) return true; // only a Call has a fn
      if (w[key] === port) return false;
      if (w[key] > port) w[key]--;
      return true;
    });
  }
}

/** The Call nodes, outside `fn` itself, that would break if it went away. */
export const callers = (fn: Fn) => functions.filter((f) => f !== fn).flatMap((f) => f.nodes.filter((n) => n.fn === fn));

export function addFunction(): Fn {
  const fn: Fn = { name: `function${functions.length}`, nodes: [], wires: [], view: null };
  const x = addNode(fn, "input", 40, 60, { name: "x" });
  connect(fn, x, 0, addNode(fn, "output", 300, 60), 0);
  functions.push(fn);
  return fn;
}

export function removeFunction(fn: Fn) {
  functions.splice(functions.indexOf(fn), 1);
}

// ── The starting graphs ──────────────────────────────────────────────────

const define = (name: string): Fn => ({ name, nodes: [], wires: [], view: null });
const main = define("main");
const factorial = define("factorial");
const sum = define("sum");
export const functions: Fn[] = [main, factorial, sum];

// Wires `ins` into the inputs of `to`, in order: [node, output] pairs.
function feed(fn: Fn, to: GraphNode, ...ins: [GraphNode, number][]) {
  ins.forEach(([from, out], i) => connect(fn, from, out, to, i));
  return to;
}

// n! = n ≤ 1 ? 1 : n × (n − 1)!   and   sum(n) = n ≤ 0 ? 0 : n + sum(n − 1)
// Same shape: the If asks for its condition, then for one branch only, so the
// branch that calls the function again is skipped once n reaches the bottom.
function recursive(fn: Fn, test: number, base: number, op: string, result: string) {
  const n = addNode(fn, "input", 30, 40, { name: "n", value: test });
  const one = addNode(fn, "number", 30, 180, { value: 1 });
  const stop = base === 1 ? one : addNode(fn, "number", 240, 290, { value: base });
  const done = feed(fn, addNode(fn, "compare", 240, 30, { op: "≤" }), [n, 0], [stop, 0]);
  const less = feed(fn, addNode(fn, "math", 240, 150, { op: "−" }), [n, 0], [one, 0]);
  const again = feed(fn, addNode(fn, "call", 450, 170, { fn }), [less, 0]);
  const step = feed(fn, addNode(fn, "math", 660, 110, { op }), [n, 0], [again, 0]);
  const pick = feed(fn, addNode(fn, "if", 870, 40), [done, 0], [stop, 0], [step, 0]);
  feed(fn, addNode(fn, "output", 1080, 60, { name: result }), [pick, 0]);
}
recursive(factorial, 5, 1, "×", "n!");
recursive(sum, 100, 0, "+", "total");

{
  // A grade: pass when the score is at least 50 and the work was handed in.
  const score = addNode(main, "number", 30, 30, { value: 72 });
  const bar = addNode(main, "number", 30, 110, { value: 50 });
  const enough = feed(main, addNode(main, "compare", 240, 30, { op: "≥" }), [score, 0], [bar, 0]);
  const handedIn = addNode(main, "switch", 240, 140, { value: true });
  const both = feed(main, addNode(main, "logic", 450, 60, { op: "and" }), [enough, 0], [handedIn, 0]);
  const pass = addNode(main, "text", 450, 170, { value: "pass" });
  const fail = addNode(main, "text", 450, 240, { value: "fail" });
  const pick = feed(main, addNode(main, "if", 660, 90), [both, 0], [pass, 0], [fail, 0]);
  feed(main, addNode(main, "output", 870, 110, { name: "grade" }), [pick, 0]);

  // Recursion: 6! asks factorial for 5!, which asks for 4!, down to 1!.
  const six = addNode(main, "number", 30, 340, { value: 6 });
  const fact = feed(main, addNode(main, "call", 240, 340, { fn: factorial }), [six, 0]);
  feed(main, addNode(main, "output", 450, 330, { name: "6!" }), [fact, 0]);

  // Depth: sum(1000) is a thousand calls inside each other.
  const deep = addNode(main, "number", 30, 460, { value: 1000 });
  const total = feed(main, addNode(main, "call", 240, 460, { fn: sum }), [deep, 0]);
  feed(main, addNode(main, "output", 450, 450, { name: "1 + … + n" }), [total, 0]);
}

// app.ts: the grid. Everything on screen is derived from the 10,000 rows by
// plain functions in data.ts (filter, sort, page), called again on every
// update(). The <tbody> is a list() over the current page, and rows are
// matched by identity: sorting moves the <tr>s that stay on the page, and an
// edited row is the same object in the table, the selection and the totals.
// The "rows built" count proves it: it only grows when a row new to the page appears.
import "nuclo";
import { columns, count, cycleSort, edit, matches, money, page, pages, query, remove, STATUSES, view, type Column, type Row, type Status } from "./data.ts";
import { s } from "./styles.ts";

type Field = HTMLInputElement | HTMLSelectElement;

const CHECK = 40; // px: the checkbox column
const ARROW = { none: "↕", ascending: "↑", descending: "↓" };

const selected = new Set<Row>();
let editing: { row: Row; column: Column } | null = null;
let built = 0;
let counting = false;

// Each <tr> counts itself once, when it is built; one update() after the batch shows the total.
function counted() {
  built++;
  if (counting) return;
  counting = true;
  queueMicrotask(() => { counting = false; update(); });
}

const pick = (row: Row, yes: boolean) => (yes ? selected.add(row) : selected.delete(row));

// Puts the cell's text back in place of the editor. If the editor had the
// focus, the cell takes it, so the keyboard carries on from there.
function close(field: Field) {
  const cell = document.activeElement === field ? field.parentElement : null;
  editing = null;
  update();
  cell?.focus();
}

// Writes the field to its row, unless the browser finds it invalid (an empty
// name, an amount that is not a number): then the editor stays open, in red.
function save(field: Field) {
  if (!editing || !field.checkValidity()) return;
  const { row, column } = editing;
  if (column.key === "amount") edit(row, "amount", Number(field.value));
  else if (column.key === "status") edit(row, "status", field.value as Status);
  else edit(row, "name", field.value);
  close(field);
}

// Enter or leaving the field saves, Escape cancels.
const fieldEvents = {
  onBlur: (e: FocusEvent & { currentTarget: Field }) => save(e.currentTarget),
  onKeyDown: (e: KeyboardEvent & { currentTarget: Field }) => {
    if (e.key === "Enter") save(e.currentTarget);
    if (e.key === "Escape") {
      e.preventDefault(); // the docs modal closes on Escape: this one is ours
      close(e.currentTarget);
    }
  },
};

function Editor(row: Row, column: Column) {
  if (column.key === "status") {
    return select(s.editor, fieldEvents, { value: () => row.status, "aria-label": "Status", onChange: (e) => save(e.currentTarget) },
      on("mount", (el) => el.focus()),
      ...STATUSES.map((status) => option({ value: status }, status)));
  }
  const amount = column.key === "amount";
  return input(s.editor, fieldEvents, {
    value: () => String(row[column.key]), required: true, inputMode: amount ? "decimal" : "text", "aria-label": column.label,
    pattern: amount ? "\\d+(\\.\\d{1,2})?" : undefined, // a plain number, up to two decimals
  }, on("mount", (el) => { el.focus(); el.select(); }));
}

const text = (row: Row, column: Column) => column.format?.(row) ?? String(row[column.key]);

// A plain cell is static text: its field never changes. An editable one reads
// its row on every update(), and swaps in an editor on double-click or Enter.
function Cell(row: Row, column: Column) {
  const style = cx(s.td, column.align === "right" && s.right);
  if (!column.editable) return td(style, text(row, column));
  const startEdit = () => { editing = { row, column }; update(); };
  return td(
    style, s.editable,
    { tabIndex: 0, onDblClick: startEdit, onKeyDown: (e) => { if (e.key === "Enter" && e.target === e.currentTarget) startEdit(); } },
    when(() => editing?.row === row && editing.column === column, Editor(row, column)).else(
      column.key === "status" ? span({ class: () => cx(s.pill, s[row.status]).className }, () => row.status) : span(() => text(row, column)),
    ),
  );
}

function RowView(row: Row) {
  return tr(
    { class: () => cx(s.tr, selected.has(row) && s.picked).className },
    on("mount", counted),
    td(s.td, s.check, input({ type: "checkbox", "aria-label": `Select row ${row.id}`, checked: () => selected.has(row), onChange: (e) => { pick(row, e.currentTarget.checked); update(); } })),
    ...columns.map((column) => Cell(row, column)),
  );
}

// Checked when the whole page is selected, a dash when part of it is.
function PageCheckbox() {
  const state = () => {
    const onPage = query();
    const n = onPage.filter((row) => selected.has(row)).length;
    return n === 0 ? "none" : n === onPage.length ? "all" : "some";
  };
  return input({
    type: "checkbox", "aria-label": "Select every row on this page", checked: () => state() === "all", indeterminate: () => state() === "some",
    onChange: (e) => { for (const row of query()) pick(row, e.currentTarget.checked); update(); },
  });
}

function HeaderCell(column: Column) {
  const sort = () => (view.sort !== column.key ? "none" : view.desc ? "descending" : "ascending");
  let from = { x: 0, width: 0 }; // where the resize drag started
  return th(
    s.th,
    { "aria-sort": sort },
    button(cx(s.sort, column.align === "right" && s.right), { onClick: () => { cycleSort(column.key); update(); } }, column.label, span(s.arrow, () => ARROW[sort()])),
    // Drag the edge to resize. The pointer is captured, so the drag goes on outside the header.
    span(s.resize, {
      title: `Resize ${column.label}`,
      onPointerDown: (e) => { e.currentTarget.setPointerCapture(e.pointerId); from = { x: e.clientX, width: column.width }; },
      onPointerMove: (e) => {
        if (!e.currentTarget.hasPointerCapture(e.pointerId)) return;
        column.width = Math.max(56, from.width + e.clientX - from.x);
        update();
      },
    }),
  );
}

function Toolbar() {
  return div(
    s.toolbar,
    input(s.search, {
      type: "search", placeholder: "Search name, email, company, country", "aria-label": "Search", value: view.search,
      onInput: (e) => { view.search = e.currentTarget.value; view.page = 0; update(); },
    }),
    select(s.select, { value: view.status, "aria-label": "Status", onChange: (e) => { view.status = e.currentTarget.value as Status | ""; view.page = 0; update(); } },
      option({ value: "" }, "All statuses"),
      ...STATUSES.map((status) => option({ value: status }, status))),
    when(() => selected.size > 0, div(
      s.bulk,
      span(() => `${count.format(selected.size)} selected`),
      button(s.btn, s.danger, "Delete", { onClick: () => { remove(selected); selected.clear(); update(); } }),
      button(s.btn, "Clear selection", { onClick: () => { selected.clear(); update(); } }),
    )),
  );
}

function Table() {
  return div(
    s.scroller,
    table(
      s.table,
      { style: () => ({ width: `max(100%, ${columns.reduce((sum, column) => sum + column.width, CHECK)}px)` }) },
      colgroup(col({ style: { width: `${CHECK}px` } }), ...columns.map((column) => col({ style: () => ({ width: `${column.width}px` }) }))),
      thead(tr(th(s.th, s.check, PageCheckbox()), ...columns.map(HeaderCell))),
      tbody(
        list(query, RowView),
        when(() => matches().length === 0, tr(td(s.empty, { colSpan: columns.length + 1 }, "No rows match."))),
      ),
    ),
  );
}

function PageButton(icon: string, title: string, target: () => number) {
  const to = () => Math.max(0, Math.min(target(), pages() - 1));
  return button(s.btn, s.icon, { title, "aria-label": title, disabled: () => to() === page(), onClick: () => { view.page = to(); update(); } }, icon);
}

function Footer() {
  return footer(
    s.footer,
    span(() => {
      const total = matches().length;
      const first = page() * view.size;
      return total === 0 ? "No rows" : `Showing ${count.format(first + 1)}–${count.format(Math.min(first + view.size, total))} of ${count.format(total)}`;
    }),
    span(s.totals, () => {
      const sum = matches().reduce((total, row) => total + row.amount, 0);
      return `Total ${money.format(sum)} · avg ${money.format(sum / (matches().length || 1))}`;
    }),
    label(s.size, "Rows", select(s.select, { value: String(view.size), onChange: (e) => { view.size = Number(e.currentTarget.value); view.page = 0; update(); } },
      ...[25, 50, 100].map((n) => option({ value: String(n) }, String(n))))),
    div(
      s.pager,
      PageButton("«", "First page", () => 0),
      PageButton("‹", "Previous page", () => page() - 1),
      PageButton("›", "Next page", () => page() + 1),
      PageButton("»", "Last page", () => pages() - 1),
    ),
  );
}

export function DataGrid() {
  return div(
    s.app,
    p(s.hint, strong(() => `${count.format(built)} rows built`), ". Sorting moves the rows that stay on the page and builds only the new ones: search \"elif.novak\", then sort. Double-click a name, status or amount to edit it."),
    Toolbar(),
    Table(),
    Footer(),
  );
}

// data.ts: the model. 10,000 rows of plain objects, each generated from its
// index, so the server and the browser build the same table. What the grid
// shows is plain functions over that array: filter, sort, then the page slice.
// An edit writes to the row object itself. Nothing here knows about the UI.

export type Status = "active" | "invited" | "suspended";
export const STATUSES: Status[] = ["active", "invited", "suspended"];

export interface Row {
  id: number;
  name: string;
  email: string;
  company: string;
  country: string;
  status: Status;
  amount: number;
  joined: string; // an ISO date, so it sorts as text
}

export interface Column {
  key: keyof Row;
  label: string;
  width: number; // px: resizing a column writes it here
  align?: "right";
  format?: (row: Row) => string;
  editable?: boolean;
}

// One fixed locale, so the server and the browser print the same text.
export const count = new Intl.NumberFormat("en-US");
export const money = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });
const day = new Intl.DateTimeFormat("en-US", { dateStyle: "medium", timeZone: "UTC" });

export const columns: Column[] = [
  { key: "id", label: "ID", width: 64, align: "right" },
  { key: "name", label: "Name", width: 160, editable: true },
  { key: "email", label: "Email", width: 210 },
  { key: "company", label: "Company", width: 120 },
  { key: "country", label: "Country", width: 110 },
  { key: "status", label: "Status", width: 110, editable: true },
  { key: "amount", label: "Amount", width: 120, align: "right", format: (row) => money.format(row.amount), editable: true },
  { key: "joined", label: "Joined", width: 120, format: (row) => day.format(new Date(row.joined)) },
];

const FIRST = ["Ana", "Bruno", "Chen", "Dana", "Elif", "Farah", "Gabriel", "Hana", "Igor", "Julia", "Kofi", "Lena", "Marta", "Nikhil", "Olga", "Pedro"];
const LAST = ["Silva", "Okafor", "Tanaka", "Novak", "Haddad", "Larsen", "Moreau", "Kowalski", "Costa", "Nguyen", "Fischer", "Rossi"];
const COMPANIES = ["Acme", "Globex", "Initech", "Hooli", "Northwind", "Contoso", "Vandelay", "Umbrella"];
const COUNTRIES = ["Brazil", "Canada", "France", "Germany", "India", "Japan", "Kenya", "Mexico", "Portugal", "Sweden"];

// A small integer hash: every field of a row is a deterministic function of its index.
function hash(n: number) {
  n = Math.imul(n ^ (n >>> 16), 0x45d9f3b);
  n = Math.imul(n ^ (n >>> 16), 0x45d9f3b);
  return (n ^ (n >>> 16)) >>> 0;
}
const pick = <T>(list: readonly T[], i: number, salt: number) => list[hash(i * 8 + salt) % list.length];

const rows: Row[] = Array.from({ length: 10_000 }, (_, i) => {
  const [first, last, company] = [pick(FIRST, i, 1), pick(LAST, i, 2), pick(COMPANIES, i, 3)];
  return {
    id: i + 1, name: `${first} ${last}`, email: `${first}.${last}@${company}.com`.toLowerCase(), company,
    country: pick(COUNTRIES, i, 4), status: pick(STATUSES, i, 5), amount: (hash(i * 8 + 6) % 1_000_000) / 100,
    joined: new Date(Date.UTC(2018, 0, 1 + (hash(i * 8 + 7) % 2900))).toISOString().slice(0, 10),
  };
});

// What the grid asks for; query() turns it into the rows on screen. A status of "" is every status.
export const view = { search: "", status: "" as Status | "", sort: null as keyof Row | null, desc: false, page: 0, size: 50 };

const SEARCHED = ["name", "email", "company", "country"] as const;

// A one-entry memo. Filtering and sorting 10,000 rows takes a few milliseconds:
// fine once per keystroke, wasteful on every update() (a column resize runs one
// per pointer move, and several parts of the grid read the result each time).
let memo: { key: string; rows: Row[] } | null = null;

/** Every row that passes the search and the status filter, in sort order. */
export function matches() {
  const key = JSON.stringify([view.search, view.status, view.sort, view.desc]);
  if (memo?.key === key) return memo.rows;
  const q = view.search.trim().toLowerCase();
  const found = rows.filter((row) => (!view.status || row.status === view.status) && (!q || SEARCHED.some((field) => row[field].toLowerCase().includes(q))));
  const by = view.sort;
  if (by) {
    const dir = view.desc ? -1 : 1;
    // sort() is stable: rows with equal values stay in id order.
    found.sort((a, b) => (a[by] < b[by] ? -dir : a[by] > b[by] ? dir : 0));
  }
  memo = { key, rows: found };
  return found;
}

export const pages = () => Math.max(1, Math.ceil(matches().length / view.size));
/** The page on screen, kept in range when the rows behind it shrink. */
export const page = () => Math.min(view.page, pages() - 1);
/** The rows of the current page. */
export const query = () => matches().slice(page() * view.size, (page() + 1) * view.size);

/** A header click: ascending, then descending, then back to id order. */
export function cycleSort(key: keyof Row) {
  if (view.sort !== key) [view.sort, view.desc] = [key, false];
  else if (!view.desc) view.desc = true;
  else view.sort = null;
}

/** Writes one field. The row stays the same object, wherever it is used. */
export function edit<K extends keyof Row>(row: Row, key: K, value: Row[K]) {
  row[key] = value;
  memo = null; // it may filter or sort differently now
}

/** Deletes rows in place: every other row keeps its object. */
export function remove(gone: Set<Row>) {
  let kept = 0;
  for (const row of rows) if (!gone.has(row)) rows[kept++] = row;
  rows.length = kept;
  memo = null;
}

// app.ts: the chat. Async is plain async/await: change the state, update(),
// await, change it again, update(). History loads upward forever: a sentinel
// above the oldest message asks for the page before it, the page goes in with
// unshift(), and scrollTop grows by the height it added, so nothing on screen
// moves. Your message shows before the server has it; when send() settles,
// the same object becomes sent, or failed with a Retry, and its row stays.
// Everything a channel is lives in one plain object, so switching channels
// swaps which object the same log, head and composer read — and the sidebar
// refreshes its badges with update("chat-sidebar") while the rest sleeps.
import "nuclo";
import { CHANNELS, connect, fetchHistory, ME, send, type ChannelEvent, type ChannelInfo, type Message } from "./server.ts";
import { s } from "./styles.ts";

const GROUP = 5 * 60_000; // ms: one author's messages this close together share a header
const NEAR = 60; // px from the bottom that still counts as "at the bottom"
const EMOJIS = ["👍", "👏", "🚀", "❤️", "😂", "🎉", "💡", "🔥"];

interface Reaction {
  emoji: string;
  count: number;
  mine: boolean;
}

// A message on screen: the server's fields, how far it got, and how it joins the one above.
interface Msg extends Message {
  status: "sent" | "sending" | "failed";
  first: boolean; // starts a group: shows the avatar and the name
  day: string; // the day line above it, or ""
  fresh: boolean; // arrived live: the pop animation plays once
  edited: boolean;
  editing: boolean; // the inline editor is open
  copied: boolean;
  reactions: Reaction[];
}

interface Channel {
  info: ChannelInfo;
  messages: Msg[];
  before: number | undefined; // the id of the oldest message loaded: the next page ends there
  loading: boolean;
  error: string | null;
  atStart: boolean; // the channel has nothing older
  online: number;
  typing: Set<string>;
  unseen: number; // messages that arrived while the reader was scrolled up
  firstUnseen: Msg | null; // where the "New messages" divider sits
  unread: number; // messages that arrived while another channel was open
  draft: string;
  atBottom: boolean; // where the reader was when they left
  scrollTop: number;
}

const channels: Channel[] = CHANNELS.map((info) => ({
  info,
  messages: [],
  before: undefined,
  loading: false,
  error: null,
  atStart: false,
  online: 0,
  typing: new Set(),
  unseen: 0,
  firstUnseen: null,
  unread: 0,
  draft: "",
  atBottom: true,
  scrollTop: 0,
}));
let active = channels[0];

let scroller: HTMLElement | null = null;
let composerEl: HTMLTextAreaElement | null = null;
let composerFocused = false;
let menu = false; // the phone drawer
let picker: Msg | null = null; // the message whose reaction picker is open
let composerPicker = false;
let lookAgain: (() => void) | null = null; // set by the mounted sentinel: checks again whether it is in view

const toMsg = (m: Message, fresh = false): Msg => {
  const msg: Msg = { ...m, status: "sent", first: true, day: "", fresh, edited: false, editing: false, copied: false, reactions: [] };
  if (fresh) setTimeout(() => { msg.fresh = false; }, 1200);
  return msg;
};

const clock = (t: number) => new Date(t).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
const fullTime = (t: number) => new Date(t).toLocaleString([], { dateStyle: "long", timeStyle: "medium" });
const dayOf = (t: number) => {
  const d = new Date(t);
  const today = new Date();
  const yesterday = new Date(today);
  yesterday.setDate(today.getDate() - 1);
  if (d.toDateString() === today.toDateString()) return "Today";
  if (d.toDateString() === yesterday.toDateString()) return "Yesterday";
  return d.toLocaleDateString([], { weekday: "long", month: "long", day: "numeric" });
};
const hue = (name: string) => [...name].reduce((h, c) => (h * 31 + c.charCodeAt(0)) % 360, 0);

// What messages[i] shows depends on the message above it: a day line when the
// day changes, the author's header when a new group starts.
function link(ch: Channel, i: number) {
  const m = ch.messages[i];
  const prev = ch.messages[i - 1];
  const day = dayOf(m.at);
  m.day = prev && dayOf(prev.at) === day ? "" : day;
  m.first = m.day !== "" || prev.author !== m.author || m.at - prev.at > GROUP;
}

function push(ch: Channel, m: Msg) {
  ch.messages.push(m);
  link(ch, ch.messages.length - 1);
}

const nearBottom = () => !scroller || scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < NEAR;
const toBottom = (behavior: ScrollBehavior = "auto") => scroller?.scrollTo({ top: scroller.scrollHeight, behavior });

async function loadOlder() {
  const ch = active;
  if (ch.loading || ch.error !== null || ch.atStart) return;
  ch.loading = true;
  update();
  try {
    const page = await fetchHistory(ch.info.id, ch.before);
    if (page.length === 0) ch.atStart = true;
    else {
      ch.before = page[0].id;
      ch.messages.unshift(...page.map((m) => toMsg(m)));
      for (let i = 0; i <= page.length && i < ch.messages.length; i++) link(ch, i); // the old top message may join the page's last group
    }
  } catch (e) {
    ch.error = (e as Error).message;
  }
  ch.loading = false;
  // The page lands above what the reader is looking at: measure, update(), and
  // scroll down by the height it added. On the first page, that is the bottom.
  // A channel left mid-flight keeps its page, but the visible log is untouched.
  const height = ch === active ? scroller?.scrollHeight ?? 0 : 0;
  update();
  if (ch === active && scroller) {
    scroller.scrollTop += scroller.scrollHeight - height;
    lookAgain?.(); // a short page can leave the sentinel in view: then load the next one too
  }
}

// The row of a message, for the scroll arithmetic that keeps the view stable.
const rowOf = (m: Msg) => scroller?.querySelector(`[data-msg="${m.id}"]`) as HTMLElement | null | undefined;

// A row grew or shrank (picker, editor, a reaction): keep the view stable the
// same way loadOlder() does — except a reader stuck to the bottom follows it.
function relayoutUnder(el: HTMLElement | null | undefined) {
  if (!el || !scroller) { update("chat-pane"); return; }
  const stick = nearBottom();
  const top = el.getBoundingClientRect().top - scroller.getBoundingClientRect().top + scroller.scrollTop;
  const height = scroller.scrollHeight;
  update("chat-pane");
  if (stick) toBottom();
  else if (top + el.offsetHeight <= scroller.scrollTop) scroller.scrollTop += scroller.scrollHeight - height;
}

function receive(e: ChannelEvent) {
  const ch = channels.find((c) => c.info.id === e.channel);
  if (!ch) return;
  if (e.type === "online") {
    ch.online = e.count;
    if (ch === active) update();
    else update("chat-sidebar");
    return;
  }
  if (e.type === "typing") {
    ch.typing.add(e.author);
    if (ch === active) {
      const stick = nearBottom();
      update("chat-pane");
      if (stick) toBottom(); // the typing row appears at the bottom: stay on it
    }
    return;
  }
  if (e.type === "reaction") {
    const m = ch.messages.find((x) => x.id === e.messageId);
    if (!m) return;
    react(m, e.emoji, false);
    if (ch === active) relayoutUnder(rowOf(m));
    return;
  }
  ch.typing.delete(e.message.author);
  const m = toMsg(e.message, true);
  push(ch, m);
  if (ch === active) {
    const stick = nearBottom(); // read before anything changes
    if (!stick) {
      ch.unseen++;
      ch.firstUnseen ??= m;
    }
    update();
    if (stick) toBottom(); // a reader at the bottom follows the conversation; the others get the pill
  } else {
    ch.unread++;
    ch.firstUnseen ??= m;
    update("chat-sidebar"); // only the badge needs to know
  }
}

// Optimistic: the message is on screen before the server has it. send() only
// changes fields on the same object, so its row is never rebuilt.
async function deliver(m: Msg) {
  const ch = active;
  m.status = "sending";
  update();
  try {
    Object.assign(m, await send(ch.info.id, m.text));
    m.status = "sent";
  } catch {
    m.status = "failed";
  }
  update();
}

function submit() {
  const ch = active;
  const text = ch.draft.trim();
  if (!text) return;
  ch.draft = "";
  ch.unseen = 0;
  ch.firstUnseen = null;
  const m = toMsg({ id: -1, author: ME, text, at: Date.now() }, true);
  push(ch, m);
  deliver(m);
  toBottom(); // your own message always takes you down
}

function remove(m: Msg) {
  const ch = active;
  const i = ch.messages.indexOf(m);
  ch.messages.splice(i, 1);
  if (i < ch.messages.length) link(ch, i); // the next message may now start a group
  update();
}

const typingText = () => {
  const names = [...active.typing];
  return names.length === 0 ? "" : `${names.join(" and ")} ${names.length === 1 ? "is" : "are"} typing…`;
};

function markRead() {
  active.unseen = 0;
  active.firstUnseen = null;
  update("chat-pane");
}

// ── Reactions: a plain array on each message, rebuilt on every change ──

function react(m: Msg, emoji: string, mine: boolean) {
  const r = m.reactions.find((x) => x.emoji === emoji);
  if (!r) m.reactions = [...m.reactions, { emoji, count: 1, mine }];
  else if (r.mine) {
    if (mine) return;
    m.reactions = r.count === 1 ? m.reactions.filter((x) => x !== r) : m.reactions.map((x) => (x === r ? { emoji, count: x.count - 1, mine: false } : x));
  } else if (mine) m.reactions = m.reactions.map((x) => (x === r ? { emoji, count: x.count + 1, mine: true } : x));
  else m.reactions = m.reactions.map((x) => (x === r ? { emoji, count: x.count + 1, mine: false } : x));
}

function toggleReaction(m: Msg, emoji: string) {
  react(m, emoji, true);
  picker = null;
  relayoutUnder(rowOf(m));
}

// ── The composer: a scope, so a keystroke only refreshes the composer ──

function insertEmoji(emoji: string) {
  active.draft += emoji;
  composerPicker = false;
  update("chat-composer");
  composerEl?.focus();
}

const lastOwn = () => [...active.messages].reverse().find((m) => m.author === ME && m.status === "sent");

// ── Editing: swap the text for a textarea on the same row, patch on save ──

function startEdit(m: Msg) {
  m.editing = true;
  relayoutUnder(rowOf(m));
}

function cancelEdit(m: Msg) {
  m.editing = false;
  relayoutUnder(rowOf(m));
  composerEl?.focus();
}

function saveEdit(m: Msg, value: string) {
  const text = value.trim();
  if (text && text !== m.text) {
    m.text = text;
    m.edited = true;
  }
  m.editing = false;
  relayoutUnder(rowOf(m));
  composerEl?.focus();
}

async function copy(m: Msg) {
  try {
    await navigator.clipboard.writeText(m.text);
  } catch {
    // The Clipboard API can be missing in sandboxed frames: fall back to a selection.
    const ta = document.createElement("textarea");
    ta.value = m.text;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    document.execCommand("copy");
    ta.remove();
  }
  m.copied = true;
  update("chat-pane");
  setTimeout(() => { m.copied = false; update("chat-pane"); }, 1200);
}

// ── Markdown-lite: bold, italic, inline code, links and @mentions. The text
// is parsed once per message, and the segments are a nested list(), so an edit
// replaces them without touching the row.

type Seg =
  | { k: "text"; text: string }
  | { k: "bold"; text: string }
  | { k: "ital"; text: string }
  | { k: "code"; text: string }
  | { k: "link"; text: string; href: string }
  | { k: "mention"; text: string; me: boolean };

const TOKEN = /(`[^`\n]+`)|(\*\*[^*\n]+\*\*)|(\*[^*\n]+\*)|(@[a-z-]+)|(https?:\/\/\S+)/gi;

function parseSegments(text: string): Seg[] {
  const out: Seg[] = [];
  let last = 0;
  for (const match of text.matchAll(TOKEN)) {
    const i = match.index ?? 0;
    if (i > last) out.push({ k: "text", text: text.slice(last, i) });
    const [full, code, bold, ital, mention, link] = match;
    if (code) out.push({ k: "code", text: code.slice(1, -1) });
    else if (bold) out.push({ k: "bold", text: bold.slice(2, -2) });
    else if (ital) out.push({ k: "ital", text: ital.slice(1, -1) });
    else if (mention) out.push({ k: "mention", text: full, me: full === "@you" });
    else if (link) {
      const href = link.replace(/[.,;:!?]+$/, "");
      out.push({ k: "link", text: href, href });
    }
    last = i + full.length;
  }
  if (last < text.length) out.push({ k: "text", text: text.slice(last) });
  return out;
}

const segCache = new WeakMap<Msg, { text: string; segs: Seg[] }>();
function segs(m: Msg): Seg[] {
  const hit = segCache.get(m);
  if (hit && hit.text === m.text) return hit.segs;
  const next = { text: m.text, segs: parseSegments(m.text) };
  segCache.set(m, next);
  return next.segs;
}

function SegView(g: Seg) {
  if (g.k === "code") return span(s.code, g.text);
  if (g.k === "bold") return span({ style: { fontWeight: "700" } }, g.text);
  if (g.k === "ital") return span({ style: { fontStyle: "italic" } }, g.text);
  if (g.k === "link") return a({ href: g.href, target: "_blank", rel: "noopener" }, s.link, g.text);
  if (g.k === "mention") return span(g.me ? s.mentionMe : s.mention, g.text);
  return span(g.text);
}

// ── The pieces ──

function ReactionChip(m: Msg, r: Reaction) {
  return button(
    {
      type: "button",
      class: () => cx(s.reaction, r.mine ? s.reactionMine : null).className,
      title: () => `${r.emoji} — ${r.count}`,
      "aria-label": `${r.emoji}: ${r.count} reaction${r.count === 1 ? "" : "s"}${r.mine ? ", yours" : ""}`,
      onClick: () => {
        react(m, r.emoji, !r.mine); // yours leaves, theirs joins
        relayoutUnder(rowOf(m));
      },
    },
    span(r.emoji),
    span(s.reactionCount, () => String(r.count)),
  );
}

function MessageRow(m: Msg) {
  return article(
    s.msg,
    {
      "data-msg": () => String(m.id), // reactive: the optimistic -1 becomes the server id when send() settles
      class: () => cx(s.msg, m.first ? s.first : null, m.status === "sent" ? null : m.status === "sending" ? s.sending : s.failed, m.fresh ? s.live : null, m.text.includes("@you") ? s.mentionRow : null).className,
    },
    when(() => m.day !== "", div(s.day, () => m.day)),
    when(() => active.firstUnseen === m, div(s.divider, span("New messages"), button(s.dividerBtn, { type: "button", onClick: markRead }, "Mark as read"))),
    when(
      () => m.first,
      div(s.avatar, { style: { backgroundColor: `hsl(${hue(m.author)} 55% 48%)` }, title: m.author }, m.author[0].toUpperCase()),
      div(s.meta, strong(m.author), time({ title: fullTime(m.at) }, clock(m.at)), when(() => m.edited, span(s.edited, "(edited)"))),
    ),
    when(
      () => m.editing,
      textarea(s.edit, { "aria-label": "Edit message", value: m.text }, {
        onKeyDown: (e) => {
          if (e.key === "Enter" && !e.shiftKey && !e.isComposing) { e.preventDefault(); saveEdit(m, e.currentTarget.value); }
          else if (e.key === "Escape") cancelEdit(m);
        },
      }, on("mount", (el) => { el.focus(); el.setSelectionRange(el.value.length, el.value.length); })),
    ),
    when(() => !m.editing, p(s.text, list(() => segs(m), SegView))),
    when(() => m.reactions.length > 0, div(s.reactions, list(() => m.reactions, (r) => ReactionChip(m, r)))),
    when(
      () => picker === m,
      div(s.picker, ...EMOJIS.map((emoji) => button(s.pick, { type: "button", title: emoji, "aria-label": `React with ${emoji}`, onClick: () => toggleReaction(m, emoji) }, emoji))),
    ),
    when(
      () => m.status === "sent" && !m.editing,
      div(s.actions, { "data-chat-actions": "" },
        button(s.action, { type: "button", title: "Add a reaction", "aria-label": "Add a reaction", onClick: () => { picker = picker === m ? null : m; relayoutUnder(rowOf(m)); } }, "😊"),
        button(s.action, { type: "button", "aria-label": "Copy message", onClick: () => copy(m) }, () => (m.copied ? "✓ Copied" : "Copy")),
        when(
          () => m.author === ME,
          button(s.action, { type: "button", "aria-label": "Edit message", onClick: () => startEdit(m) }, "Edit"),
          button(s.action, { type: "button", "aria-label": "Delete message", onClick: () => remove(m) }, "Delete"),
        ),
      ),
    ),
    when(
      () => m.status === "failed",
      div(s.retry, "Not sent.", button(s.small, { type: "button", onClick: () => deliver(m) }, "Retry"), button(s.small, { type: "button", onClick: () => remove(m) }, "Delete")),
    ),
  );
}

// The row above the oldest message: it asks for the page before it while it
// is still well out of view, and says how that went.
function Sentinel() {
  return div(
    s.top,
    on("mount", (el) => {
      const observer = new IntersectionObserver(
        ([entry]) => { if (entry.isIntersecting) loadOlder(); },
        { root: el.parentElement, rootMargin: "800px" },
      );
      observer.observe(el);
      lookAgain = () => { observer.unobserve(el); observer.observe(el); };
      return () => { observer.disconnect(); lookAgain = null; }; // left set, it would keep this element alive
    }),
    when(() => active.error !== null, div(s.error, span(() => active.error ?? ""), button(s.btn, { type: "button", onClick: () => { active.error = null; loadOlder(); } }, "Retry")))
      .when(() => active.atStart, p(s.beginning, () => `This is the beginning of ${active.info.name}.`))
      .else(p(s.loading, "Loading older messages…")),
  );
}

// A channel row: the badge is the only thing an inactive channel updates.
function Sidebar() {
  return nav(
    s.sidebar,
    scope("chat-sidebar"),
    { "data-chat-sidebar": "", class: () => cx(s.sidebar, menu ? null : s.sidebarClosed).className },
    div(s.brand, div(s.logo, "◆"), "nuclo chat"),
    div(s.sideLabel, "Channels"),
    list(() => channels, (ch) =>
      button(
        {
          type: "button",
          class: () => cx(s.channel, ch === active ? s.channelOn : null).className,
          "aria-current": () => String(ch === active),
          title: ch.info.topic,
          onClick: () => openChannel(ch),
        },
        span(s.hash, "#"),
        span(s.channelName, () => ch.info.name.slice(2)),
        when(() => ch.unread > 0, span(s.badge, () => (ch.unread > 99 ? "99+" : String(ch.unread)))),
      )),
    div(s.sideFoot,
      div(s.you,
        div(s.youAvatar, "y"),
        div(s.youMeta,
          span(s.youName, "you"),
          span(s.youSub, () => `${channels.length} channels · ${channels.reduce((n, c) => n + c.online, 0)} people online`),
        ),
      ),
    ),
  );
}

// Switching channels keeps the one you leave, exactly as it was.
function openChannel(ch: Channel) {
  if (ch === active) { menu = false; update(); return; }
  active.atBottom = nearBottom();
  active.scrollTop = scroller?.scrollTop ?? 0;
  active = ch;
  menu = false;
  picker = null;
  composerPicker = false;
  const away = ch.unread; // what arrived while this channel was closed
  ch.unread = 0;
  // Clicking the channel button blurs the composer: on a pointer-fine device,
  // put the cursor back so the reader can keep typing. On touch, leave it —
  // focusing would pop the keyboard over the conversation.
  const focusComposer = composerFocused || (document.activeElement instanceof HTMLElement && document.activeElement.getAttribute("aria-current") !== null);
  const pointerFine = matchMedia("(hover: hover)").matches;
  update();
  if (scroller) {
    if (ch.atBottom) {
      toBottom();
      ch.unseen = 0;
      ch.firstUnseen = null;
    } else {
      scroller.scrollTop = ch.scrollTop;
      ch.unseen += away; // what arrived while away joins what was already unread
      if (nearBottom()) {
        ch.unseen = 0;
        ch.firstUnseen = null;
      }
    }
  }
  if (focusComposer && pointerFine) composerEl?.focus();
  lookAgain?.(); // the sentinel may be in view again: load the next page
}

export function ChatApp() {
  return div(
    s.app,
    on("mount", () => {
      const disconnect = connect(receive);
      loadOlder();
      return () => {
        disconnect();
        channels.forEach((ch) => { ch.typing.clear(); ch.unseen = 0; ch.firstUnseen = null; });
      };
    }),
    Sidebar(),
    when(() => menu, div(s.backdrop, { onClick: () => { menu = false; update(); } })),
    div(
      s.main,
      header(
        s.head,
        button(s.menuBtn, { type: "button", "aria-label": "Channels", "aria-expanded": () => String(menu), onClick: () => { menu = !menu; update(); } }, "☰"),
        div(s.headMain, strong(() => active.info.name), span(s.topic, () => active.info.topic)),
        span(s.online, () => (active.online ? `${active.online} online` : "connecting…")),
        span(s.state, () => `${active.messages.length} messages in the DOM · ${active.loading ? "loading history…" : active.atStart ? "all of it" : "scroll up for more"}`),
      ),
      div(
        s.pane,
        scope("chat-pane"),
        div(
          s.log,
          on("mount", (el) => {
            scroller = el;
            toBottom(); // opened again: the messages are still here, show the newest
            return () => { scroller = null; };
          }),
          { onScroll: () => { if (active.unseen > 0 && nearBottom()) { active.unseen = 0; active.firstUnseen = null; update("chat-pane"); } } },
          Sentinel(),
          list(() => active.messages, MessageRow),
          when(() => active.typing.size > 0, div(s.typingRow, { "aria-live": "polite" }, span(s.dots, i(), i(), i()), span(() => typingText()))),
        ),
        when(
          () => active.unseen > 0,
          button(s.pill, () => `${active.unseen} new message${active.unseen === 1 ? "" : "s"} ↓`, { onClick: () => { markRead(); toBottom("smooth"); } }),
        ),
      ),
      div(
        s.composerArea,
        scope("chat-composer"), // one scope for the picker and the form: a keystroke or an emoji click refreshes only this
        when(
          () => composerPicker,
          div(s.composerPicker, ...EMOJIS.map((emoji) => button(s.pick, { type: "button", title: emoji, "aria-label": `Add ${emoji}`, onClick: () => insertEmoji(emoji) }, emoji))),
        ),
        form(
          s.composer,
          { onSubmit: (e) => { e.preventDefault(); submit(); } },
          textarea(s.input, { rows: 1, placeholder: () => `Message ${active.info.name}`, "aria-label": "Message", value: () => active.draft }, {
            onInput: (e) => { active.draft = e.currentTarget.value; update("chat-composer"); }, // a keystroke only refreshes the composer
            onKeyDown: (e) => {
              if (e.key === "Enter" && !e.shiftKey && !e.isComposing) { e.preventDefault(); submit(); }
              else if (e.key === "ArrowUp" && active.draft === "" && e.currentTarget.selectionStart === 0) {
                const last = lastOwn();
                if (last) { e.preventDefault(); startEdit(last); } // ↑ edits your last message
              }
            },
            onFocus: () => { composerFocused = true; },
            onBlur: () => { composerFocused = false; },
          }, on("mount", (el) => { composerEl = el; el.focus(); return () => { composerEl = null; }; })),
          button(s.emojiBtn, { type: "button", title: "Add an emoji", "aria-label": "Add an emoji", onClick: () => { composerPicker = !composerPicker; update("chat-composer"); } }, "😊"),
          button(s.send, { type: "submit", disabled: () => !active.draft.trim() }, "Send"),
        ),
      ),
    ),
  );
}

// server.ts: a fake multi-channel chat backend and its socket. Each channel's
// history is generated from its message ids, so the same cursor always returns
// the same page. Requests take a moment, and sending sometimes fails. The
// socket brings what other people post — per channel — after showing that they
// are typing; a bot answers what you send, and once in a while someone reacts
// to a message. Nothing here knows about the UI.

export interface Message {
  id: number;
  author: string;
  text: string;
  at: number; // ms since the epoch
}

export interface ChannelInfo {
  id: string;
  name: string; // "# general"
  topic: string;
}

export type ChannelEvent =
  | { type: "typing"; channel: string; author: string }
  | { type: "message"; channel: string; message: Message }
  | { type: "reaction"; channel: string; messageId: number; emoji: string }
  | { type: "online"; channel: string; count: number };

export const ME = "you";
const BOT = "nuclo-bot";
const PAGE = 30;
const GAP = 4 * 60_000; // ms between two history messages, on average

// Each channel: how much history it has, and a salt so its archive differs.
export const CHANNELS: ChannelInfo[] = [
  { id: "general", name: "# general", topic: "The build, the demos and everything in between" },
  { id: "random", name: "# random", topic: "Off-topic: lunch, keyboards, compilers" },
  { id: "nuclo", name: "# nuclo", topic: "One update() call at a time" },
];
const SIZE: Record<string, number> = { general: 5000, random: 3000, nuclo: 2000 };
const SALT: Record<string, number> = { general: 1, random: 2, nuclo: 3 };

const AUTHORS = ["Ada", "Grace", "Linus", "Margaret", "Dennis", "Barbara", "Ken", "Radia"];
const SHORT = ["+1", "lgtm", "nice!", "on it", "ha, same", "thanks!", "which branch?", "merged", "brb, coffee", "can't reproduce"];
const OPENERS = ["Pushed a fix for", "Reviewed", "Reverted", "Finally fixed", "Still debugging", "Benchmarked", "Rewrote", "Deleted half of", "Paired on", "Wrote tests for"];
const SUBJECTS = ["the list diff", "the router", "the docs build", "hydration", "the style engine", "the flaky test", "the update loop", "the scroll anchoring", "the composer", "the fake socket"];
const ENDINGS = ["today.", "before lunch.", "on main.", "with half the code.", "in one update() call.", "without a store.", "if anyone wants to look.", "for the next release.", "with Ada.", "this morning."];
const REPLIES = ["Noted.", "Agreed.", "Tell me more.", "Filed under #general.", "Everyone saw that after one update()."];

// #nuclo posts are markdown-heavy, so the demo shows code spans, bold, links
// and @mentions; #random is short and loud.
const MD = [
  "**merged** the router after `list()` matched every row by identity.",
  "`update()` twice, no store: the message showed before the server had it, and Retry just calls `send()` again.",
  "Pushed a fix for the **hydration** edge case: `scope()` ids are cleaned up now.",
  "see https://nuclo.dev/en/docs#api-list for how a `list()` reconciles.",
  "@you have you tried **Shift+Enter** in the composer? `field-sizing` grows it for you.",
  "Benchmarked the style engine: `css()` compiles once, `cx()` just compares class strings.",
  "Rewrote the update loop with `queueMicrotask`: every `update()` in one tick coalesces.",
  "`unshift()` the older page, grow `scrollTop` by the height it added: nothing on screen moves.",
  "The typing line is `when(() => typing.size > 0, …)`: one update() and it is there.",
];
const RANDOM = [
  "lunch was **tacos** 🌮", "brb, coffee ☕", "anyone tried `nuclo@next` yet?",
  "ship it 🚀", "**weekend** plans: rewrite the router in 300 lines", "🎉 it passed on main",
  "the demo ate my `localStorage`, nice", "keyboard arrived, typing **+11%** faster",
];

// A small integer hash: every field of a history message is a function of its id.
function hash(n: number) {
  n = Math.imul(n ^ (n >>> 16), 0x45d9f3b);
  n = Math.imul(n ^ (n >>> 16), 0x45d9f3b);
  return (n ^ (n >>> 16)) >>> 0;
}
const pick = <T,>(list: T[], n: number, salt: number) => list[hash(n * 31 + salt) % list.length];
const random = <T,>(list: T[]) => list[Math.floor(Math.random() * list.length)];

const sentence = (ch: ChannelInfo, n: number) => `${pick(OPENERS, n, SALT[ch.id] + 2)} ${pick(SUBJECTS, n, SALT[ch.id] + 3)} ${pick(ENDINGS, n, SALT[ch.id] + 4)}`;

// Any number makes a message: a short reply, or one to three sentences.
function say(ch: ChannelInfo, n: number) {
  const h = hash(n * 31 + SALT[ch.id]);
  if (ch.id === "nuclo") return h % 4 === 0 ? pick(SHORT, n, SALT[ch.id]) : pick(MD, n, SALT[ch.id] + 7);
  if (ch.id === "random") return h % 3 === 0 ? pick(SHORT, n, SALT[ch.id]) : pick(RANDOM, n, SALT[ch.id] + 7);
  if (h % 4 === 0) return pick(SHORT, n, SALT[ch.id]);
  return Array.from({ length: 1 + ((h % 7) % 3) }, (_, i) => sentence(ch, n * 3 + i)).join(" ");
}

const opened = Date.now(); // the history ends when this module loads; everything after arrives live

function archived(ch: ChannelInfo, id: number): Message {
  // Messages come in bursts: most of a block of four share an author.
  const author = pick(AUTHORS, hash(id * 7 + SALT[ch.id]) % 5 === 0 ? id : id >> 2, 5);
  // Each message gets a slot GAP wide and a random spot in it, so time only moves forward.
  return { id, author, text: say(ch, id), at: opened - (SIZE[ch.id] - id) * GAP + (hash(id + SALT[ch.id]) % GAP) };
}

/** The messages before `before` (the id of the oldest one you have), oldest first. Empty at the beginning of the channel. */
export function fetchHistory(channelId: string, before = SIZE[channelId]): Promise<Message[]> {
  const ch = CHANNELS.find((c) => c.id === channelId) ?? CHANNELS[0];
  return new Promise((resolve) => {
    setTimeout(() => {
      const from = Math.max(0, before - PAGE);
      resolve(Array.from({ length: before - from }, (_, i) => archived(ch, from + i)));
    }, 300 + Math.random() * 400);
  });
}

const EMOJIS = ["👍", "🚀", "😂", "❤️", "🔥"];
const nextId: Record<string, number> = { general: 5000, random: 3000, nuclo: 2000 };
const online: Record<string, number> = { general: 9, random: 5, nuclo: 4 };
let listener: ((e: ChannelEvent) => void) | null = null;
const timers = new Set<ReturnType<typeof setTimeout>>();

const emit = (e: ChannelEvent) => listener?.(e);
const stamp = (channelId: string, author: string, text: string): Message => ({ id: nextId[channelId]++, author, text, at: Date.now() });

// A timer the socket owns: disconnecting clears every one still pending.
function later(ms: number, fn: () => void) {
  const timer = setTimeout(() => { timers.delete(timer); fn(); }, ms);
  timers.add(timer);
}

function typeThenPost(ch: ChannelInfo, author: string, text: string, ms: number) {
  emit({ type: "typing", channel: ch.id, author });
  later(ms, () => {
    const message = stamp(ch.id, author, text);
    emit({ type: "message", channel: ch.id, message });
    if (Math.random() < 0.3) {
      later(900 + Math.random() * 1500, () => emit({ type: "reaction", channel: ch.id, messageId: message.id, emoji: random(EMOJIS) }));
    }
  });
}

// Other people, now and then: someone types and posts, someone comes or goes.
function chatter(ch: ChannelInfo) {
  if (Math.random() < 0.3) {
    online[ch.id] = Math.max(2, online[ch.id] + (Math.random() < 0.5 ? -1 : 1));
    emit({ type: "online", channel: ch.id, count: online[ch.id] });
  }
  typeThenPost(ch, random(AUTHORS), say(ch, Math.floor(Math.random() * 1e9)), 1500 + Math.random() * 2500);
  later(5000 + Math.random() * 7000, () => chatter(ch));
}

/** Stores your message. It takes a moment and fails about one time in seven; then the bot answers and someone may react. */
export function send(channelId: string, text: string): Promise<Message> {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (Math.random() < 0.15) return reject(new Error("Not delivered."));
      const message = stamp(channelId, ME, text);
      resolve(message);
      const quote = text.length > 48 ? `${text.slice(0, 48)}…` : text;
      later(600, () => typeThenPost(CHANNELS.find((c) => c.id === channelId) ?? CHANNELS[0], BOT, `“${quote}”: ${random(REPLIES)}`, 1200));
      if (Math.random() < 0.7) {
        later(1500 + Math.random() * 1800, () => emit({ type: "reaction", channel: channelId, messageId: message.id, emoji: random(EMOJIS) }));
      }
    }, 400 + Math.random() * 600);
  });
}

/** Opens the socket: `onEvent` hears typing, messages, reactions and the online count of every channel. Returns the disconnect. */
export function connect(onEvent: (e: ChannelEvent) => void) {
  listener = onEvent;
  for (const ch of CHANNELS) {
    emit({ type: "online", channel: ch.id, count: online[ch.id] });
    later(1500 + Math.random() * 2500, () => chatter(ch));
  }
  return () => {
    listener = null;
    timers.forEach(clearTimeout);
    timers.clear();
  };
}

// app.ts: the dashboard. Every card is a scope() with its own timer: the timer
// moves the card's feed one step, then calls update() with the card's id, so a
// tick evaluates that card's dynamic values and nothing else. Every dynamic
// value goes through count(), which is how the page shows the cost. In
// "update() everything" mode each timer calls update() with no id: the page
// looks the same, but every tick of every timer evaluates every card.
import "nuclo";
import { HISTORY, SAMPLES, change, clock, load, orders, pushOrder, stepClock, stepLoad, stepTickers, tickers, type Ticker } from "./feeds.ts";
import { s } from "./styles.ts";

type Count = <T>(fn: () => T) => () => T;

let scoped = true; // false: every timer calls update() instead of update(id)
let paused = false;

// Evaluations per scope id: counted as they happen, turned into a rate once a second.
const meters = new Map<string, { count: number; rate: number }>();

function counter(id: string) {
  const meter = { count: 0, rate: 0 };
  meters.set(id, meter); // a card built again (the example reopened) starts from zero
  const count: Count = (fn) => () => { meter.count++; return fn(); };
  return { meter, count };
}

const refresh = (id: string) => (scoped ? update(id) : update());

// Runs step() after every delay(), then refreshes the card it feeds.
function every(delay: () => number, id: string, step: () => void) {
  let timer = setTimeout(function tick() {
    if (!paused) { step(); refresh(id); }
    timer = setTimeout(tick, delay());
  }, delay());
  return () => clearTimeout(timer);
}

// "x,y x,y …" for a polyline: x is the index, y puts min at the bottom of an
// h-tall box and max at the top.
function points(values: number[], h: number, min = Math.min(...values), max = Math.max(...values)) {
  return values.map((v, i) => `${i},${(h - ((v - min) / (max - min || 1)) * h).toFixed(1)}`).join(" ");
}

const percent = (values: number[]) => points(values, 100, 0, 100);
const latest = (values: number[]) => Math.round(values[SAMPLES - 1]);
const signed = (n: number) => `${n < 0 ? "" : "+"}${n.toFixed(2)}%`;
const money = (cents: number) => `$${(cents / 100).toFixed(2)}`;

// A card is one scope. Its head names the call its timer makes and how many
// of its dynamic values ran in the last second. That label also carries the
// shared "dash-meter" id: one update("dash-meter") refreshes it in every card.
function Card(id: string, title: string, rate: string, body: (count: Count) => NodeModLike<"section">[]) {
  const { meter, count } = counter(id);
  return section(
    s.card,
    scope(id),
    header(s.cardHead, h3(title), span(s.rate, rate), span(s.evals, scope("dash-meter"), count(() => `${meter.rate} evals/s`))),
    code(s.call, count(() => (scoped ? `update("${id}")` : "update()"))),
    ...body(count),
  );
}

function TickerRow(t: Ticker, count: Count) {
  return li(
    s.ticker,
    { class: count(() => cx(s.ticker, change(t) < 0 ? s.down : s.up).className) },
    strong(t.symbol),
    svgSvg(
      s.spark,
      { viewBox: `0 0 ${HISTORY - 1} 20`, preserveAspectRatio: "none", "aria-hidden": "true" },
      polylineSvg(s.line, { points: count(() => points(t.history, 20)) }),
    ),
    span(s.price, count(() => t.price.toFixed(2))),
    span(count(() => signed(change(t)))),
  );
}

const Tickers = () =>
  Card("dash-tickers", "Tickers", "20/s", (count) => [s.tall, ul(s.tickers, ...tickers.map((t) => TickerRow(t, count)))]);

const Load = () =>
  Card("dash-load", "Server load", "4/s", (count) => [
    s.wide,
    div(
      s.readings,
      span(s.cpu, count(() => `CPU ${latest(load.cpu)}%`)),
      span(s.memory, count(() => `Memory ${latest(load.memory)}%`)),
      span(count(() => `${load.rps} req/s`)),
    ),
    svgSvg(
      s.chart,
      { viewBox: `0 0 ${SAMPLES - 1} 100`, preserveAspectRatio: "none", role: "img", "aria-label": "CPU and memory, last 15 seconds" },
      ...[25, 50, 75].map((y) => lineSvg(s.rule, { x1: 0, y1: y, x2: SAMPLES - 1, y2: y })),
      polygonSvg(s.area, { points: count(() => `0,100 ${percent(load.cpu)} ${SAMPLES - 1},100`) }), // the CPU line, closed along the bottom
      polylineSvg(s.line, s.cpu, { points: count(() => percent(load.cpu)) }),
      polylineSvg(s.line, s.memory, { points: count(() => percent(load.memory)) }),
    ),
  ]);

const Clock = () =>
  Card("dash-clock", "Clock", "1/s", (count) => [
    div(
      s.clock,
      strong(count(() => clock.now?.toLocaleTimeString() ?? "--:--:--")),
      span(count(() => clock.now?.toLocaleDateString([], { weekday: "long", month: "long", day: "numeric" }) ?? "")),
    ),
  ]);

// A new order builds one row on top (it flashes) and the oldest row goes: the rest are kept.
const Orders = () =>
  Card("dash-log", "Orders", "~1/s", (count) => [
    ol(
      s.log,
      list(count(() => orders), (o) => li(s.order, span(s.id, `#${o.id}`), span(s.what, `${o.who} · ${o.qty} × ${o.item}`), span(money(o.cents)))),
    ),
  ]);

function Stats() {
  const { count } = counter("dash-stats");
  const total = () => [...meters.values()].reduce((sum, m) => sum + m.rate, 0);
  const mode = (value: boolean, text: string) =>
    button(
      s.mode,
      { class: count(() => cx(s.mode, scoped === value ? s.on : null).className), "aria-pressed": count(() => String(scoped === value)) },
      text,
      { onClick: () => { scoped = value; update(); } }, // every card's call label changes
    );
  return header(
    s.stats,
    scope("dash-stats"),
    p(s.total, scope("dash-meter"), strong(count(() => String(total()))), "dynamic values evaluated per second"),
    div(
      s.controls,
      div(s.modes, { role: "group", "aria-label": "Update mode" }, mode(true, "Scoped updates"), mode(false, "update() everything")),
      button(s.btn, count(() => (paused ? "Resume" : "Pause")), { onClick: () => { paused = !paused; update("dash-stats"); } }),
    ),
    p(
      s.hint,
      "Every card is a ", code("scope()"), ", and its timer calls ", code('update("its id")'),
      ": a tick evaluates that card and nothing else. Switch to ", code("update()"),
      " everything: the page looks the same, but every tick now evaluates every card. The clock still changes once a second; watch how often it is evaluated.",
    ),
  );
}

export function LiveDashboard() {
  return div(
    s.app,
    on("mount", () => {
      const stops = [
        every(() => 50, "dash-tickers", stepTickers),
        every(() => 250, "dash-load", stepLoad),
        every(() => 1000 - (Date.now() % 1000), "dash-clock", stepClock), // on the second, like a real clock
        every(() => 300 + Math.random() * 1700, "dash-log", pushOrder), // whenever an order comes in
      ];
      // The meter ignores Pause: it keeps showing what still runs.
      const meter = setInterval(() => {
        for (const m of meters.values()) { m.rate = m.count; m.count = 0; }
        refresh("dash-meter");
      }, 1000);
      return () => { stops.forEach((stop) => stop()); clearInterval(meter); };
    }),
    Stats(),
    div(s.grid, Tickers(), Load(), Clock(), Orders()),
  );
}

// feeds.ts: the data sources. Stock prices, server load, an order log and a
// clock, each moved one step forward by its own function. They are plain
// numbers and arrays, and none of them knows who shows them or how often.
// The first values come from a hash of an index, so the server and the
// browser start from the same numbers; Math.random() only runs once they tick.

export const HISTORY = 40; // prices kept per ticker
export const SAMPLES = 60; // load samples kept: 15 seconds at 4 a second
const LOG_SIZE = 8; // orders kept

// A small integer hash, as in infinite-scroll/api.ts. unit() maps it to [0, 1).
function hash(n: number) {
  n = Math.imul(n ^ (n >>> 16), 0x45d9f3b);
  n = Math.imul(n ^ (n >>> 16), 0x45d9f3b);
  return (n ^ (n >>> 16)) >>> 0;
}
const unit = (n: number) => hash(n) / 2 ** 32;
const pick = <T,>(list: T[], id: number, salt: number) => list[hash(id * 31 + salt) % list.length];

// `length` values, each one next() of the one before it, fed a fixed random number.
function series(first: number, length: number, salt: number, next: (prev: number, r: number) => number) {
  const values = [first];
  while (values.length < length) values.push(next(values[values.length - 1], unit(salt + values.length)));
  return values;
}

// Drops the oldest value and appends the newest, in place.
function roll(values: number[], value: number) {
  values.shift();
  values.push(value);
  return value;
}

// ── Tickers: a random walk, one step per tick ────────────────────────────

export interface Ticker {
  symbol: string;
  open: number; // the first price: the change is measured from it
  price: number;
  history: number[]; // the last HISTORY prices, oldest first
}

const walk = (price: number, r: number) => price * (1 + (r - 0.5) * 0.004); // ±0.2% at most

export const tickers: Ticker[] = ["NUCL", "ACME", "BYTE", "CORE", "HTML", "LIST", "NODE", "WHEN"].map((symbol, i) => {
  const history = series(20 + unit(i + 1) * 300, HISTORY, i * 100, walk);
  return { symbol, open: history[0], price: history[HISTORY - 1], history };
});

/** The change since the open, in percent. */
export const change = (t: Ticker) => (t.price / t.open - 1) * 100;

export function stepTickers() {
  for (const t of tickers) t.price = roll(t.history, walk(t.price, Math.random()));
}

// ── Server load: CPU and memory in percent, and requests per second ──────

// Each sample lands up to `step` points away from the last one.
const wander = (step: number) => (prev: number, r: number) => Math.min(98, Math.max(2, prev + (r - 0.5) * 2 * step));
const nextCpu = wander(9);
const nextMemory = wander(1.5);

export const load = { cpu: series(40, SAMPLES, 1000, nextCpu), memory: series(62, SAMPLES, 2000, nextMemory), rps: 1000 };

export function stepLoad() {
  const cpu = roll(load.cpu, nextCpu(load.cpu[SAMPLES - 1], Math.random()));
  roll(load.memory, nextMemory(load.memory[SAMPLES - 1], Math.random()));
  load.rps = Math.round(cpu * 24 + Math.random() * 120); // a busier server is serving more
}

// ── Orders: newest first, the oldest falls off ───────────────────────────

export interface Order {
  id: number;
  who: string;
  qty: number;
  item: string;
  cents: number;
}

const NAMES = ["Ada", "Grace", "Linus", "Margaret", "Dennis", "Barbara", "Ken", "Radia"];
const ITEMS: [string, number][] = [["keyboard", 8900], ["monitor", 24900], ["mouse", 3900], ["desk lamp", 4500], ["headset", 12900], ["webcam", 7900]];

// An order is a fixed function of its id, like a post in infinite-scroll/api.ts.
// Only when the next one arrives is random, and the app's timer decides that.
function order(id: number): Order {
  const [item, price] = pick(ITEMS, id, 1);
  const qty = pick([1, 1, 1, 2, 3], id, 2);
  return { id, who: pick(NAMES, id, 3), qty, item, cents: qty * price };
}

let nextId = 1000;
export const orders: Order[] = Array.from({ length: LOG_SIZE }, () => order(nextId++)).reverse();

export function pushOrder() {
  orders.unshift(order(nextId++));
  if (orders.length > LOG_SIZE) orders.pop();
}

// ── Clock ────────────────────────────────────────────────────────────────

// null until the first tick: the server and the browser have no "now" to agree on.
export const clock = { now: null as Date | null };

export function stepClock() {
  clock.now = new Date();
}

// app.ts: the editor. The picture is one plain array of colors, and each of
// its 1024 cells reads its color from that array. A stroke writes into the
// array and calls update(); when it ends, history.ts keeps a copy. Undo, redo
// and the history panel only put an older copy back.
import "nuclo";
import { SIZE, at, blank, commit, fill, get, history, jump, line, load, mushroom, pixels, redo, undo, type Snapshot } from "./history.ts";
import { s } from "./styles.ts";

const TOOLS = [
  { name: "Pencil", key: "B" },
  { name: "Eraser", key: "E" },
  { name: "Fill", key: "G" },
  { name: "Picker", key: "I" },
] as const;
type Tool = (typeof TOOLS)[number]["name"];

const PALETTE = ["#1f2937", "#6b7280", "#d1d5db", "#ffffff", "#ef4444", "#f97316", "#facc15", "#fde68a", "#22c55e", "#15803d", "#14b8a6", "#38bdf8", "#2563eb", "#8b5cf6", "#ec4899", "#92400e"];

let tool: Tool = "Pencil";
let color = "#ef4444";
let stroke: { tool: Tool; ink: string; x: number; y: number; changed: number } | null = null; // a pencil or eraser drag

// Picking a color means painting with it next: leave the eraser and the picker.
function choose(c: string) {
  color = c;
  if (tool !== "Fill") tool = "Pencil";
}

function replace(label: string, next: string[]) {
  load(next);
  commit(label);
  update();
}

// The cell under the pointer, from coordinates rather than from the event
// target: with pointer capture, a drag keeps reporting to the canvas, even
// outside it (those cells are off the picture and paint nothing).
function cellAt(e: PointerEvent, el: HTMLElement) {
  const r = el.getBoundingClientRect();
  return [Math.floor(((e.clientX - r.left) / r.width) * SIZE), Math.floor(((e.clientY - r.top) / r.height) * SIZE)];
}

function Canvas() {
  return div(
    s.canvas,
    { role: "img", "aria-label": `Canvas, ${SIZE} by ${SIZE} pixels` },
    {
      onPointerDown: (e) => {
        if (e.button !== 0) return;
        const [x, y] = cellAt(e, e.currentTarget);
        if (tool === "Picker") { const c = get(x, y); if (c) choose(c); }
        else if (tool === "Fill") commit(`Fill · ${fill(x, y, color)} px`);
        else {
          e.currentTarget.setPointerCapture(e.pointerId);
          const ink = tool === "Eraser" ? "" : color;
          stroke = { tool, ink, x, y, changed: line(x, y, x, y, ink) };
        }
        update();
      },
      onPointerMove: (e) => {
        if (!stroke) return;
        const [x, y] = cellAt(e, e.currentTarget);
        if (x === stroke.x && y === stroke.y) return;
        stroke.changed += line(stroke.x, stroke.y, x, y, stroke.ink); // the whole segment: fast drags skip cells
        stroke.x = x;
        stroke.y = y;
        update();
      },
      // Fires when the stroke's pointer goes up, and when the browser cancels it.
      onLostPointerCapture: () => {
        if (stroke) commit(`${stroke.tool} · ${stroke.changed} px`);
        stroke = null;
        update();
      },
    },
    // The cells never come and go, so they are built once; only their color is read again.
    ...pixels.map((_, i) => div(s.cell, { style: () => ({ backgroundColor: pixels[i] }) })),
  );
}

const ToolButton = (t: (typeof TOOLS)[number]) =>
  button(
    s.tool,
    { class: () => cx(s.tool, tool === t.name ? s.on : null).className, "aria-pressed": () => String(tool === t.name), title: `${t.name} (${t.key})` },
    t.name,
    kbd(t.key),
    { onClick: () => { tool = t.name; update(); } },
  );

const Swatch = (c: string) =>
  button(s.swatch, {
    style: { backgroundColor: c },
    title: c,
    "aria-label": `Color ${c}`,
    class: () => cx(s.swatch, c === color ? s.picked : null).className,
    onClick: () => { choose(c); update(); },
  });

// A snapshot never changes, so its thumbnail is drawn once, when its row mounts.
const Thumb = (snap: Snapshot) =>
  canvas(s.thumb, { width: SIZE, height: SIZE, "aria-hidden": "true" }, on("mount", (el) => {
    const ctx = el.getContext("2d")!;
    snap.pixels.forEach((c, i) => { if (c) { ctx.fillStyle = c; ctx.fillRect(i % SIZE, Math.floor(i / SIZE), 1, 1); } });
  }));

function Entry(snap: Snapshot) {
  const i = () => history.indexOf(snap);
  return button(
    s.entry,
    { class: () => cx(s.entry, i() === at ? s.current : i() > at ? s.future : null).className, "aria-current": () => String(i() === at) },
    Thumb(snap),
    span(snap.label),
    { onClick: () => { jump(i()); update(); } }, // time travel: any snapshot, either direction
  );
}

// Shortcuts listen on the document in the capture phase: they work wherever
// the focus is, and a key handled here is defaultPrevented before the modal sees it.
function shortcuts(el: HTMLElement) {
  const onKey = (e: KeyboardEvent) => {
    // Not while a source tab hides the editor, nor while typing in the color field.
    if (!el.offsetParent || e.altKey || e.target instanceof HTMLInputElement) return;
    const key = e.key.toUpperCase();
    const t = TOOLS.find((t) => t.key === key);
    if (e.ctrlKey || e.metaKey) {
      if (key === "Z") (e.shiftKey ? redo : undo)();
      else if (key === "Y") redo();
      else return;
    } else if (t) tool = t.name;
    else return;
    e.preventDefault();
    update();
  };
  document.addEventListener("keydown", onKey, true);
  return () => {
    document.removeEventListener("keydown", onKey, true);
    stroke = null; // a drag cut short by closing the example must not go on at the next visit
  };
}

export function PixelEditor() {
  return div(
    s.app,
    on("mount", shortcuts),
    div(
      s.tools,
      ...TOOLS.map(ToolButton),
      div(s.palette, ...PALETTE.map(Swatch)),
      label(s.custom, input({ type: "color", value: () => color }, { onInput: (e) => { choose(e.currentTarget.value); update(); } }), "Custom"),
      div(
        s.actions,
        button(s.btn, "Clear", { onClick: () => replace("Clear", blank()) }),
        button(s.btn, "Mushroom", { title: "Start again from the mushroom", onClick: () => replace("Mushroom", mushroom()) }),
      ),
    ),
    div(s.stage, Canvas()),
    aside(
      s.history,
      div(
        s.head,
        strong("History"),
        button(s.btn, "Undo", { title: "Undo (Ctrl+Z)", disabled: () => at === 0, onClick: () => { undo(); update(); } }),
        button(s.btn, "Redo", { title: "Redo (Ctrl+Shift+Z)", disabled: () => at === history.length - 1, onClick: () => { redo(); update(); } }),
      ),
      p(s.stats, () => `${history.length} snapshots · each a plain array of ${SIZE * SIZE} strings`),
      // Newest first. Rows are the snapshot objects: a new step builds one row, nothing else.
      div(s.entries, list(() => history.slice().reverse(), Entry)),
    ),
  );
}

// history.ts: the picture and its past. The picture is a plain array of color
// strings, one per pixel ("" is transparent). A snapshot is pixels.slice(), and
// undo copies an older snapshot back. No store, no immutable data: old states
// are just old arrays. Nothing here knows about the UI.

export const SIZE = 32;
const LIMIT = 100; // snapshots kept; the oldest are dropped first

export interface Snapshot {
  label: string;
  pixels: string[];
}

// The starter picture: one string per row, one letter per pixel.
const INK: Record<string, string> = { k: "#1f2937", r: "#ef4444", w: "#ffffff", s: "#fde68a" };
const MUSHROOM = [
  ".....kkkkkk.....",
  "...kkrrrrrrkk...",
  "..krwwrrrrrrrk..",
  ".krwwwwrrrrwwrk.",
  ".krwwwwrrrwwwwk.",
  "krrrwwrrrrwwwwrk",
  "krrrrrrwwrrwwrrk",
  "krrrrrwwwwrrrrrk",
  "krrrrrwwwwrrrrrk",
  ".kkkkkkkkkkkkkk.",
  "...kssssssssk...",
  "...kssksskssk...",
  "...kssksskssk...",
  "...kssssssssk...",
  "....kssssssk....",
  ".....kkkkkk.....",
];

export const blank = () => Array<string>(SIZE * SIZE).fill("");

export function mushroom() {
  const px = blank();
  const edge = (SIZE - MUSHROOM.length) / 2; // the sprite is square: the same margin on every side
  MUSHROOM.forEach((row, y) => [...row].forEach((ch, x) => { px[(edge + y) * SIZE + edge + x] = INK[ch] ?? ""; }));
  return px;
}

export const pixels = mushroom();
export const history: Snapshot[] = [{ label: "Mushroom", pixels: pixels.slice() }];
export let at = 0; // the snapshot that `pixels` matches

/** Saves the picture as a new step. A step that changed nothing is not saved. */
export function commit(label: string) {
  if (pixels.every((c, i) => c === history[at].pixels[i])) return;
  history.splice(at + 1); // a new step drops the undone ones
  history.push({ label, pixels: pixels.slice() });
  if (history.length > LIMIT) history.shift();
  at = history.length - 1;
}

/** Overwrites the picture in place: the array the cells read stays the same one. */
export const load = (next: string[]) => { pixels.splice(0, SIZE * SIZE, ...next); };

export function jump(i: number) {
  at = i;
  load(history[i].pixels);
}
export const undo = () => { if (at > 0) jump(at - 1); };
export const redo = () => { if (at < history.length - 1) jump(at + 1); };

const inside = (x: number, y: number) => x >= 0 && y >= 0 && x < SIZE && y < SIZE;
export const get = (x: number, y: number) => (inside(x, y) ? pixels[y * SIZE + x] : "");

/** Paints every pixel from (x0, y0) to (x1, y1), so a fast stroke leaves no gaps. Returns how many changed. */
export function line(x0: number, y0: number, x1: number, y1: number, color: string) {
  const steps = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0));
  let changed = 0;
  for (let i = 0; i <= steps; i++) {
    const t = steps === 0 ? 0 : i / steps;
    const x = Math.round(x0 + (x1 - x0) * t), y = Math.round(y0 + (y1 - y0) * t);
    if (inside(x, y) && pixels[y * SIZE + x] !== color) { pixels[y * SIZE + x] = color; changed++; }
  }
  return changed;
}

/** Flood fill, with a stack instead of recursion. Returns how many pixels changed. */
export function fill(x: number, y: number, color: string) {
  const from = get(x, y);
  if (!inside(x, y) || from === color) return 0;
  const stack = [[x, y]];
  let changed = 0;
  while (stack.length) {
    const [px, py] = stack.pop()!;
    if (!inside(px, py) || pixels[py * SIZE + px] !== from) continue;
    pixels[py * SIZE + px] = color;
    changed++;
    stack.push([px + 1, py], [px - 1, py], [px, py + 1], [px, py - 1]);
  }
  return changed;
}

// app.ts: the game. The loop is a setTimeout: each tick calls step() on the
// plain game object, then update() once. The snake is a list() of its cell
// objects, and step() makes the tail object the new head, so a tick moves one
// existing element to the front and builds nothing. "Segments built" counts
// mounts to prove it: it only goes up when the snake eats.
import "nuclo";
import { interval, level, newGame, step, turn, type Cell, type Dir } from "./game.ts";
import { s } from "./styles.ts";

let game = newGame();
let state: "ready" | "playing" | "paused" | "over" = "ready";
let best = 0;
let built = 0; // segment elements built, counted by their mount
let timer: ReturnType<typeof setTimeout> | undefined;
let swipe = { x: 0, y: 0 }; // where the last press on the board started

function tick() {
  if (step(game)) timer = setTimeout(tick, interval(game));
  else state = "over";
  best = Math.max(best, game.score);
  update();
}

function play() {
  state = "playing";
  clearTimeout(timer);
  timer = setTimeout(tick, interval(game));
  update();
}

function pause() {
  clearTimeout(timer);
  state = "paused";
  update();
}

function restart() {
  game = newGame(); // new cell objects: the list builds three new segments
  built = 0;
  play();
}

// Space, P and the middle of the pad.
const toggle = () => (state === "playing" ? pause() : state === "over" ? restart() : play());

function steer(dir: Dir) {
  if (state === "over") return;
  turn(game, dir);
  if (state !== "playing") play();
}

const KEYS: Record<string, Dir> = { arrowup: "up", w: "up", arrowdown: "down", s: "down", arrowleft: "left", a: "left", arrowright: "right", d: "right" };
const ARROWS: Record<Dir, string> = { up: "↑", left: "←", right: "→", down: "↓" };
const ANGLE: Record<Dir, string> = { right: "0deg", down: "90deg", left: "180deg", up: "-90deg" };

function onKeyDown(e: KeyboardEvent) {
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  const key = e.key.toLowerCase();
  if (KEYS[key]) steer(KEYS[key]);
  else if (key === " " || key === "p") toggle();
  else return; // Escape and the rest go on to the modal
  e.preventDefault(); // the modal steps examples on arrow keys, unless the event was handled
}

function Segment(cell: Cell) {
  const isHead = () => cell === game.snake[0];
  return div(
    s.segment,
    { class: () => cx(s.segment, isHead() ? s.head : null).className },
    // The position goes in `translate` and the heading in `rotate`, which
    // leaves `transform` free for the head's slide in from the neck.
    { style: () => ({ translate: `${cell.x * 100}% ${cell.y * 100}%`, rotate: isHead() ? ANGLE[game.dir] : "", animationDuration: `${interval(game)}ms` }) },
    on("mount", () => { built++; queueMicrotask(update); }),
    span(s.eye),
    span(s.eye),
  );
}

const Food = (food: Cell) => div(s.food, { style: { translate: `${food.x * 100}% ${food.y * 100}%` } });

const Overlay = (title: string, ...content: NodeModLike<"div">[]) => div(s.overlay, strong(title), ...content);

function Board() {
  return div(
    s.board,
    { tabIndex: 0, role: "application", "aria-label": "Snake: arrow keys or WASD steer, Space pauses" },
    on("mount", (el) => {
      el.focus({ preventScroll: true });
      // Leaving the example stops the loop. The game waits, paused, for the next visit.
      return () => { clearTimeout(timer); if (state === "playing") state = "paused"; built = 0; };
    }),
    {
      onKeyDown,
      onBlur: () => { if (state === "playing") pause(); },
      // Also runs after "Play again", whose button is gone by then: the focus comes back here.
      onClick: (e) => { e.currentTarget.focus(); if (state === "ready" || state === "paused") play(); },
      onPointerDown: (e) => { swipe = { x: e.clientX, y: e.clientY }; },
      onPointerMove: (e) => {
        if (e.pointerType !== "touch") return; // a mouse steers with the keyboard
        const dx = e.clientX - swipe.x;
        const dy = e.clientY - swipe.y;
        if (Math.hypot(dx, dy) < 24) return;
        steer(Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? "right" : "left") : dy > 0 ? "down" : "up");
        swipe = { x: e.clientX, y: e.clientY }; // keep swiping to keep turning
      },
    },
    // A new food object is a new item: its element is built, and pops in.
    list(() => [game.food], Food),
    list(() => game.snake, Segment),
    when(() => state === "ready", Overlay("Snake", p("Press an arrow key or Space"), p(s.small, "WASD works too. On a touch screen, swipe or use the pad.")))
      .when(() => state === "paused", Overlay("Paused", p("Click to continue")))
      .when(() => state === "over", Overlay("Game over", p(() => `Score ${game.score} · best ${best}`), button(s.again, "Play again", { onClick: restart }))),
  );
}

const keepFocus = (e: MouseEvent) => e.preventDefault(); // a press on the pad leaves the focus on the board

const PadButton = (area: string, label: string, glyph: NodeModLike<"button">, press: () => void) =>
  button(s.padBtn, { style: { gridArea: area }, title: label, "aria-label": label, onPointerDown: press, onMouseDown: keepFocus }, glyph);

const Stat = (label: string, value: NodeModLike<"dd">) => div(s.stat, dt(label), dd(value));

export function SnakeGame() {
  return div(
    s.app,
    div(s.stage, Board()),
    aside(
      s.panel,
      dl(
        s.stats,
        // A new score is a new item too, so its element is built again and the flash replays.
        Stat("Score", list(() => [game.score], (n) => span(n > 0 ? s.flash : null, String(n)))),
        Stat("Best", () => String(best)),
        Stat("Length", () => String(game.snake.length)),
        Stat("Segments built", () => String(built)),
        Stat("Speed", () => String(level(game))),
      ),
      p(s.note, "Each tick the tail element becomes the head: one element moves, none is built. ", strong("Segments built"), " only goes up when the snake eats."),
    ),
    div(
      s.pad,
      ...(Object.keys(ARROWS) as Dir[]).map((dir) => PadButton(dir, `Turn ${dir}`, ARROWS[dir], () => steer(dir))),
      PadButton("mid", "Pause or play", () => (state === "playing" ? "❚❚" : "►"), toggle),
    ),
  );
}

// game.ts: the rules, with no DOM. A snake is an array of { x, y } cells, head
// first. step() moves it one cell by turning the tail object into the new
// head: the same objects, in a new order. Only eating adds an object.

export const GRID = 20; // cells per side
const PER_LEVEL = 5; // foods per speed level

export type Dir = "up" | "down" | "left" | "right";

export interface Cell {
  x: number;
  y: number;
}

export interface Game {
  snake: Cell[]; // head first
  food: Cell;
  dir: Dir;
  turns: Dir[]; // pressed but not taken yet: one per step
  score: number;
}

const DELTA: Record<Dir, Cell> = { up: { x: 0, y: -1 }, down: { x: 0, y: 1 }, left: { x: -1, y: 0 }, right: { x: 1, y: 0 } };
const OPPOSITE: Record<Dir, Dir> = { up: "down", down: "up", left: "right", right: "left" };

// Always the same start: the server and the browser render the same board.
export const newGame = (): Game => ({
  snake: [{ x: 6, y: 10 }, { x: 5, y: 10 }, { x: 4, y: 10 }],
  food: { x: 14, y: 10 },
  dir: "right",
  turns: [],
  score: 0,
});

export const level = (g: Game) => 1 + Math.floor(g.score / PER_LEVEL);
export const interval = (g: Game) => Math.max(60, 160 - (level(g) - 1) * 15); // ms per step

/**
 * Queues a turn. It is checked against the last queued one, so two quick
 * presses within one step both count, and a turn back into the neck is refused.
 */
export function turn(g: Game, dir: Dir) {
  const last = g.turns.at(-1) ?? g.dir;
  if (dir !== last && dir !== OPPOSITE[last] && g.turns.length < 3) g.turns.push(dir);
}

/** Moves one cell. Returns false when the game is over: a wall, the snake itself, or a full board. */
export function step(g: Game) {
  g.dir = g.turns.shift() ?? g.dir;
  const x = g.snake[0].x + DELTA[g.dir].x;
  const y = g.snake[0].y + DELTA[g.dir].y;
  const eats = x === g.food.x && y === g.food.y;
  const body = eats ? g.snake : g.snake.slice(0, -1); // the tail leaves its cell this step, unless the snake grows
  if (x < 0 || y < 0 || x >= GRID || y >= GRID || body.some((c) => c.x === x && c.y === y)) return false;
  if (eats) {
    g.snake.unshift({ x, y }); // the only new object
    g.score++;
    return placeFood(g);
  }
  const tail = g.snake.pop()!;
  tail.x = x;
  tail.y = y;
  g.snake.unshift(tail); // the tail object is the new head
  return true;
}

// Food goes on a random free cell. There is none left only when the snake fills the board.
function placeFood(g: Game) {
  const taken = new Set(g.snake.map((c) => c.y * GRID + c.x));
  const free = Array.from({ length: GRID * GRID }, (_, i) => i).filter((i) => !taken.has(i));
  if (free.length === 0) return false;
  const i = free[Math.floor(Math.random() * free.length)];
  g.food = { x: i % GRID, y: Math.floor(i / GRID) };
  return true;
}

